(window.GIM_TP=window.GIM_TP||{})["Z.Pinchas.1"]={"from":83,"a":[[["וּבְעוֹד דְּהִיא קְשִׁירָא בִּידַיְיהוּ, אִינּוּן מְלַחֲשֵׁי בְּקַלֵיהוֹן, וְאִיהִי מְצַפְצְפָא בַּהֲדַיְיהוּ, וּפַרְחַת לְעֵילָּא, וְנַחְתַּת. וְכָל אִינּוּן בְּנִין דִּתְחוֹת גַּדְפֵּי אִמְּהוֹן, כֵּיוָן דְּשַׁמְעֵי הַהוּא צִפְצֻפָא דְּאַחֲתְהוֹן, וּלְחִישׁוּ דְּהַהוּא קָלָא, מִיַּד נַפְקֵי מִתְּחוֹת גַּדְפָהָא דְּאִמְּהוֹן, וּפַרְחֵי לְגַבֵּי הַהוּא צִפּוֹרָא, וְיִשְׂרָאֵל נַטְלֵי לוֹן, וְאַחְדֵּי בְּהוּ. וְאִלְמָלֵא הַהוּא צִפּוֹרָא דְּקָא אַחְדֵּי בְּקַדְמִיתָא, אִינּוּן לָא פַּרְחֵי לְגַבַּיְיהוּ לְעָלְמִין, וְלָא יַכְלִין לְאַחֲדָא בְּהוּ.","הֵיךְ צָדִין צֵידָה דְּהַאי צִפָּרָא קַדִּישָׁא. מְתַקְּנִין לְקָמָא מֵיכְלָא יַקִּירָא בְּחֶדְוָוה, וְכָל עִנּוּגִין, וְעָאלִין לְבֵי כְּנִשְׁתָּא וּלְבֵי מִדְרָשָׁא, וּמְצַפְצְפָן לְגַבָּהּ בְּקַל לְחִישׁוּ כַּדְּקָא יָאוּת. וְאִיהִי דִּמְטַמְּרָא תְּחוֹת גַּדְפָהָא דְּאִימָּא, זַקְפָת רֵישָׁא, וְחָמָאת פָּתוֹרִין מְתֻקְּנָן, וְצִפְצוּפִין לְגַבָּהּ כַּדְּקָא יָאוּת. נַפְקַת וּפַרְחַת לְגַבַּיְיהוּ כְּמָה דְּאִתְּמַר, וּבָה אֲחָדִין כָּל אִינּוּן בְּנִין.","וּמְשַׁלְּחִין לְהַהוּא דִּרְבִיעָא עָלַיְיהוּ וְאַזְלַת. בְּגִין דְּהָא מִן רְקִיעָא שְׁבִיעָאָה וּלְעֵילָּא, בַּמְכוּסֶּה מִמָּךְ אַל תִּדְרוֹשׁ. שָׁלַח לֵיהּ, דְּלָא תִּיכוֹל לְאַדְבְּקָה וְעַל דָּא כְּתִיב, (דברים כ״ב:ז׳) שַׁלֵּח תְּשַׁלַּח וְגוֹ'.","מִקְרָא קֹדֶשׁ, דָּא קְרִיאָה וְצִפְצוּפָא, דְּעַבְדִּין לְהַהוּא צִפָּרָא קַדִּישָׁא בְּקַדְמִיתָא. וְכֵיוָן דְּאַחְדִּין בָּהּ שְׁאַר יוֹמִין, אִקְרוּן מִקְרָאֵי קֹדֶּשׁ. הַאי צִפָּרָא אִקְרֵי קֹדֶשׁ, דִּכְתִּיב, כִּי קֹדֶשׁ הִיא לָכֶם. וּבְגִין דְּאִיהִי קֹדֶשׁ, אִיהִי קָרְאָה לְכוּלְהוּ וְאַתְיָין לְגַבָּהּ. וּבְגִין כַּךְ אִקְרוּן מִקְרָאֵי קֹדֶשׁ.","אִיהִי קָרְאָה, וְיִשְׂרָאֵל מְצַפְצְפָן בַּהֲדָהּ, וּקְרָאָן אוּף הָכִי. וְעַל דָּא אִינּוּן אַתְיָין לְגַבַּיְיהוּ, וְאַחְדֵּי בְּהוּ. בְּגִין כַּךְ (ויקרא כ״ג:ד׳) אֵלֶּה מוֹעֲדֵי יְיָ מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אוֹתָם. מִקְרָאֵי קֹדֶשׁ, בְּצִפְצוּפָא דִּלְּהוֹן, וּבְהַהוּא צִפָּרָא קַדִּישָׁא קֹדֶשׁ, דְּקָרָא לוֹן.","\u0003רעיא מהימנא\u0004 אָמַר רַעְיָא מְהֵימָנָא, מִלִּין אִלֵּין, כַּמָה סְתִימִין אִינּוּן, לְמַאן דְּלָא יָדַע, וְגַלְיָין לְמַאן דְּיָדַע בְּהוּ. וַדַּאי הַהוּא צִּפּוֹרָא אִיהוּ שְׁכִינְתָּא. קֵן דִּילָהּ, דָּא בֵּי מַקְדְּשָׁא. וְיִשְׂרָאֵל אִינּוּן אֶפְרוֹחִין, דְּאִימָּא יָתְבָא עָלַיְיהוּ. הֲדָא הוּא דִכְתִיב, (דברים כ״ב:ו׳) וְהָאֵם רוֹבֶצֶּת עַל הָאֶפְרוֹחִים, וְאִינּוּן מָארֵי מִשְׁנָה, דְּפַרְחִין בְּפִקּוּדִין דִּילָהּ. אוֹ בֵיצִּים, אִינּוּן מָארֵי מִקְרָא.","וּבְזִמְנָא דְּחָבוּ יִשְׂרָאֵל, וְאִתְחָרִיב בֵּי מַקְדְּשָׁא, מַה כְּתִיב. שַׁלֵּח תְּשַׁלַּח אֶת הָאֵם, הֲדָא הוּא דִכְתִיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְאִינּוּן מָארֵי שִׁיתָא סִדְרֵי מִשְׁנָה כְּתִיב בְּהוּ, וְאֶת הַבָּנִים תִּקַּח לָךְ. דְּאִינּוּן שִׁית, מִסִּטְרָא דְּשִׁית בְּנִין דִּתְחוֹת אִימָּא עִלָּאָה, דְּאִינּוּן בְּשִׁית תֵּיבִין דִּקְרִיאַת שְׁמַע. אוֹ בְּשִׁית סִדְרֵי מִשְׁנָה, אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט וּבִלְבַד שֶיְכַוִּין לִבּוֹ לַשָּׁמַיִם. וְקַשְׁרִין לוֹן בְּקִשְׁרִין דִּתְפִלִּין, עַל רֵישָׁא וְעַל דְּרוֹעָא.","וּבְמַאי נַטְלִין בְּנִין בְּכַמָּה צִּפְצּוּפִין דְּקַלִין דִּקְרִיאַת שְׁמַע. וּלְבָתַר לַחֲשִׁין בִּלְחִישׁוּ בִּצְּלוֹתָא דַּחֲשַׁאי, לְגַבֵּי אִימָּא וּבְרַתָּא, וְאִינּוּן ה' ה', וְנַחְתִּין לְגַבֵּיהּ ו', בְּקֶשֶׁר דִּילֵיהּ דְּאִיהוּ יו\"ד. וְשַׁרְיָא ה' עִלָּאָה, עַל ו', תְּפִלִּין עַל רֵישֵׁיהּ. ה' זְעֵירָא, נָחַת לְגַבֵּי י', דְּאִיהוּ קֶשֶׁר דְּה' עִלָּאָה, עַל רֹאשׁ ו', וְאִיהוּ ו', קֶשֶׁר עִמָּהּ בְּה' דְּיָד כֵּהָה.","וּבְגִין דָּא, אֶפְרוֹחִים מִסִּטְרָא דְּאָת ו', כָּלִיל ו' סִדְרֵי מִשְׁנָה. אוֹ בֵיצִּים, אִלֵּין. מָארֵי מִקְרָא, דְּאִתְּמַר עָלַיְיהוּ, בֶּן ה' שָׁנִים לְמִקְרֵא, וְדָא ה'. בְּנִין מִסִּטְרָא דְּבֶן יָ\"הּ, אִלֵּין מָארֵי קַבָּלָה. עָלַיְיהוּ אִתְּמַר (דברים כ״ב:ו׳) לֹא תִקַּח הָאֵם עַל הַבָּנִים.","וּמָארֵי קַבָּלָה, אִינּוּן מָארֵי תַּלְמוּד. וְאִתְּמַר עָלַיְיהוּ, (דברים ו) וְשִׁנַּנְתָּם. וְאוֹקְמוּהָ מָארֵי מָתְנִיתִין, אַל תִּקְרֵי וְשִׁנַּנְתָּם, אֶלָּא וְשִׁלַּשְׁתָּם, דְּאִינּוּן שְׁלִּישׁ בַּמִקְרָא, שְׁלִישׁ בַּמִּשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד. וְרָזָא דְּמִלָּה, (דברים כ״ב:ו׳) כִּי יִקָּרֵא קַן צִּפּוֹר לְפָנֶיךָ בַדֶּרֶךְ, בְּמָארֵי מִקְרָא. (שמות כ״ה:ל״א) וְעָשִׂיתָ מְנוֹרַת זָהָב טָהוֹר. הָא אוֹקְמוּהָ, וְעָשִׂיתָ מְנוֹרַת, כְּלָל. זָהָב, פְּרָט. מִקְשָׁה, כְּלָל. וְכַמָּה מִקְרָאִין מָארֵי מַתְנִיתִין, אִינּוּן מַרְבִּין וּמְמַעֲטִין, כְּגוֹן רִיבָּה וּמִיעֵט. אוּף הָכִי, מַרְבִּין, אַל תִּקְרֵי מַה. אֶלָּא מֵאָה. אוּף הָכִי, אַל תִּקְרֵי וְשִׁנַּנְתָּם, וְשִׁלַּשְׁתָּם. אֶלָּא וְדַרְשֵׁינָן מִנֵּיהּ, שְׁלִישׁ בַּמִקְרָא, שְׁלִישׁ בַּמִשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד. כִּדְאִיתָא בְּקִדּוּשִׁין.","אוּף הָכִי, (במדבר ז׳:א׳) בְּיוֹם כַּלֹּת מֹשֶׁה, כַּלַּת דַּרְשִׁינָן בֵּיהּ. אִי תֵּימָא דְּדַרְשֵׁינָן לוֹן מִנְּהוֹן. כֵּיצַּד מֵאַלְפָא בֵּיתָא, וְלָא מֵעַצְּמָן דְּאִינּוּן לֵית לוֹן רְשׁוּ, לְאוֹסָפָא, וְלָא לְמִגְרַע אוֹת מִנֵּיהּ, (דהיא ו') אוֹ לְאַחְלְפָא אָת דָּא בְּאָת אַחֲרָא. הָא כְּתִיב כַּלוֹת מָלֵּא בְּאוֹרַיְיתָא. מַאן יָהִיב לוֹן רְשׁוּת לְמִגְרַע אוֹת מִנֵּיהּ, דְּהוּא ו', הָא לָא אִית הָכָא מִלָּה דְּאִתְחַלָּיף בְּאַלְפָא בֵּיתָא. אֶלָּא עַל אִלֵּין תֵּיבִין חֲסֵרִין, דְּאִינּוּן מְלֵאִים. וּמְלֵאִים, דְּאִינּוּן חֲסֵרִים. וְעַל כָּל פֵּירוּשִׁין דְּיַכְלִין לְמֶעְבַּד לְקַשְׁטָא כַּלָּה בְּתַכְשִׁיטִין דִּילָהּ, קוּדְשָׁא בְּרִיךְ הוּא מָנֵּי לְמֶעְבַּד, כְּמָה דְּיֵימְרוּן, וּלְמֶהֱוִי מַאֲמִין לוֹן, הֲדָא הוּא דִכְתִיב, (דברים י״ז:י״א) עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ.","לְאוּמָן דְּחָתַךְ מָאנֵי לְבוּשִׁין דְּמַלְכוּתָא, וְעָבִיד מִנְּהוֹן חֲתִיכָן סַגִּיאִין, אִינּוּן דְּיַדְעִין אַתְרִין דְּחָסֵרִין אִלֵּין חֲתִיכוֹת, אוֹ אִלֵּין דְּמִשְׁתַּאֲרִין, אִינּוּן מְתַקְּנִין אִינּוּן לְבוּשִׁין, וְשָׁוְיָן אִינּוּן חֲתִיכוֹת דְּאִתּוֹסְפָן, בַּאֲתָר דְּמִעוּטִין, וַחֲתִיכוֹת דְּאִינּוּן מְעַטִין, מוֹסִיפִין עָלַיְיהוּ, וְהַאי אִיהוּ עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ.","וְאִי תֵּימָא, אִי כַּךְ הוּא, מַאי אִיהוּ דִּלְזִמְנִין טָעֵי חַד מִנַּיְיהוּ, וְיֵימָּא הַדְרֵי בִּי. אֶלָּא עַד דְּיָעַבְדֵי הוֹרָאָה מֵהַהִיא מִלָּה דְּחוֹלְקִין עָלָהּ, יָכִיל הַהוּא דְּאַקְשֵׁי עָלָהּ, לְמֵימַר הַדְרֵי בִּי. דְּלָא כָּל מְפָרְקֵי תַּכְשִׁיטִין דְּכַלָּה, יַדְעִין בַּחֲתִיכוֹת לְאָן אַזְלָן, עַד דִּיְהֵא פְּסָק עַל בּוּרְיֵיהּ, פִּרוּקִין דַּהֲלָכוֹת עַל בּוּרְיֵיהוֹן.","מְנוֹרָה, שֶׁבַע בּוֹצִּינִין דִּילָהּ, (אסתר ב׳:ט׳) אֵת שֶׁבַע הַנְּעָרוֹת הָרְאוּיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ. לָקֳבֵל שִׁי\"ן דִּתְלַת רָאשִׁין ש. וְשי\"ן דְּאַרְבַּע רָאשִׁין דִּתְפִילִין. וְאִינּוּן לָקֳבֵל ז' בִּרְכָאן דִּקְרִיאַת שְׁמַע, דְּאִינּוּן בַּשַּׁחַר מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲרֶיהָ. לְבָתַר, כַּהֲנָא רַבָּא בַּעֲבוֹדָה, דִּמְשַׁמֵּשׁ בְּכַנְפֵי מִצְּוָה, פַּעֲמוֹנִים וְרִמּוֹנִים, אִינּוּן קִשְׁרִין וְחוּלְיָין וְצִּיץ תְּפִילִּין, מִתַּמָּן וְאֵילָךְ (שמות ל׳:א׳) וְעָשִׂיתָ מִזְבֵּחַ מִקְטַר קְטֹרֶת.","פָּתַח רַעְיָא מְהֵימָנָא, (ד\"א רבי שמעון) וְאָמַר, כְּתִיב בְּפַרְשְׁתָּא דָּא, וְהִקְרַבְתֶּם אִשֶּׁה עוֹלָה לַיְיָ. וְאוֹקְמוּהָ, דְּעוֹלָה לָאִשִּׁים. וּבְגִין כָּךְ סָמַךְ עוֹלָה לְאִשֶּׁה. וְעוֹד אוֹקְמוּהָ, דְּלֵית עוֹלָה אַתְיָא אֶלָּא עַל הִרְהוּר הַלֵּב.","וַדַּאי, כָּל קָרְבְּנִין לָא אַתְיָין, אֶלָּא לְכַפְּרָא. כָּל קָרְבְּנָא וְקָרְבְּנָא, עַל כָּל אֵבָרִין דְּבַּר נָשׁ, כְּפוּם הַהוּא חֵטְא דְּהַהוּא אֵבֶר. עַל טִפִּין דְּמוֹחָא, (שמות י״ב:ל״ט) עוּגוֹת מַצּוֹת כִּי לֹא חָמֵץ. אִי זָרִיק טִפִּין קַדְמָאִין, קֹדֶם דְּאַחְמִיצּוּ, בַּאֲתָר דְּלָאו דִּילֵיהּ. וְעַל אִלֵּין דְּאַחְמִיצּוּ, וְזָרִיק לוֹן בַּאֲתָר דְּלָא אִצְּטְרִיךְ, צָּרִיךְ לְאַיְיתָאָה עָלַיְיהוּ לֶחֶם חָמֵץ, וְאִינּוּן לַחְמִי תּוֹדָה הָכִי הֲווֹ, מִנְּהוֹן חָמֵץ, וּמִנְּהוֹן מַצָּה. פָּרִים מִסִּטְרָא דְּדִינָא, כְּבָשִׂים וְאֵילִים וְעַתּוּדִים וְעִזִּים. בְּגִין דְּאִינּוּן אַנְפֵּי דְּשׁוֹר, כֻּלְּהוּ שְׁחִיטָתָן בַּצָּפוֹן, וְקִבּוּל דָּמָן בִּכְלֵי שָׁרֵת בַּצָּפוֹן.","שְׁחִיטָה וְקַבָּלָה וּזְרִיקָה כֻּלָּם בַּצָּפוֹן. לְבַסְּמָא מִדַּת הַדִּין, דְּאָתֵי לְבֵית דִּין מִסִּטְרָא דִּגְבוּרָה. בֵּית דִּין הַגָּדוֹל מִסִּטְרָא דִּגְבוּרָה, דְּתַמָּן בִּינָה. בֵּית דִּין הַקָּטָן, מִסִּטְרָא דְּמַלְכוּת. וְכָל אִינּוּן שׁוֹפְכֵי דָּמִים לְמִצְּוָה, אִינּוּן מִסִּטְרָא דִּגְבוּרָה.","וּמַה דְּאוֹקְמוּהָ, עוֹלַת שַׁבַּת בְּשַׁבַּתוֹ וְלָא בְּשַׁבָּת אָחֳרָא, בְּגִין דְּעָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ. דְּקָרְבָּן דּוֹחָה שַׁבַּת, וְאַדְלִיק אֵשׁ בְּשַׁבָּת, בְּגִין דְּאִיהוּ אֶשָּׁא קְדוֹשָׁה. דְּכָל אֵשׁ דְּקָרְבְּנִין אִיהוּ קֹדֶשׁ, וְשַׁבָּת קֹדֶשׁ, אֲחִידָן דָּא בְּדָא.","אֲבָל אֵשׁ דְּחוֹל, אָסִיר לְאַחֲדָא לֵיהּ בַּקֹּדֶשׁ, וּבְגִין דָּא מָנֵי לוֹן לְיִשְׂרָאֵל, (שמות ל״ה:ג׳) לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת. דְּהַאי אִיהוּ כִּלְאַיִם דְּטוֹב וָרָע. וּבְשַׁבָּת דְּשַׁלְטָא אִילָנָא דְּחַיִּי, דְּלֵית בֵּיהּ תַּעֲרוֹבֶת, (אסיר לאבערא ביה דחולין, דהאי אש דחולין דטומאה ולא דחולין דטהרה) וְחוּלִין דְּטָהֳרָה אָסִיר לְעָרְבָא בְּאֵשׁ דִּקְדוּשָּׁה. כָּל שֶׁכֵּן חוּלִין דְּטוּמְאָה, דְּאָסִיר לְעָרְבָא לוֹן בִּקְדוּשָּׁה. אוּף הָכִי כָּל קָרְבְּנִין, אִתְקְרִיאוּ בְּשַׂר קֹדֶשׁ. וְכָל קָרְבְּנִין דְּכָל מִין, אִית בְּהוֹן חוּלִין דְּטָהֳרָה, וְאִית בְּהוֹן קֹדֶשׁ וְקֹדֶשׁ הַקֳּדָשִׁים."],[[0,"ובעוד דהיא קשירא וכו':","ובעוד שהיא קשורה בידיהם, של ישראל, הם מלחשים בקולם, והיא מצפצפת עמהם, ופורחת למעלה, ויורדת. וכל אלו הבנים שהם תחת כנפי אמם, שהם חג\"ת נה\"י דז\"א, כיון ששומעים צפצוף ההוא של אחותם, המלכות, והלחש של קול ההוא של ישראל, מיד יוצאים מתחת כנפי אמם, ופורחים אל צפור ההיא, שהיא המלכות, וישראל לוקחים אותם ומתאחדים בהם. ולולא אותה הצפור שנאחזו בה תחילה, הם, החג\"ת נה\"י, לא היו פורחים אליהם לעולם, ולא יכלו להתאחד בהם."],[1,"היך צדין צידה וכו':","איך צודים ציד של צפור הקדושה הזו. הוא, שמתקנים לפניה מאכל יקר בשמחה, וכל מיני תענוגים, ובאים לבית הכנסת ולבית המדרש, ומצפצפים אליה בקול לחשים כראוי. והיא, הצפור, שמסתתרת תחת כנפי אמא, זוקפת ראשה, ורואה שלחנות ערוכים, והצפצופים שאליה, דהיינו התפלות, כראוי, היא יוצאת, מתחת כנפי אמא, ופורחת אליהם, כמו שלמדנו, ובה נאחזים כל אלו הבנים, שהם חג\"ת נה\"י דז\"א."],[2,"ומשלחין לההוא דרביעא וכו':","ומשלחים אותה שרובצת עליהם, דהיינו אמא, שהיא בינה, הרובצת על חג\"ת נהי\"מ, והולכת לה. משום שמרקיע השביעי, שהוא חסד, ולמעלה, דהיינו בג\"ר, במכוסה ממך אל תדרוש. על כן שלח אותה, את האם, שהיא בינה, שהיא מג\"ר, כי לא תוכל להשיגה. וע\"כ כתוב, שלח תשלח את האם ואת הבנים תקח לך. שפירושו, שתשלח את הבינה מלעיין בה, כי אין בה השגה, ואת הבנים, שהם חג\"ת נהי\"מ, תקח לך, כי בהם יש השגה."],[3,"מקרא קדש דא וכו':","מקרא קודש, זה הוא, הקריאה וצפצוף דהיינו התפלות, שינו עושים לצפור הקדושה ההיא, שהיא מלכות, בתחילה, ואח\"כ כיון שנאחזים בה שאר הימים, חג\"ת נה\"י, הם נקראים מקראי קדש, לשון רבים. כי צפור הזה נקרא קדש, שכתוב, כי קדש היא לכם, שסובב על מלכות, ע\"כ אומר היא, ומשום שהיא קדש, היא קוראת לכולם, לחג\"ת נה\"י, ובאים אליה, ומשום זה הם נקראים מקראי קדש."],[4,"איהי קראה וישראל וכו':","היא קראה, לחג\"ת נה\"י, וישראל מצפצפים עמה, ואף הם קוראים, וע\"כ המה באים אליהם ומתאחדים בהם. משום זה כתוב, אלה מועדי ה' מקראי קדש אשר \u0003תקראו אותם. מקראי קדש,\u0004 היינו על שם הצפצוף שלהם, ועל שם אותה הצפור הקדושה, שהיא קדש, הקורא אותם."],[4,"","ביאור המאמר. כי סו\"ה והאם רובצת על הבנים, ה\"ס הקטנות שאמא משפעת אל הבנים. כי תקון ראשון שהבינה מתקנת את זו\"ן שהם חג\"ת נהי\"מ, הוא העלאת המלכות אליה. שה\"ס הבאת ה \u0003י'\u0004 ב \u0003אור\u0004 הבינה ונעשה \u0003אויר,\u0004 שאז מתמעטת הבינה מכח המלכות לו\"ק חסר ג\"ר, ואחריה מתמעטות כן כל המדרגות וכולן מקבלות ו\"ק חסר ג\"ר, מחמת עלית המלכות לבינה של כל המדרגות. והשפעה זו נק' האם רובצת על הבנים. כי אם לא היו זו\"ן מקבלים הקטנות הזו מן הבינה לא היו ראוים לקבל שום מוחין. (כמ\"ש ב\"א דף ז' ד\"ה וכבר). וע\"כ נבחן זה, שחג\"ת נה\"י דז\"א, וכן המלכות עלו תחת כנפי הבינה, ומקבלים כך את הקטנות שלהם. אמנם בזמנים ומועדים צריכים ישראל בכח תפלותיהם ותענוג יו\"ט, להוריד המלכות והו\"ק דז\"א מן כנפי הבינה, ולהמשיך להם מוחין דגדלות מן הבינה."],[4,"","וז\"ש (באות תש\"פ) \u0003בחד צפרא דאשכחת בין גדפהא דאימא,\u0004 דהיינו המלכות המקבלת הקטנות מאמא, המכונה גדפהא דאמא, בסוד המלכות שעלתה לבינה, דהיינו ה \u0003י'\u0004 שנכנסה באור הבינה. ונעשה אויר. (כנ\"ל ויצא אות י\"ז) והמשכת הג\"ר מן הבינה למלכות, מכונה ציד. ויש ציד רע, שז\"ס \u0003יודע ציד,\u0004 שכתוב בעשו הרשע, משום שהיה ממשיך הג\"ר דשמאל, שאסור להמשיכם. אבל ישראל \u0003יודעים\u0004 לצוד \u0003ציד טוב.\u0004 שה\"ס להמשיך ו\"ק דחכמה המיוחדים בימין בחסדים ע\"י קו האמצעי. וז\"ש, \u0003וישראל ידעי למיצד צידא טבא רבא ויקירא,\u0004 כי הציד של ישראל ה\"ס \u0003צידה טבא,\u0004 ולא ציד רע מלא דינים כעשו, והוא \u0003רבא ויקירא,\u0004 דהיינו שהוא מוחין דגדלות היקרים. והוא ע\"י יחוד שמאל וימין בקו אמצעי, וע\"י זווג ז\"א ומלכות. וז\"ש, \u0003מה עבדי\u0004 וכו' \u0003מלחשו לגבה לחישו בתר לחישו,\u0004 דהיינו שמעלים מיין נוקבין ע\"י תפלותיהם להמשיך הארה עליונה להוציא הי' מאויר הבינה, ולהחזיר הג\"ר לבינה, שתשפיע אותם אל המלכות, שתחילה יוצא הקו שמאל של הבינה בסוד נקודת השורק (כנ\"ל ב\"א ט\"ו ד\"ה ההיא) והמלכות מקבלת ממנו הארת החכמה דשמאל שנקראת ראש, וז\"ש (באות תשפ\"א) \u0003וההוא צפורא דחייש לאינון לחישין\u0004 וכו' \u0003זקיף רישא,\u0004 דהיינו שיוצאת מקטנות אמא, ומקבלת ג\"ר דשמאל הנקרא ראש. וז\"ש, \u0003ופרחת לגבייהו, ונפקת מתחות, גדפהא דאימא,\u0004 שיצאה מקטנות אמא, אבל לגדלות ממש עוד לא באה, להיותה בג\"ר דשמאל, שהן מוחין דאחורים. וז\"ש, \u0003כיון דישראל נטלי לה, אתקיפו בה, ולחשין לה, וקשרין לה בקשורא דלא תפרח ותזיל,\u0004 כלומר שהם מעלים מ\"ן ע\"י תפלותיהם, בכדי למעט אותה מג\"ר דשמאל, ע\"י הגילוי דמסך דחירק. וז\"ש \u0003אתקיפו בה,\u0004 שהמסך דחירק הוא קשר שהמלכות תתקשר תחת היסוד דז\"א, שז\"ש \u0003וקשרין לה בקשורא דלא תפרח ותזיל,\u0004 שלא תוכל לפרוח מלשוב לבחינת ג\"ר דשמאל, שישראל אין להם חלק שם. וז\"ש \u0003מיד נטלי לה ישראל בההוא קשורא, ואיהי בעאת למפרח ולמיזל ולא יכילת למיזל לה,\u0004 כי המסך דחירק ממעט הג\"ר דשמאל, באפן שאינה יכולה עוד לשוב אליהם (כנ\"ל לך י\"ג ד\"ה ונתבאר) וז\"ש \u0003ולא יכילת למיזל לה.\u0004"],[4,"","ואחר זה שהמלכות נתמעטה עד לנקודה תחת היסוד, צריכים להעלותה להיכל או\"א, שתבנה שם בנין חדש, שתהיה ראויה להזדווג עם ז\"א פנים בפנים, שזסו\"ה, ויבן ה' אלקים את הצלע וגו'. וז\"ש (באות תשפ\"ב) \u0003ובעוד דחיא קשירא בידייהו,\u0004 דהיינו בעוד שהיא במיעוטה, \u0003אינון מלחשין בקליהון\u0004 וכו' דהיינו שמעלים מ\"ן ע\"י תפלותיהם, \u0003ופרחת לעילא\u0004 דהיינו שעולה להיכל או\"א להבנות מחדש, \u0003ונחתת,\u0004 ויורדת, כשהוא בנויה ומתוקנת להתחבר עם ז\"א פנים בפנים. וז\"ש, \u0003וכל אינון בנין דתחות גדפי אמהון,\u0004 דהיינו ו\"ק דז\"א, שהם חג\"ת נה\"י, שהיו מקבלים קטנות הבינה, הנקראת גדפי אמהון, כנ\"ל, \u0003כיון דשמעי ההוא צפצפא דאחתהון ולחישו דההוא קלא,\u0004 דהיינו קול תפלות ישראל, והשירה של המלכות, שה\"ס המ\"ן שהם מעלים לז\"א, \u0003נפקי מתחות גדפהא דאמהון,\u0004 יוצאים גם הם מקטנות דאמא, \u0003ופרחי לגבי ההוא צפורא,\u0004 והם פורחים ומתחברים עם המלכות פנים בפנים. \u0003וישראל נטלי לון,\u0004 שמקבלים המוחין דז\"א ומלכות, \u0003ואחדי בהו,\u0004 ומתאחדים בהם. \u0003ואלמלא ההוא צפורא דקא אחדי בקדמיתא אינון לא פרחי לגבייהו לעלמין.\u0004 כי החסדים מקובלים מז\"א. והחכמה מקובלת מן המלכות ביחוד (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד כמה) וכל זמן שאין לישראל חכמה, נבחנים החסדים שמקבלים רק לבחינת ו\"ק בלי ראש. ולפיכך מחויבים לקבל תחילה החכמה מן המלכות, ואח\"כ יכולים לקבל החסדים דז\"א שהם בחינת ג\"ר. ונמצא \u0003שאלמלא ההוא צפורא דקא אחדי בקדמיתא,\u0004 שאם לא היו מקבלים חכמה תחילה מצפור ההיא שהיא המלכות, \u0003אינון לא פרחי לגבייהו לעלמין,\u0004 לא היו החג\"ת נה\"י דז\"א פורחים לישראל לעולם. כי היו כך ו\"ק בלי ראש."],[4,"","ולא עוד, אלא מטרם שחג\"ת נה\"י דז\"א מתיחדים עם המלכות, אין אפילו בהם עצמם בחינת חכמה, כי ז\"א דבוק תמיד בג\"ר דבינה, שהם חסדים מכוסים. ולפיכך אין הם נקראים מקראי קדש, אשר קדש פירושו ג\"ר, אלא אחר שז\"א מתיחד עם המלכות. וז\"ש (באות תשפ\"ה) \u0003ובגין דאיהי קדש, איהי קראה לכולהו ואתיין לגבה,\u0004 דהיינו שחג\"ת נה\"י דז\"א מתיחדין עמה, \u0003ובגין כך אקרון מקראי קדש,\u0004 שמשום שמתיחדים עם המלכות הם נקראים מקראי קדש, דהיינו שיש בהם ג\"ר כנ\"ל."],[5,"אמר רעיא מהימנא וכו':","דברים אלו, כמה סתומים הם למי שאינו יודע, והם גלוים למי שיודע אותם. ודאי \u0003צפור\u0004 ההיא זו היא השכינה. הקן שלה היא בית המקדש, ששם שרתה השכינה. וישראל הם \u0003האפרוחים\u0004 שהאם, שהיא השכינה, יושבת עליהם. ז\"ש, והאם רובצת על האפרוחים, והם בעלי משנה, שפורחים במצותיה. \u0003או ביצים,\u0004 הם בעלי מקרא."],[6,"ובזמנא דחבו ישראל וכו':","ובזמן שחטאו ישראל. ונחרב בית המקדש, מה כתוב, שלח תשלח את האם. שהיא השכינה. ז\"ש ובפשעכם שלחה \u0003אמכם.\u0004 ובאלו בעלי ששה סדרי משנה, כתוב בהם, ואת הבנים תקח לך. שהם ששה סדרים, מצד ששה הבנים, חג\"ת נה\"י, שהם תחת אמא עלאה, שהיא בינה, שהם מרומזים בשש מלות של קריאת שמע, או בששה סדרי משנה. אחד המרבה ואחד הממעיט, ובלבד שיכוין לבו לשמים. דהיינו ליחד את המלכות עם ז\"א שנקרא שמים. וקושרים אותה בקשר של תפלין על הראש ועל הזרוע. (כמ\"ש להלן באות תשפ\"ט)."],[6,"","פירוש. \u0003ביצים,\u0004 הם מארי מקרא, שה\"ס אור הנפש. \u0003אפרוחים,\u0004 הם מארי משנה, שה\"ס אור הרוח. ועדיין הם בקטנות שחסרים ג\"ר הנקראים גדלות. ובעלי קבלה ה\"ס אור הגדלות ונקראים \u0003בנים.\u0004 אמנם יש בחינת ו\"ק דגדלות, שהוא כעין היחוד שבשש מלות דק\"ש (כנ\"ל תרומה אות קכ\"ו ובהעלותך אות ג') ואלו יצאו מכלל אפרוחים, שהוא ו\"ק בלי ראש, ולבחינת בנים ממש עוד לא באו, שהרי אין להם רק ו\"ק דגדלות, וחסרים להם ג\"ר דגדלות וגם הם נקראים בנים. וז\"ש, \u0003ואינון מארי שיתא סדרי משנה,\u0004 כתוב בהם ואת \u0003הבנים\u0004 תקח לך, \u0003דאינון שית מסטרא דשית בנין דתחות אמא עלאה,\u0004 דהיינו ו\"ק דגדלות, שכבר אמא עלאה שורה עליהם, אלא רק מבחינת ו\"ק. וז\"ש, \u0003דתחות אמא עלאה. דאינון בשית תיבין דקריאת שמע,\u0004 שו\"ק דגדלות אלו נמשכים לז\"א, בשש מלות של קריאת שמע. וכן \u0003בשית סדרי משנה.\u0004 ונמצא שיש ב' בחינות במארי משנה, או בחינת רוח בלבד, שהיא קטנות, או בחינת ו\"ק דגדלות. ועליהם אומר, \u0003אחד המרבה,\u0004 שהוא ו\"ק דגדלות, \u0003ואחד הממעיט,\u0004 שהוא אור הרוח סחם, \u0003ובלבד שיכוין לבו לשמים.\u0004 ליחוד המלכות עם ז\"א שנקרא שמים."],[7,"ובמאי נטלין בנין וכו':","ובמה לוקחים הבנים. דהיינו הו\"ק דגדלות הנ\"ל. היינו בכמה צפצופין של קולות קריאת שמע. שביחוד ק\"ש ממשיכים ו\"ק דגדלות כנ\"ל. ולאחר כך מלחשים בלחש התפלה בחשאי, דהיינו בתפלת העמידה, אל האם, שהיא בינה, להמשיך הג\"ר דגדלות, ואל הבת, שהיא מלכות. והן \u0003ה' ה',\u0004 כי אמא היא ה' ראשונה דהויה, וברתא היא ה' אחרונה. והן יורדות אל ה \u0003ו',\u0004 שהיא ז\"א, בקשר שלו שהוא \u0003י'\u0004 דהויה, דהיינו חכמה. ו \u0003ה'\u0004 עליונה, שהיא בינה, שורה על \u0003ו'\u0004 שהיא ז\"א, שהוא סוד תפלין על ראשו, דהיינו המוחין דג\"ר. ו \u0003ה'\u0004 קטנה, שהיא מלכות, יורדת אל ה \u0003י'\u0004 דהויה, שהיא הקשר של ה' עליונה שעל ראש ה \u0003ו'.\u0004 שז\"ס אבא שהוא \u0003י'\u0004 דהויה, יסד ברתא, שהיא המלכות. והוא ה \u0003ו',\u0004 שהוא ז\"א, קשור עמה ב \u0003ה',\u0004 דיד כהה, דהיינו הקשר דתפלין של יד. באפן שה \u0003י'\u0004 דהויה ה\"ס הקשר דתפילין של ראש, שה\"ס אמא על ראש ה \u0003ו',\u0004 והיא הקשר של תפילין של יד, שהיא המלכות, ביד כהה דז\"א."],[8,"ובג\"ד אפרוחים מסטרא וכו':","ומשום זה \u0003אפרוחים\u0004 הם מצד אות \u0003ו',\u0004 דהיינו אור הרוח, הכולל ששה סדרי משנה, שהם חג\"ת נה\"י. \u0003או ביצים,\u0004 אלו הם בעלי מקרא, שהם בבחינת אור הנפש, שהיא מלכות, \u0003ה'\u0004 אחרונה דהויה. שנאמר עליהם בן \u0003ה'\u0004 שנים למקרא, וזה הוא המלכות שהיא \u0003ה'. בנים,\u0004 הם מצד בן י\"ה, דהיינו ז\"א שיש לו ג\"ר מן י\"ה, ואלו הם בעלי קבלה. עליהם נאמר, לא תקח האם על הבנים."],[9,"ומארי קבלה אינון וכו':","ובעלי קבלה הם בעלי תלמוד, ונאמר עליהם, ושננתם, והעמידו בעלי המשנה, אל תקרי ושננתם, אלא ושלשתם, שהם שליש במקרא, שליש במשנה, שליש בתלמוד. וסוד הדבר, כי יקרא קן צפור לפניך \u0003בדרך\u0004 היינו בעלי מקרא, \u0003בכל עץ\u0004 היינו בעלי משנה, \u0003או על הארץ,\u0004 אלו הם בעלי תלמוד. (כנ\"ל אות חשנ\"א) דהיינו שליש במקרא שליש במשנה ושליש בתלמוד. ואין לתמוה על מה שמשנים המלה ושננתם לושלשתם כי על הכתוב, ועשית מנורת זהב טהור, הנה העמידו, ועשית מנורת, הוא כלל זהב, הוא פרט, מקשה, הוא כלל. (עי' קדושין ל.) וכן כמה מקראות שבעלי המשנה מרבים וממעטים, כגון מה שאומרים ריבה ומיעט, וכן מרבים אות, ואומרים אל תקרי מה אלא מאה. כך כאן אנו אומרים, אל תקרי ושננתם אלא ושלשתם, ודרשינן ממנו, שליש במקרא שליש במשנה שליש בתלמוד, כמ\"ש בקדושין (דף ל' ע\"א)."],[10,"אוף הכי ביום וכו':","אף כך, ביום כלות משה שאנו דורשים בו כלה של משה (לעיל אות רנ\"ב) אם תאמר שאנו דורשים זה מהם, דהיינו מאותיות אלפא ביתא שבהמלה, אשר כלת היא אותיות כלה, ולא הוסיפו מעצמם, שהם אין להם רשות להוסיף או לגרוע אות ממנו, ולא להחליף אות זה באות אחר. אם כן, הרי כתוב בתורה כלות, מלא ב \u0003ו',\u0004 מי נתן להם רשות לגרוע אות ממנו, שהיא \u0003ו'\u0004 ולדרוש לשון כלת. שהרי אין כאן מלה להחליף בחלופי אלפא ביתות, כגון בא\"ת ב\"ש, אלא שגרעו ה \u0003ו'\u0004 מן המלה, ודרשו כמו שהיה כתוב כלת בלי \u0003ו'.\u0004 אלא שעל אלו מלות חסרות שדורשים כאלו היו מלאות, ומלות מלאות כאלו היו חסרות ועל כל מיני פרושים שיכולים לעשות. לקשט הכלה, שהיא התורה, בתכשיטין שלה, צוה לנו הקב\"ה לעשות כמו שיאמרו, ולהאמין אותם. ז\"ש על פי התורה אשר יורוך."],[11,"לאומן דחתך מאני וכו':","ודומה, לחייט שחתך לעשות לבושי מלכות, ועשה מהם חתיכות רבות, אלו שיודעים המקומות שחסרים אותן החתיכות ויודעים אותן החתיכות הנשארות, הם יכולים לעשות את הלבושים, כי משימים החתיכות שנתוספו, במקום שהן חסרות, וחתיכות שהן מועטות מוסיפים עליהם. וזה הוא, על פי התורה אשר יורוך."],[12,"ואי תימא אי וכו':","ואם תאמר, אם כך הוא, מה הוא שלפעמים טועה אחד מהם, ואומר אני מתחרט. ומשיב. אלא מטרם שפוסק הוראה באותו דבר שחולקים בו, יכול אותו שמקשה עליו, לומר אני מתחרט. כי לא כל המפרקים לעשות תכשיטי כלה יודעים לאן הולכות החתיכות, מטרם שהפסק הוא על מכונו, ומטרם שהתירוצים של ההלכות הם על מכונם."],[13,"מנורה, שבע בוצינין וכו':","המנורה, שבעת הנרות שלה, ה\"ס את שבע הנערות הראויות לתת לה מבית המלך, (שנתבארו לעיל ויקהל אות נ\"ג) שהן כנגד שין של ג' ראשים \u0003ש,\u0004 ושין של ארבע ראשים שבתפילין. דהיינו כנגד ז' ראשים שבב' שינין. והם כנגד ז' ברכות דקריאת שמע, שהם בשחרית, מברך שתים לפניה ואחת לאחריה, ובערב מברך שתים לפניה ושתים לאחריה. לאח\"כ כתוב המצוה, שכהן גדול בעבודה משמש בכנפי מצוה, שהם פעמונים ורמונים, שהם כמו הקשרים והחוליות שבציצית. והציץ, שהוא כמו תפילין. משם ואילך כתוב, ועשית מזבח מקטר קטרת."],[14,"פתח רעיא מהימנא וכו':","פרע\"מ ואמר, כתוב בפרשה זו, והקרבתם אשה עולה לה'. והעמידו אשר עולה היא לאשים, שכולה נשרפת באש, ומשום זה סמך עולה לאשה. ועוד העמידו שאין עולה באה אלא על הרהור הלב."],[15,"ודאי כל קרבנין וכו':","ודאי כל הקרבנות אינם באים אלא לכפרה, כל קרבן וקרבן מכפר על כל אבר ואבר של האדם כפי החטא שחטא באותו אבר. על טפות המוח, דהיינו החטא של מוציא זרע לבטלה, מביא, עוגות מצות כי לא חמץ. דהיינו אם זרק טפות ראשונות, מטרם שהחמיצו במקום שאינו שלו, דהיינו בלי נקבה אסורה, שבה מחמיצים הטפות. ועל אלו שהחמיצו, שזרק אותם במקום שאינו צריך, דהיינו בנקבה האסורה לו, ששם מחמיצים הטפות. הוא צריך להביא עליהם לחם חמץ. ואלו לחמי תודה כך היו, מהם חמץ ומהם מצה."],[16,"פרים מסטרא דדינא וכו':","פרים הם מצד הדין. וכן כבשים ואילים ועתודים ועזים כולם הם מצד הדין, משום שהם פני שור, שנאמר ופני שור מהשמאל, שהוא דין. כולם הם שחיטתם בצפון וקבול דמם בכלי שרת בצפון. שחיטה קבלה וזריקה כולם הם בצפון שהוא צד שמאל, כדי לבשם ולהמתיק מדת הדין, הבא לבית דין מצד הגבורה. בית דין הגדול, הוא מצד הגבורה ששם בינה, בית דין הקטן הוא מצד המלכות. וכל אלו שופכי דמים למצוה, הם מצד הגבורה."],[17,"ומה דאוקמוה עולת וגו':","ומה שהעמידו, עולת שבת בשבתו, לא בשבת אחר הוא משום שעבר יומו בטל קרבנו, ואין להשלימו בשבת אחר. הקרבן דוחה שבת. ומדליק אש בשבת, הוא משום שהוא אש קדושה. שכל אש הקרבנות קדושה, היא קדושה, ושבת קדושה אחוזות הן זו בזו."],[18,"אבל אש דחול וכו':","אבל אש של חול אסור לאחדו בקדש, דהיינו בשבת. ומשום זה צוה לישראל, לא תבערו אש בכל מושבותיכם ביום השבת. כי זה הוא כלאים של טוב ורע, כי בשבת, שולט בו עץ החיים, שאין בו תערובת של טוב ורע. וחולין של טהרה אסור לערב באש דקדושה, כל שכן חולין של טומאה שאסור לערב אותם בקדושה. אף כך כל הקרבנות נקראים בשר קדש, וכל הקרבנות של כל מין, יש בהם חולין דטהרה, ויש בהם קדש, וקדש הקדשים."]],[[0,"","וּבְעוֹד שֶׁהִיא קְשׁוּרָה בִּידֵיהֶם, הֵם לוֹחֲשִׁים בְּקוֹלָם, וְהִיא מְצַפְצֶפֶת עִמָּהֶם, וּמְעוֹפֶפֶת לְמַעְלָה וְיוֹרֶדֶת. וְכָל אוֹתָם בָּנִים שֶׁתַּחַת כַּנְפֵי אִמּוֹתֵיהֶם, כֵּיוָן שֶׁשּׁוֹמְעִים אוֹתוֹ הַצִּפְצוּף שֶׁל אֲחוֹתָם וּלְחִישַׁת אוֹתוֹ הַקּוֹל, מִיָּד יוֹצְאִים תַּחַת כַּנְפֵי אִמּוֹתֵיהֶם וּמְעוֹפְפִים אֵצֶל אוֹתָהּ הַצִּפּוֹר. וְיִשְׂרָאֵל לוֹקְחִים אוֹתָם וְאוֹחֲזִים בָּהֶם. וְאִם לֹא אוֹתָהּ צִפּוֹר שֶׁאוֹחֲזִים בָּהּ בַּתְּחִלָּה, לֹא הָיוּ אֵלּוּ מְעוֹפְפִים אֶצְלָם לְעוֹלָמִים, וְלֹא יְכוֹלִים לֶאֱחֹז בָּהֶם."],[1,"","אֵיךָ צָדִים צִידָה שֶׁל צִפּוֹר קְדוֹשָׁה זוֹ? מְתַקְּנִים לְפָנֶיהָ מַאֲכָל מְכֻבָּד בְשִׂמְחָה וְכָל תַּעֲנוּגִים, וְנִכְנָסִים לְבָתֵּי כְנֵסִיּוֹת וּלְבָתֵּי מִדְרָשׁוֹת, וּמְצַפְצְפִים אֵלֶיהָ בְּקוֹל לַחַשׁ כְּמוֹ שֶׁרָאוּי. וְהִיא נִסְתֶּרֶת תַּחַת כְּנָפֶיהָ שֶׁל אִמָּא, וְזוֹקֶפֶת רֹאשָׁהּ, וְרוֹאָה שֻׁלְחָנוֹת מְתֻקָּנִים וְצִפְצוּפִים אֵלֶיהָ כְּמוֹ שֶׁרָאוּי. יוֹצֵאת וּמְעוֹפֶפֶת אֶצְלָם כְּמוֹ שֶׁנִּתְבָּאֵר, וּבָהּ אֲחוּזִים כָּל אוֹתָם בָּנִים."],[2,"","וּמְשַׁלְּחִים לְאוֹתָהּ שֶׁרוֹבֶצֶת עֲלֵיהֶם, וְהוֹלֶכֶת. מִשּׁוּם שֶׁהֲרֵי מֵהָרָקִיעַ הַשְּׁבִיעִי וּלְמַעְלָה, בַּמְכֻסֶּה מִמְּךְ אַל תִּדְרֹשׁ. שָׁלַח אוֹתָהּ, שֶׁלֹּא תוּכַל לְהַשִּׂיגָהּ, וְעַל זֶה כָּתוּב (דברים כב) שַׁלֵּחַ תְּשַׁלַּח וְגוֹ'."],[3,"","מִקְרָא קֹדֶשׁ - זוֹהִי הַקְּרִיאָה וְהַצִּפְצוּף שֶׁעוֹשִׂים לְאוֹתָהּ צִפּוֹר קְדוֹשָׁה בָּרִאשׁוֹנָה. וְכֵיוָן שֶׁאֲחוּזִים בָּהּ שְׁאָר הַיָּמִים, נִקְרָאִים מִקְרָאֵי קֹדֶשׁ. צִפּוֹר זוֹ נִקְרֵאת קֹדֶשׁ, שֶׁכָּתוּב כִּי קֹדֶשׁ הִיא לָכֶם. וּמִשּׁוּם שֶׁהִיא קֹדֶשׁ, הִיא קוֹרֵאת לְכֻלָּם וּבָאִים אֶצְלָהּ, וּמִשּׁוּם זֶה נִקְרָאִים מִקְרָאֵי קֹדֶשׁ."],[4,"","הִיא קוֹרֵאת, וְיִשְׂרָאֵל מְצַפְצְפִים עִמָּהּ וְקוֹרְאִים גַּם כָּךְ. וְעַל זֶה הֵם בָּאִים אֶצְלָם וְאוֹחֲזִים בָּהֶם. וּמִשּׁוּם זֶה (ויקרא כג) אֵלֶּה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אֹתָם. מִקְרָאֵי קֹדֶשׁ - בַּצִּפְצוּפִים שֶׁלָּהֶם, וּבְאוֹתָהּ צִפּוֹר קְדוֹשָׁה. קֹדֶשׁ - שֶׁקּוֹרֵאת לָהֶם."],[5,"","אָמַר הָרוֹעֶה הַנֶּאֱמָן, דְּבָרִים אֵלּוּ כַּמָּה סְתוּמִים הֵם לְמִי שֶׁלֹּא יוֹדֵעַ, וְנִגְלִים לְמִי שֶׁיּוֹדֵעַ בָּהֶם. וַדַּאי אוֹתָהּ צִפּוֹר הִיא הַשְּׁכִינָה. הַקֵּן שֶׁלָּהּ זֶה בֵּית הַמִּקְדָּשׁ. וְיִשְׂרָאֵל הֵם הָאֶפְרוֹחִים, שֶׁאִמָּא יוֹשֶׁבֶת עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב (דברים לב) וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים, וְהֵם בַּעֲלֵי מִשְׁנָה שֶׁמְּעוֹפְפִים בַּמִּצְווֹת שֶׁלָּהּ. אוֹ בֵיצִים - אֵלּוּ בַּעֲלֵי מִקְרָא."],[6,"","וּבִזְמַן שֶׁחָטְאוּ יִשְׂרָאֵל וְנֶחֱרַב בֵּית הַמִּקְדָּשׁ, מַה כָּתוּב? שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם. זֶהוּ שֶׁכָּתוּב (ישעיה נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְאֵלּוּ בַּעֲלֵי שִׁשָּׁה סִדְרֵי מִשְׁנָה כָּתוּב בָּהֶם, וְאֶת הַבָּנִים תִּקַּח לָךְ. שֶׁהֵם שִׁשָּׁה מִצַּד שֶׁל שִׁשָּׁה בָנִים שֶׁתַּחַת הָאִמָּא הָעֶלְיוֹנָה, שֶׁהֵם בְּשֵׁשׁ תֵּבוֹת שֶׁל קְרִיאַת שְׁמַע, אוֹ בְּשִׁשָּׁה סִדְרֵי מִשְׁנָה, אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט וּבִלְבַד שֶׁיְּכַוֵּן לִבּוֹ לַשָּׁמַיִם. וְקוֹשְׁרִים אוֹתָם בְּקִשְׁרֵי הַתְּפִלִּין, עַל הָרֹאשׁ וְעַל הַזְּרוֹעַ."],[7,"","וּבַמֶּה לוֹקְחִים הַבָּנִים? בְּכַמָּה צִפְצוּפִים שֶׁל קוֹלוֹת שֶׁל קְרִיאַת שְׁמַע. וּבַסּוֹף לוֹחֲשִׁים בִּלְחִישַׁת הַתְּפִלָּה שֶׁבַּחֲשַׁאי אֵצֶל אִמָּא וּבִתָּהּ, וְאֵלּוּ ה' ה', וְיוֹרְדִים אֵצֶל ו' בַּקֶּשֶׁר שֶׁלּוֹ, שֶׁהִיא יוֹ\"ד. וְשׁוֹרָה ה' עֶלְיוֹנָה עַל ו', תְּפִלִּין עַל רֹאשׁוֹ. ה' קְטַנָּה יוֹרֶדֶת אֵצֶל י', שֶׁהִיא קֶשֶׁר שֶׁל ה' עֶלְיוֹנָה, עַל רֹאשׁ ו', וְהִיא ו', קֶשֶׁר עִמָּהּ בְּה' שֶׁל יָד כֵּהָה."],[8,"","וּמִשּׁוּם זֶה אֶפְרֹחִים, מִצַּד שֶׁל אוֹת ו', כּוֹלֵל שִׁשָּׁה סִדְרֵי מִשְׁנָה. אוֹ בֵיצִים - אֵלּוּ בַּעֲלֵי מִקְרָא שֶׁנֶּאֱמַר עֲלֵיהֶם בֶּן חָמֵשׁ שָׁנִים לְמִקְרָא, וְזוֹ ה'. בָּנִים מִצַּד שֶׁל בֶּן יָ\"הּ, אֵלּוּ בַּעֲלֵי קַבָּלָה. עֲלֵיהֶם נֶאֱמַר (דברים כב) לֹא תִקַּח הָאֵם עַל הַבָּנִים. וּבַעָלֵי קַבָּלָה אֵלּוּ בַּעֲלֵי תַלְמוּד, וְנֶאֱמַר עֲלֵיהֶם (שם ו) וְשִׁנַּנְתָּם. וּבֵאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, אַל תִּקְרֵי וְשִׁנַּנְתָּם אֶלָּא וְשִׁלַּשְׁתָּם. שֶׁהֵם שְׁלִישׁ בַּמִּקְרָא, שְׁלִישׁ בַּמִּשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד."],[9,"","וְסוֹד הַדָּבָר - (שם כב) כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךְ בַּדֶּרֶךְ, בְּבַעֲלֵי מִקְרָא. (שמות כה) וְעָשִׂיתָ מְנֹרַת זָהָב טָהוֹר. הֲרֵי בֵּאֲרוּהוּ, מְנֹרַת - כְּלָל. זָהָב - פְּרָט. מִקְשָׁה - כְּלָל. וְכַמָּה פְסוּקִים בַּעֲלֵי הַמִּשְׁנָה, אֵלּוּ מַרְבִּים וּמְמַעֲטִים, כְּגוֹן רִבָּה וּמִעֵט. אַף כָּךְ מַרְבִּים, אַל תִּקְרָא מָה אֶלָּא מֵאָה. אַף כָּךְ אַל תִּקְרָא וְשִׁנַּנְתָּם אֶלָּא וְשִׁלַּשְׁתָּם. וְדוֹרְשִׁים מִמֶּנּוּ, שְׁלִישׁ בַּמִּקְרָא, שְׁלִישׁ בַּמִּשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד. כְּמוֹ שֶׁיֵּשׁ בְּקִדּוּשִׁין."],[10,"","אַף כָּךְ (במדבר ז) בְּיוֹם כַּלֹּת מֹשֶׁה, וְדוֹרְשִׁים בּוֹ כַּלַּת. אִם תֹּאמַר שֶׁדּוֹרְשִׁים לָהֶם מֵהֶם - כֵּיצַד מֵאָלֶף בֵּית וְלֹא מֵעַצְמָם, שֶׁהֵם אֵין לָהֶם רְשׁוּת לְהוֹסִיף וְלֹא לִגְרֹעַ אוֹת מִמֶּנּוּ, (שהיא ו') אוֹ לְהַחֲלִיף אוֹת זוֹ בְּאוֹת אַחֶרֶת. הֲרֵי כָּתוּב כַּלּוֹת מָלֵא בַּתּוֹרָה, וּמִי נוֹתֵן לָהֶם רְשׁוּת לִגְרֹעַ אוֹת מִמֶּנָּה, שֶׁהִיא ו'? הֲרֵי אֵין כָּאן דָּבָר שֶׁמִּתְחַלֵּף בָּאָלֶף בֵּית. אֶלָּא עַל אֵלּוּ תֵּבוֹת חֲסֵרוֹת שֶׁהֵן מְלֵאוֹת, וּמְלֵאוֹת שֶׁהֵן חֲסֵרוֹת, וְעַל כָּל פֵּרוּשִׁים שֶׁיְּכוֹלִים לַעֲשׂוֹת לְקַשֵּׁט כַּלָּה בְּתַכְשִׁיטֶיהָ, הַקָּדוֹשׁ בָּרוּךְ הוּא מְצַוֶּה לַעֲשׂוֹת כְּמוֹ שֶׁיֹּאמְרוּ, וְלִהְיוֹת מַאֲמִין לָהֶם. זֶהוּ שֶׁכָּתוּב (דברים יז) עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךְ."],[11,"","לְאֻמָּן שֶׁחָתַךְ כְּלֵי לְבוּשִׁים שֶׁל הַמַּלְכוּת וְעָשָׂה מֵהֶם חֲתִיכוֹת רַבּוֹת - אֵלּוּ שֶׁיּוֹדְעִים הַמְּקוֹמוֹת שֶׁחֲסֵרִים אֵלּוּ הַחֲתִיכוֹת אוֹ אֵלּוּ שֶׁנִּשְׁאָרִים, אֵלּוּ מְתַקְּנִים אוֹתָם הַלְּבוּשִׁים, וְשָׂמִים אֵלּוּ הַחֲתִיכוֹת שֶׁנּוֹסָפוֹת בִּמְקוֹם הַחֲסֵרוֹת, וַחֲתִיכוֹת שֶׁהֵן מוּעָטוֹת, מוֹסִיפִים עֲלֵיהֶן, וְזֶהוּ שֶׁנֶּאֱמַר עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךְ."],[12,"","וְאִם תֹּאמַר, אִם כָּךְ הוּא, מַהוּ שֶׁלִּפְעָמִים טוֹעֶה אֶחָד מֵהֶם וְיֹאמַר חוֹזְרַנִי בִּי? אֶלָּא עַד שֶׁיַּעֲשׂוּ הוֹרָאָה מֵאוֹתוֹ דִּבּוּר שֶׁחוֹלְקִים עָלָיו, יָכוֹל אוֹתוֹ שֶׁהִקְשָׁה עָלָיו לוֹמַר חוֹזְרַנִי בִּי. שֶׁלֹּא כָּל אֵלּוּ שֶׁמְּפָרְקִים תַּכְשִׁיטֵי הַכַּלָּה יוֹדְעִים בַּחֲתִיכוֹת לְאָן הוֹלְכוֹת, עַד שֶׁיְּהֵא הַפְּסָק עַל בֻּרְיוֹ, תֵּרוּצֵי הַהֲלָכוֹת עַל בֻּרְיָם."],[13,"","הַמְּנוֹרָה, שִׁבְעַת נֵרוֹתֶיהָ הוּא שֶׁנֶּאֱמַר, (אסתרב) אֵת שֶׁבַע הַנְּעָרוֹת הָרְאֻיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ. כְּנֶגֶד שִׁי\"ן שֶׁל שְׁלֹשָׁה רָאשִׁים ש, וְאוֹת שִׁי\"ן שֶׁל אַרְבָּעָה רָאשִׁים שֶׁבַּתְּפִלִּין, וְהֵם כְּנֶגֶד שֶׁבַע בְּרָכוֹת שֶׁל קְרִיאַת שְׁמַע, שֶׁהֵן: בַּשַּׁחַר מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ. וְאַחַר כָּךְ כֹּהֵן גָּדוֹל בָּעֲבוֹדָה, שֶׁמְּשַׁמֵּשׁ בְּכַנְפֵי מִצְוָה. פַּעֲמוֹנִים וְרִמּוֹנִים - אֵלּוּ הַקְּשָׁרִים וְהַחֻלְיוֹת. וְצִיץ - תְּפִלִּין. מִשָּׁם וְאֵילָךְ, (שמות ל) וְעָשִׂיתָ מִזְבֵּחַ מִקְטַר קְטֹרֶת."],[14,"","פָּתַח הָרוֹעֶה הַנֶּאֱמָן (רבי שמעון) וְאָמַר, כָּתוּב בְּפָרָשָׁה זוֹ, וְהִקְרַבְתֶּם אִשֶּׁה עֹלָה לַה'. וּפֵרְשׁוּהָ, שֶׁעוֹלָה לָאִשִּׁים. וְלָכֵן סָמַךְ עוֹלָה לְאִשֶּׁה. וְעוֹד פֵּרְשׁוּהוּ, שֶׁאֵין עוֹלָה בָּאָה אֶלָּא עַל הִרְהוּר הַלֵּב."],[15,"","וַדַּאי, כָּל הַקָּרְבָּנוֹת לֹא בָאִים אֶלָּא לְכַפָּרָה. כָּל קָרְבָּן וְקָרְבָּן עַל כָּל אֵיבָרִים שֶׁל אָדָם כְּפִי אוֹתוֹ חֵטְא שֶׁל אוֹתוֹ אֵיבָר. עַל טִפּוֹת הַמֹּחַ נֶאֱמַר, (שמות יב) עֻגֹת מַצּוֹת כִּי לֹא חָמֵץ. אִם זוֹרֵק טִפּוֹת רִאשׁוֹנוֹת קֹדֶם שֶׁהֶחְמִיצוּ בְּמָקוֹם שֶׁלֹּא שֶׁלּוֹ. וְעַל אֵלּוּ שֶׁהֶחְמִיצוּ וְזָרַק אוֹתָן בְּמָקוֹם שֶׁלֹּא צָרִיךְ, צָרִיךְ לְהָבִיא עֲלֵיהֶן לֶחֶם חָמֵץ, וְאוֹתָם לַחְמֵי תוֹדָה כָּךְ הֵם - מֵהֶם חָמֵץ וּמֵהֶם מַצָּה. פָּרִים - מִצַּד הַדִּין, וְכֵן כְּבָשִׂים וְאֵילִים וְעַתּוּדִים וְעִזִּים. מִשּׁוּם שֶׁהֵם פְּנֵי שׁוֹר, כֻּלָּם שְׁחִיטָתָם בַּצָּפוֹן, וְקִבּוּל דָּמָם בִּכְלִי שָׁרֵת בַּצָּפוֹן."],[16,"","שְׁחִיטָה וְקַבָּלָה וּזְרִיקָה כֻּלָּם בַּצָּפוֹן, לְבַסֵּם מִדַּת הַדִּין שֶׁבָּאָה לְבֵית דִּין מִצַּד הַגְּבוּרָה. בֵּית דִּין הַגָּדוֹל מִצַּד הַגְּבוּרָה, שֶׁשָּׁם בִּינָה. בֵּית דִּין הַקָּטָן מִצַּד הַמַּלְכוּת. וְכָל אוֹתָם שׁוֹפְכֵי דָמִים לְמִצְוָה הֵם מִצַּד הַגְּבוּרָה."],[17,"","וּמַה שֶּׁבֵּאֲרוּהָ עֹלַת שַׁבַּת בְּשַׁבַּתּוֹ - וְלֹא בְּשַׁבָּת אַחֶרֶת, מִשּׁוּם שֶׁעָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ. שֶׁקָּרְבָּן דּוֹחֶה שַׁבָּת, וּמַדְלִיק אֵשׁ בְּשַׁבָּת, מִשּׁוּם שֶׁהוּא אֵשׁ שֶׁל קְדֻשָּׁה. שֶׁכָּל אֵשׁ שֶׁל קָרְבָּנוֹת הוּא קֹדֶשׁ, וְשַׁבָּת קֹדֶשׁ, אֲחוּזִים זֶה בָּזֶה."],[18,"","אֲבָל אֵשׁ שֶׁל חֹל אָסוּר לָתֵת לוֹ אֲחִיזָה בַּקֹּדֶשׁ, וּמִשּׁוּם זֶה צִוָּה לָהֶם לְיִשְׂרָאֵל, (שמותלה) לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבֹתֵיכֶם בְּיוֹם הַשַּׁבָּת. שֶׁזֶּהוּ כִּלְאַיִם שֶׁל טוֹב וָרָע. וּבְשַׁבָּת שֶׁשּׁוֹלֵט עֵץ הַחַיִּים, שֶׁאֵין בּוֹ תַּעֲרֹבֶת, (אסור להבעיר בו חלין, שזה האש של חלין של טמאה, ולא של חלין של טהרה) וְחֻלִּין שֶׁל טָהֳרָה אָסוּר לְעָרֵב בְּאֵשׁ שֶׁל קְדֻשָּׁה. כָּל שֶׁכֵּן חֻלִּין שֶׁל טֻמְאָה שֶׁאָסוּר לְעָרֵב אוֹתָם בִּקְדֻשָּׁה. אַף כָּךְ כָּל קָרְבָּנוֹת נִקְרָאִים בְּשַׂר קֹדֶשׁ, וְכָל קָרְבָּנוֹת שֶׁל כָּל מִין יֵשׁ בָּהֶם חֻלִּין שֶׁל טָהֳרָה, וְיֵשׁ בָּהֶם קֹדֶשׁ וְקֹדֶשׁ הַקְּדָשִׁים."]]],[["וְרָזָא, דְּאִית הֶפְרֵשׁ בֵּין קֹדֶשׁ לְקֹדֶשׁ, הֲדָא הוּא דִכְתִיב, (שמות כ״ו:ל״ג) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקּוֹדֶשׁ וּבֵין קֹדֶשׁ הַקֳּדָשִׁים. אוּף הָכָא אֶשּׁוֹת דְּקָרְבְּנִין, לָאו אִינּוּן שָׁוִין. דְּאֵשׁ שֶׁל גָּבוֹהַּ מְקוּדָּשׁ מֵאֵשׁ דְּקֹדֶשׁ דִּלְתַּתָּא. דְּאִתְקְרֵי אֵשׁ עֲצֵי הַקֹּדֶשׁ, אוֹ אֵשׁ בְּשַׂר הַקֹּדֶשׁ. וְאֶשָּׁא דְּקוּדְשָׁא, אִית בֵּיהּ הַפְרָשָׁה לְבֵין אֵשׁ הֶדְיוֹט. אַף עַל גַּב דְּאוֹקְמוּהָ עָלֵיהּ, דְּמִצְוָה לְהָבִיא מִן הַהֶדְיוֹט, אַף עַל גַּב דְּאִית אֵשׁ דְּקוּדְשָׁא, דְּכָל חַד צָרִיךְ לְאַתְרֵיהּ. וּמַתְלָא אִמְתִּילוּ יִשְׂרָאֵל קַדְמָאֵי לְהַאי רָזָא יִשְׂרָאֵל.","(נ\"א ישראל אמתילו להאי. דהא ישראל בכלל) אִתְקְרִיאוּ מְלָכִים כְּמָה דְּאוֹקְמוּהָ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. אֲבָל כַּד הֲווֹ עָאלִין לְבֵי מַקְדְּשָׁא, כָּל חַד שַׁרְיָיא בְּאַתְרֵיהּ, כַּדְּקָא יָאוּת לֵיהּ. אוּף הָכִי כָּל קָרְבְּנִין לָאו אִינּוּן שָׁוִין, דְּאַף עַל גַּב דִּבְכוּלְּהוּ כְּתִיב קָרְבָּן לַיְיָ, אִיהוּ פָּלִיג כֹּלָּא כָּל חַד וְחַד כַּדְּקָא יָאוּת. וְרָזָא דָּא, אִשְׁתְּמוֹדַע בְּפָרֵי הֶחָג, דַּהֲווֹ קְרִיבִין לוֹן יִשְׂרָאֵל קֳדָם יְיָ.","אָמַר בּוּצִינָא קַדִּישָׁא, קוּם רַעְיָא מְהֵימָנָא מִשְּׁנָתָךְ, דְּאַנְתְּ וַאֲבָהָן יְשֵׁנֵי עָפָר אִתְקְרוּן, דְּעַד כְּעַן הֲוִיתוּן מִשְׁתַּדְּלִין בְּאוֹרַיְיתָא, בְּאִינּוּן יְשֵׁנִים בַּמִשְׁנָה, דְּאִתְּמַר בְּהוֹן עַל הָאָרֶץ תִּישָׁן. וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה לַיהוָֹה. אַתּוּן אִינּוּן (בני) בִּכּוּרִים דִּשְׁכִינְתָּא, וּבְעוֹבָדִין דִּלְכוֹן, אִיהִי אִתְחַדְּשַׁת בִּצְלוֹתִין דַּאֲבָהָן בְּכָל יוֹמָא. דְּאוֹקְמוּהָ מָארֵי מַתְנִיתִין, תְּפִלּוֹת כְּנֶגֶד אָבוֹת תִּקְנוּם. וּבְקְרִיאַת שְׁמַע דְּאָמַר רַעְיָא מְהֵימָנָא שְׁמַע יִשְׂרָאֵל, וְאוֹקְמוּהָ כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע בְּכָל יוֹם, כְּאִלּוּ הוּא מְקַיֵּים (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה.","ודַּאי בִּצְלוֹתִין דִּלְכוֹן, בִּקְרִיאַת שְׁמַע דִּלְכוֹן, שְׁכִינְתָּא אִיהִי אִתְחַדְּשַׁת קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין דָּא, וְהִקְרַבְתֶּם מִנְחָה חֲדָשָׁה לַיהוָֹה. בִּצְלוֹתִין דְּאִינּוּן בַּאֲתָר דְּקָרְבְּנִין. בְּאָן קָרְבְּנִין דִּצְלוֹתִין אִיהִי מִתְחַדֶשֶׁת. בְּשָׁבוּעוֹתֵיכֶם. דְּהַיְינוּ שָׁבוּעוֹת, דְּבֵיהּ מַתַּן תּוֹרָה, וְאִתְקְרֵי חֲמִשִּׁים יוֹם לָעוֹמֶר. וּבֵיהּ שִׁבְעָה שָׁבוּעוֹת, מִסִּטְרָא דְּהַהוּא דְּאִתְּמַר בֵּיהּ, (תהילים קי״ט:קס״ד) שֶׁבַע בַּיוֹם הִלַּלְתִּיךָ, וְאִיהִי מַלְכוּת כַּלָּה. כְּלִילָא מִשְּׁבַע סְפִירָן, כְּלִילָא בַּבִּינָה, דְּאִיהִי אִתְפַּשְּׁטַת בְּה' סְפִירָאן לְחַמְשִׁין.","יְסוֹד כָּל, כָּלוּל מֵאִלֵּין חַמְשִׁין. כַּלָּ\"ה: כָּ\"ל ה'. כְּלִילָא מֵחֲמִשִׁים, כֻּלְּהוּ נִבְלָעִים בְּגוֹ חֲמִשִּׁים, חָכְמָה דְּאִיהִי, י' עִלָּאָה, מוּבְלַעַת בְּגוֹ חַמְשִׁין. ה' זִמְנִין עֶשֶׂר. ה' בִּינָה. י' חָכְמָה. עֶשֶׂר זִמְנִין ה' הַיְינוּ חַמְשִׁין וּבְחוּשְׁבָּן כָּ\"ל. וּבְחוּשְׁבָּן יָ\"ם. וְאִיהוּ יַם הַתּוֹרָה. מְקוֹרָא דִּילֵיהּ כֶּתֶר, דְּלֵית לֵיהּ סוֹף. שְׁאַר סְפִירָאן, אִתְקְרִיאוּ עַל שְׁמָהּ שִׁבְעַת יָמִים. וּמַלְכוּת יַם סוּף, סוֹף דְּכָל יָמִים.","וּבְגִין דָּא דְּאִינּוּן חַמְשִׁין, שֶׁבַע שָׁבוּעוֹת, מִנְחָתָם שְׁלֹשָׁה עֶשְׂרוֹנִים, וּשְׁנֵי עֶשְׂרוֹנִים. חֲמֵשׁ, דְּאִינּוּן חֲמֵשׁ זִמְנִין עֶשֶׂר. הֲדָא הוּא דִכְתִיב, וּמִנְחָתָם סֹלֶת בְּלוּלָה בַשֶּׁמֶן שְׁלֹשָׁה עֶשְׂרוֹנִים לַפָּר הָאֶחָד וּשְׁנֵי עֶשְׂרוֹנִים לָאַיִל הָאֶחָד עִשָּׂרוֹן עִשָּׂרוֹן לַכֶּבֶשׂ הָאֶחָד לְשִׁבְעַת הַכְּבָשִׂים. וְשִׁבְעַת הַכְּבָשִׂים, לָקֳבֵל (ויקרא כ״ג:ט״ו) שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת תִּהְיֶינָה. כָּל חַד עִם שִׁית יוֹמִין דִּילֵיהּ.","(במדבר כ״ט:א׳) וּבֶעָשׂוֹר לַחוֹדֶשׁ הַשְּׁבִיעִי, דְּאִיהוּ תִּשְׁרֵי. מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם, דָּא יוֹם הַכִּפּוּרִים. דְּאִיהוּ עֲשִׂירִי י', כָּלִיל מֵעֲשֶׂרֶת יְמֵי תְּשׁוּבָה. וְתַקִּינוּ בֵּיהּ ה' צְלוֹתִין, לְחַבְּרָא לָּהּ עִם ה'. (מאי מקרא קדש. יהיה לכם דא יום הכפורים דאיהי עשירי י', כליל מעשרת ימי תשובה. ותקינו ביה ה' צלותין, לחברא עם ה') מַאי מִקְרָא קֹדֶשׁ. לְאַפְרְשָׁא לֵיהּ מִשְּׁאַר יוֹמִין, דְּאִית בְּהוּ פּוּלְחָנָא דְּחוֹל. וּבְגִין דָּא, כָּל מְלֶאכֶת עֲבוֹדָה לֹא תַעֲשׂוּ.","דְּיוֹמִין דְּאִית בְּהוֹן מְלֶאכֶת חוֹל, אִינּוּן מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע. דְּאִתְהַפָּךְ מִמַּטֶּה לְנָחָשׁ, וּמִנָחָשׁ לְמַטֶּה. לְכָל חַד כְּפוּם עוֹבָדוֹי, וְדָא מְטַטְרוֹן מַטֶּה, נָחָשׁ, סָמָאֵל. אֲבָל בְּהַאי יוֹמָא דְּאִיהוּ יוֹם הַכִּפּוּרִים דְּאִתְקְרֵי קֹדֶשׁ, שַׁלְטָא אִילָנָא דְּחַיֵּי, דְּלָא אִשְׁתְּתַּף עִמֵּיהּ שָׂטָן וּפֶגַע רָע. וּמִסִּטְרֵיהּ (תהילים ה׳:ה׳) לֹא יְגוּרְךָ רָע. וּבְגִין דָּא, בֵּיהּ נַיְיחִין עַבְדִּין בְּאִילָנָא דְּחַיֵּי, (נ\"א ואשתתפן גביה) וּבֵיהּ נַפְקָן לְחֵירוּת, בֵּיהּ נַפְקֵי מִשֻׁלְשְׁלֵיהוֹן.","אִינּוּן דְּאִית עָלַיְיהוּ גְּזַר דִּין, בְּנֶדֶר וּבִשְׁבוּעָה, וּבְגִין דָּא תַּקִּינוּ לְמֵימַר בֵּיהּ, כָּל נִדְרֵי וְאֵיסָרֵי וְכוּ', כּוּלְהוֹן יְהוֹן שְׁבִיתִין וּשְׁבִיקִין לָא שְׁרִירִין וְלָא קַיָּימִין. וּבְגִין דָּא נֵדֶר דַּיְדוָֹ\"ד, דְּאִיהוּ תִּפְאֶרֶת. וּשְׁבוּעָה דַּאֲדֹנָי, דְּאִיהוּ מַלְכוּת. דְּעַבְדּוּ עַל גָּלוּתָא דִּלְהוֹן, בְּחָכְמָה וּבִינָה יְהוֹן שְׁבִיקִין וּשְׁבִיתִין לָא שְׁרִירִן וְלָא קַיָּימִין, (במדבר ט״ו:כ״ו) וְנִסְלַח לְכָל עֲדַת בְּנֵי יִשְׂרָאֵל. דְּחֶסֶד אִיהוּ מַיִם. גְּבוּרָה אֵשׁ. תִּפְאֶרֶת אַוִּיר. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין, הֵתֶּר נְדָרִים פּוֹרְחִים בַּאֲוִיר.","וּבְגִין דִּשְׁבוּעָה מִמַּלְכוּת, דְּאִיהִי לְתַתָּא מִינֵּיהּ. אוֹקְמוּהָ, נְדָרִים עַל גַּבֵּי שְׁבוּעוֹת עוֹלִים. וְעוֹד אוֹקְמוּהָ, כָּל הַנִּשְׁבַּע כְּאִילּוּ נִשְׁבַּע בַּמֶּלֶךְ עַצְמוֹ. וְכָל הַנּוֹדֵר כְּאִילּוּ נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ. הַמֶּלֶךְ עַצְמוֹ, אֲדֹנָי. חַיֵּי הַמֶּלֶךְ, יְדוָֹ\"ד. וּבְגִין דָּא (במדבר ל׳:ג׳) כִּי יִדּוֹר נֶדֶר לַיְדוָֹ\"ד."],[[0,"ורזא דאית הפרש וכו':","והסוד הוא, כי יש הפרש בין קדש לקדש, ז\"ש, והבדילה הפרכת לכם בין הקדש ובין קדש הקדשים. אף כאן, אשים של הקרבנות אינן שוות כי אש של גבוה יותר מקודש מאש הקדש שלמטה, שנקרא, אש עצי הקדש, או אש בשר הקדש. ואש הקדש יש בו הפרש לבין אש של הדיוט המובא על המזבח, אע\"פ שהעמידו עליה, שמצוה להביא אש מן ההדיוט, אע\"פ שיש אש קדוש על המזבח. כי כל אחד צריך למקומו."],[1,"ישראל אמתילו להאי","וכו': ישראל נמשלו לזה. כי ישראל בכלל נקראים מלכים, כמו שהעמידו, כל ישראל בני מלכים. אבל כשנכנסו לבית המקדש, כל אחד שרה במקומו כראוי לו הכהנים לבדם, ולוים לבדם, וישראל לבדם, אף כאן כל הקרבנות אינם שוין, אע\"פ שכתוב בכולם קרבן לה'. כי הוא הקב\"ה מחלק הכל כל אחד ואחד כראוי לו. וסוד זה נודע בפרי החג שהיו ישראל מקריבים לפני ה'. שהיה מחלק אותם לקיום ע' האומות."],[2,"אמר בוצינא קדישא","וכו': אמר המאור הקדוש, שהוא ר' שמעון, קום רעיא מהימנא משנתך, כי אתה והאבות נקראים ישיני עפר, כי עד עתה הייתם עוסקים בתורה באלו ישנים במשנה, שנאמר בהם ועל הארץ תישן (אבות פ\"ו). וביום הבכורים בהקריבכם מנחה חדשה לה'. אתם הם בכורים של השכינה, ובמעשים שלכם השכינה מתחדשת בתפלות האבות בכל יום. שהעמידו בעלי המשנה, תפלות כנגד אבות תקנום. ובקריאת שמע. שאמר רעיא מהימנא, דהיינו משה רבינו, שמע ישראל, והעמידו, כל הקורא קריאת שמע בכל יום, כאלו הוא מקיים והגית בו יומם ולילה."],[3,"ודאי בצלותא דלכון","וכו': ודאי בתפלה שלכם, ובקריאת שמע שלכם, השכינה מתחדשת לפני הקב\"ה. ומשום זה נאמר, והקרבתם מנחה חדשה לה', דהיינו בתפלות שהן במקום קרבנות. ובאיזה קרבנות, שהם תפלות, היא מתחדשת. היינו \u0003בשבועותיכם,\u0004 דהיינו שבועות, שבו מתן תורה, ונקרא חמשים יום לעומר, ובו שבעה שבועות, מצד אותו שנאמר בו שבע ביום הללתיך, שהיא מלכות שנקראת כלה, שהיא כלולה בשבע ספירות חג\"ת נהי\"מ, וכלולה בבינה, והיא מתפשטת בה' ספירות, חג\"ת נ\"ה, לחמשים."],[4,"יסוד כל כלול","וכו': יסוד שנקרא \u0003כל,\u0004 שבגי' חמשים, כלול גם כן מאלו החמשים, שהם חג\"ת נ\"ה שכל אחת כלולה מעשר, והמלכות נקראת \u0003כלה,\u0004 שהוא אותיות \u0003כל ה'\u0004 דהיינו \u0003ה'\u0004 ספירות הכלולות מחמשים. כולן נבלעות בתוך חמשים, חכמה שהיא \u0003י'\u0004 עליונה, מובלעת תוך חמשים, כי \u0003ה'\u0004 פעמים \u0003י'\u0004 היא חמשים, כי \u0003ה'\u0004 היא בינה, \u0003י'\u0004 חכמה, ויש י\"ה בחכמה, שמכפילים זו על זו והם חמשים, ויש י\"ה בבינה, שמכפילים \u0003י'\u0004 פעמים \u0003ה'\u0004 והם חמשים. והיא בחשבון \u0003כל,\u0004 כנ\"ל, ובחשבון \u0003ים,\u0004 כי הבינה נקראת \u0003ים,\u0004 שהוא בחשבון חמשים, והוא ים התורה, שמבינה הנקראת ים, תצא התורה, שהיא ז\"א. המקור שלה, היא כתר, שאין לו סוף. שאר ספירות שהם חג\"ת נהי\"מ, נקראים על שמה שבעת ימים. וים הוא בחשבון חמשים נמצא שבכל אחת יש חמשים. ומלכות נקראת ים סוף, על שם שהיא הסוף של כל הימים."],[5,"ובג\"ד דאינון חמשין","וכו': ומשום זה שכל אחת משבע שבועות היא חמשים, כנ\"ל, מנחתם שלשה עשרונים ושני עשרונים, שהם חמשה עשרונים שהם חמש פעמים עשר, כי כל עשרון הוא עשר וה' עשרונים הם חמשים. ז\"ש, ומנחתם סלת בלולה בשמן שלשה עשרונים לפר האחד ושני עשרונים לאיל האחד עשרון עשרון לכבש האחד לשבעת הכבשים. ושבעת הכבשים הם כנגד שבע שבתות תמימות תהיינה. שהן שבע מלכיות, כי מלכות נקראת שבת, וכל אחת עם ששה ימים שלו, שהם חג\"ת נה\"י, שהם בגי' חמשים עם יום השבועות."],[6,"ובעשור לחדש השביעי:","שהוא תשרי, מקרא קדש יהיה לכם, זהו יום הכפורים, שהוא עשירי, שהוא \u0003י',\u0004 שהוא כלול מעשרת ימי תשובה, והתקינו בו \u0003ה'\u0004 תפלות, כדי לחבר ה \u0003י'\u0004 עם ה \u0003ה',\u0004 דהיינו החכמה עם הבינה, מהו \u0003מקרא קדש.\u0004 היינו להבדיל אותו משאר הימים שיש בהם עבודה של חול, ומשום זה \u0003כל מלאכת עבודה לא תעשו.\u0004"],[7,"דיומין דאית בהון","וכו': כי הימים שיש בהם מלאכת חול, הם מצד עץ הדעת טוב ורע, שנתהפך ממטה לנחש ומנחש למטה לכל אחד לפי מעשיו, ומטטרון זה הוא מטה, וסמאל, הוא נחש. אבל ביום הזה שהוא יום הכפורים הנקרא קדש, שולט בו עץ החיים, שאינו מתחבר עמו השטן ופגע רע, ומצדו לא יגורך \u0003רע,\u0004 אלא כולו טוב. ומשום זה בו בעץ החיים ינוחו העבדים, ובו הם יוצאים לחירות, בו יוצאים מכבליהם."],[7,"","פירוש. ימות החול הם חג\"ת נה\"י דמטטרון, הנמשך מצד עץ הדעת טוב ורע שהוא המלכות וע\"כ נוהג בימות החול טוב ורע, אם זכה, הוא דבוק במטטרון, הנקרא מטה. אם לא זכה, הוא דבוק בסמאל שהוא רע הנקרא נחש. וכן מתהפכת השליטה על האדם לפי מעשיו. שז\"ס מטה המתהפך לנחש. כי המעשים מהפכים לו השליטה של טוב או רע. אבל ביוה\"כ הנקרא קדש, שולט עץ החיים, שהוא ז\"א, שכולו טוב ואין בו אחיזה לשטן וסמאל, והזוכה להתדבק ביוה\"כ שה\"ס עץ החיים, כבר יצא מכלל התהפכות ממטה לנחש, וזוכה להיות דבוק בו לנצחיות, ואין עוד לשום רע שליטה עליו. וזסו\"ה, לא יגורך \u0003רע.\u0004 הנאמר על הזוכה להדבק בעץ החיים. וז\"ש \u0003וביה נפקן לחירות ביה נפקי משלשליהון.\u0004 כי אז נעשים בני חורין ממלחמת הטוב ורע, ויוצאים מכבלי הסטרא אחרא לנצחיות."],[8,"אינון דאית עלייהו","וכו': אותם שיש עליהם גזר דין, בנדר ושבועה שלא לשנות הגזר דין, התקינו לומר משום זה, כל נדרי ואיסרי וכו' כולהון יהון שביתין ושביקין לא שרירין ולא קיימין, אלא שיתבטל גזר הדין מעליהם. ומשום זה, הנדר, הוא בשם הויה, שהוא תפארת, והשבועה היא בשם אדני, שהיא מלכות, שהם גרמו בעונותיהם על הגלות שלהם. הנה על ידי חכמה ובינה יהיו נעזבים ומושבתים, לא יהיו חזקים ולא יתקיימו, ונסלח לכל עדת בני ישראל. החסד הוא מים, הגבורה היא אש, התפארת הוא \u0003אויר\u0004, וכיון שהנדרים הם בתפארת, שהוא אויר, ע\"כ העמידו בעלי המשנה, התר נדרים פורחים באויר, שההתר מן חכמה ובינה פורח \u0003באויר\u0004 שהוא תפארת ומבטל משם את הנדר."],[9,"ובגין דשבועה ממלכות","וכו': ומשום שהשבועה היא ממלכות, שהיא למטה מנדר שהוא בתפארת, העמידו שנדרים עולים על השבועות, ועוד העמידו, כל הנשבע כאלו נשבע במלך עצמו, וכל הנודר כאלו נודר בחיי המלך. המלך עצמו, הוא \u0003אדנ\"י\u0004 שהיא מלכות. חיי המלך, הם \u0003הויה,\u0004 שהוא ז\"א, שממנו החיים אל המלך שהיא המלכות. ומשום זה כתוב, כי ידור נדר להויה. שהוא ז\"א."]],[[0,"","וְהַסּוֹד שֶׁיֵּשׁ הֶפְרֵשׁ בֵּין קֹדֶשׁ לְקֹדֶשׁ, זֶהוּ שֶׁכָּתוּב (שמות כו) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקְּדָשִׁים. אַף כָּךְ אִשֵּׁי הַקָּרְבָּנוֹת אֵינָם שָׁוִים. שֶׁאֵשׁ שֶׁל גָּבוֹהַּ מְקֻדָּשׁ מֵאֵשׁ שֶׁל קֹדֶשׁ שֶׁלְּמַטָּה, שֶׁנִּקְרָא אֵשׁ עֲצֵי הַקֹּדֶשׁ, אוֹ אֵשׁ בְּשַׂר הַקֹּדֶשׁ. וְאֵשׁ שֶׁל קְדֻשָּׁה יֵשׁ בּוֹ הַבְדָּלָה בֵּינוֹ לְבֵין אֵשׁ שֶׁל הֶדְיוֹט. אַף עַל גַּב שֶׁבֵּאֲרוּ עָלָיו שֶׁמִּצְוָה לְהָבִיא מִן הַהֶדְיוֹט אַף עַל גַּב שֶׁיֵּשׁ אֵשׁ שֶׁל קֹדֶשׁ, שֶׁכָּל אֶחָד צָרִיךְ לִמְקוֹמוֹ. וּמָשָׁל נִמְשְׁלוּ יִשְׂרָאֵל הָרִאשׁוֹנִים לְסוֹד זֶה יִשְׂרָאֵל."],[1,"","(ישראל נמשלו לזה. שהרי ישראל בכלל) נִקְרָאִים מְלָכִים, כְּמוֹ שֶׁבֵּאֲרוּהוּ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. אֲבָל כַּאֲשֶׁר הָיוּ עוֹלִים לְבֵית הַמִּקְדָּשׁ, כָּל אֶחָד שׁוֹרֶה בִּמְקוֹמוֹ כְּמוֹ שֶׁרָאוּי לוֹ. אַף כָּךְ כָּל הַקָּרְבָּנוֹת אֵינָם שָׁוִים, שֶׁאַף עַל גַּב שֶׁבְּכֻלָּם כָּתוּב קָרְבָּן לַה', הוּא מְחַלֵּק הַכֹּל כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁרָאוּי. וְסוֹד זֶה נוֹדָע בְּפָרֵי הֶחָג, שֶׁהָיוּ מַקְרִיבִים לָהֶם יִשְׂרָאֵל לִפְנֵי ה'."],[2,"","אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, קוּם רוֹעֶה נֶאֱמָן מִשְּׁנָתְךְ, שֶׁאַתָּה וְהָאָבוֹת נִקְרָאִים יְשֵׁנֵי עָפָר, שֶׁעַד כָּאן הֱיִיתֶם מִשְׁתַּדְּלִים בַּתּוֹרָה בְּאוֹתָם יְשֵׁנִים בַּמִּשְׁנָה, שֶׁנֶּאֱמַר בָּהֶם עַל הָאָרֶץ תִּישָׁן. וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה לַה'. אַתֶּם הֵם (בני) בִּכּוּרִים שֶׁל הַשְּׁכִינָה, וּבַמַּעֲשִׂים שֶׁלָּכֶם הִיא מִתְחַדֶּשֶׁת בַּתְּפִלּוֹת שֶׁל הָאָבוֹת בְּכָל יוֹם. שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, תְּפִלּוֹת כְּנֶגֶד אָבוֹת תִּקְּנוּם. וּבִקְרִיאַת שְׁמַע שֶׁאָמַר הָרוֹעֶה הַנֶּאֱמָן שְׁמַע יִשְׂרָאֵל, וּפֵרְשׁוּהָ כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע בְּכָל יוֹם כְּאִלּוּ הוּא מְקַיֵּם (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה."],[3,"","וַדַּאי בַּתְּפִלּוֹת שֶׁלָּהֶם, בַּקְּרִיאַת שְׁמַע שֶׁלָּכֶם, הַשְּׁכִינָה הִיא מִתְחַדֶּשֶׁת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם זֶה נֶאֱמַר וְהִקְרַבְתֶּם מִנְחָה חֲדָשָׁה לַה'. בַּתְּפִלּוֹת שֶׁהֵן בִּמְקוֹם הַקָּרְבָּנוֹת. בְּאֵילוּ קָרְבָּנוֹת שֶׁל הַתְּפִלּוֹת הִיא מִתְחַדֶּשֶׁת? בְּשָׁבֻעֹתֵיכֶם. כְּלוֹמַר שָׁבוּעוֹת, שֶׁבּוֹ מַתַּן תּוֹרָה, וְנִקְרָא חֲמִשִּׁים יוֹם לָעֹמֶר. וּבוֹ שִׁבְעָה שָׁבוּעוֹת, מִצַּד אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ. וְהִיא מַלְכוּת, כַּלָּה, כְּלוּלָה מִשֶּׁבַע סְפִירוֹת, כְּלוּלָה בְּבִינָה, שֶׁהִיא מִתְפַּשֶּׁטֶת בְּחָמֵשׁ סְפִירוֹת לַחֲמִשִּׁים."],[4,"","יְסוֹד כֹּל, כָּלוּל מֵאֵלּוּ הַחֲמִשִּׁים. כַּלָּ\"ה - כֹּ\"ל ה'. כְּלוּלָה מֵחֲמִשִּׁים, כֻּלָּם נִבְלָעִים בְּתוֹךְ חֲמִשִּׁים, חָכְמָה שֶׁהִיא י' עֶלְיוֹנָה מֻבְלַעַת בְּתוֹךְ חֲמִשִּׁים. ה' פְּעָמִים עֶשֶׂר. ה' - בִּינָה. י' - חָכְמָה. עֶשֶׂר פְּעָמִים ה', כְּלוֹמַר חֲמִשִּׁים בְּחֶשְׁבּוֹן כֹּ\"ל, וּבְחֶשְׁבּוֹן יָ\"ם, וְהוּא יָם הַתּוֹרָה. הַמָּקוֹר שֶׁלּוֹ כֶּתֶר, שֶׁאֵין לוֹ סוֹף. שְׁאָר הַסְּפִירוֹת נִקְרָאוֹת עַל שְׁמָהּ שִׁבְעַת יָמִים. וְהַמַּלְכוּת יַם סוּף, שֶׁהִיא סוֹף כָּל הַיָּמִים."],[5,"","וּמִשּׁוּם זֶה שֶׁהֵם חֲמִשִּׁים, שִׁבְעָה שָׁבוּעוֹת, מִנְחָתָם שְׁלֹשָׁה עֶשְׂרוֹנִים וּשְׁנֵי עֶשְׂרוֹנִים, חָמֵשׁ, שֶׁהֵם חָמֵשׁ פְּעָמִים עֶשֶׂר. זֶהוּ שֶׁכָּתוּב (במדבר כח) וּמִנְחָתָם סֹלֶת בְּלוּלָה בַשָּׁמֶן שְׁלֹשָׁה עֶשְׂרֹנִים לַפָּר הָאֶחָד (ו) שְׁנֵי עֶשְׂרֹנִים לָאַיִל הָאֶחָד, עִשָּׂרוֹן עִשָּׂרוֹן לַכֶּבֶשׂ הָאֶחָד לְשִׁבְעַת הַכְּבָשִׂים. וְשִׁבְעַת הַכְּבָשִׂים כְּנֶגֶד (ויקרא כג) שֶׁבַע שַׁבָּתוֹת תְּמִימֹת תִּהְיֶינָה. כָּל אֶחָד עִם שִׁשָּׁה הַיָּמִים שֶׁלּוֹ."],[6,"","וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי (במדבר כט) - שֶׁהוּא תִּשְׁרֵי. מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם - זֶה יוֹם הַכִּפּוּרִים, שֶׁהוּא עֲשִׂירִי, י', כָּלוּל מֵעֲשֶׂרֶת יְמֵי תְשׁוּבָה. וְתִקְּנוּ בוֹ חָמֵשׁ תְּפִלּוֹת, לְחַבֵּר אוֹתוֹ עִם ה'. (מהו מקרא קדש יהיה לכם, ' זה יום הכפורים שהוא עשירי, י', כלול מעשרת ימי תשובה. ותקנו בו חמש תפלות, לחברו עם ה') מַהוּ מִקְרָא קֹדֶשׁ? לְהַבְדִּילוֹ מִשְּׁאָר יָמִים שֶׁיֵּשׁ בָּהֶם עֲבוֹדָה שֶׁל חֹל. וּמִשּׁוּם זֶה, כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ."],[7,"","שֶׁיָּמִים שֶׁיֵּשׁ בָּהֶם מְלָאכָה שֶׁל חֹל, הֵם מִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע. שֶׁהִתְהַפֵּךְ מִמַּטֶּה לְנָחָשׁ, וּמִנָּחָשׁ לְמַטֶּה, לְכָל אֶחָד כְּפִי מַעֲשָׂיו. וְזֶה מְטַטְרוֹן מַטֶּה, נָחָשׁ, סָמָאֵל. אֲבָל בְּיוֹם זֶה, שֶׁהוּא יוֹם הַכִּפּוּרִים שֶׁנִּקְרָא קֹדֶשׁ, שׁוֹלֵט עֵץ הַחַיִּים, שֶׁלֹּא מִשְׁתַּתֵּף עִמּוֹ שָׂטָן וּפֶגַע רָע. וּמִצִּדּוֹ (תהלים ה) לֹא יְגֻרְךְ רָע. וּמִשּׁוּם זֶה יֵשׁ בּוֹ מְנוּחָה לַעֲבָדִים בְּעֵץ הַחַיִּים, (ומשתתפים אצלו) וּבוֹ יוֹצְאִים לַחֵרוּת, בּוֹ יוֹצְאִים מִשַּׁלְשְׁלוֹתֵיהֶם."],[8,"","אֵלּוּ שֶׁיֵּשׁ עֲלֵיהֶם גְּזַר דִּין בְּנֶדֶר וּבִשְׁבוּעָה, וּמִשּׁוּם זֶה הִתְקִינוּ לוֹמַר בּוֹ: כָּל נְדָרִים וְאִסּוּרִים וְכוּ', כֻּלָּם יִהְיוּ מֻשְׁבָּתִים וַעֲזוּבִים בְּלִי תֹקֶף וְלֹא קַיָּמִים. וּמִשּׁוּם זֶה נֶדֶר שֶׁל שֵׁם יְהֹוָ\"ה, שֶׁהִיא תִּפְאֶרֶת. וּשְׁבוּעָה - שֶׁל אֲדנָי, שֶׁהִיא מַלְכוּת. שֶׁעָשׂוּ עַל גָּלוּת שֶׁלָּהֶם, בְּחָכְמָה וּבִינָה יִהְיוּ נֶעֱזָבִים וּמֻשְׁבָּתִים לְלֹא תֹקֶף וּבְלִי קִיּוּם, (במדבר טו) וְנִסְלַח לְכָל עֲדַת בְּנֵי יִשְׂרָאֵל. שֶׁחֶסֶד הוּא מַיִם, וּגְבוּרָה אֵשׁ, וְתִפְאֶרֶת אֲוִיר. וּמִשּׁוּם זֶה בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, הֶתֵּר נְדָרִים פּוֹרְחִים בָּאֲוִיר."],[9,"","וּמִשּׁוּם שֶׁשְּׁבוּעָה מִמַּלְכוּת, שֶׁהִיא לְמַטָּה מִמֶּנּוּ, פֵּרְשׁוּהוּ, נְדָרִים עַל גַּבֵּי שְׁבוּעוֹת עוֹלִים. וְעוֹד פֵּרְשׁוּ, כָּל הַנִּשְׁבָּע כְּאִלּוּ נִשְׁבָּע בַּמֶּלֶךְ עַצְמוֹ, וְכָל הַנּוֹדֵר כְּאִלּוּ נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ. הַמֶּלֶךְ עַצְמוֹ - אֲדנָי. חַיֵּי הַמֶּלֶךְ - יְהֹוָ\"ה. וּמִשּׁוּם זֶה נֶאֱמַר (במדבר ל) כִּי יִדֹּר נֶדֶר לַיהֹוָ\"ה."]]],[["וְאוֹף הָכִי אִית רָזָא אַחֲרָא, חַיֵּי הַמֶּלֶךְ, חָכְמָה. הֲדָא הוּא דִכְתִיב, (קהלת ז׳:י״ב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. כָּל הַנּוֹדֵר בַּיְהוָֹה, דְּאִיהוּ תִּפְאֶרֶת. כְּאִילּוּ נוֹדֵר בַּחָכְמָה, דְּאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, חַיֵּי הַמֶּלֶךְ. וְכָל הַנִּשְׁבַּע בַּאדֹנָי, כְּאִילּוּ נִשְׁבַּע בַּמֶּלֶךְ עַצְמוֹ. עַצְמוֹ דָּא אִימָּא עִלָּאָה, כְּאִילּוּ נִשְׁבַּע בָּהּ, דְּאִיהִי (שמות כ״ד:י׳) עֶצֶם הַשָּׁמַיִם לָטוֹהַר. מִסִּטְרָא דְּחֶסֶד, (בראשית ב׳:כ״ג) עֶצֶם מֵעֲצָמַי. וּבָשָׂר מִבְּשָׂרִי, מִסִּטְרָא דִּגְבוּרָה, דָּא מַלְכוּת. וּבְחָכְמָה דְּאִיהִי חַיֵּי תִּפְאֶרֶת, אִיהוּ סָלִיק לְאִתְקְרֵי אָדָם, הֲדָא הוּא דִכְתִיב, (ישעיה מד) כְּתִפְאֶרֶת אָדָם.","וְאִתְּמַר בְּיוֹם הַכִּפּוּרִים. (ויקרא ט״ז:ל״א) וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם. וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם. תַּקִּינוּ בֵּיהּ ה' עִנּוּיִים, בְּגִין דְּתִתְלַבֵּן ה' זְעֵירָא בְּה' עִלָּאָה, דְּאִיהוּ ה' צְלוֹתִין. לְקַיֵּים בְּיִשְׂרָאֵל, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְהַאי אִיהוּ רָזָא דְּלָשׁוֹן שֶׁל זְהוֹרִית, בְּגִין דְּכָל חוֹבִין דְּיִשְׂרָאֵל מָטוּן לְגַבֵּי מַלְכוּת. וּתְשׁוּבָה דְּאִיהִי בִּינָה, מְלַבֶּנֶת לוֹן. בְּגִין דְּאִתְּמַר בָּהּ, (ויקרא ט״ז:ט״ז) הַשּׁוֹכֵן אִתָּם בְּתוֹךְ טוּמְאוֹתָם. וְד' בִּגְדֵי לָבָן, וְד' בִּגְדֵי זָהָב לְמִלְבַּשׁ, יְאֲהדוָֹנָהי.","וְתַקִּינוּ לִתְקוֹעַ שׁוֹפָר בְּיוֹם הַכִּפּוּרִים, לְסַלְּקָא קוֹל דְּאִיהוּ ו', לְחֵרוּת. דְּאִתְּמַר בָּהּ, (ישעיה סג) בְּכָל צָרָתָם לוֹ צָר, בְּא', וּבְו', קְרֵי וּכְתִיב. וַעֲבוֹדַת יוֹם הַכִּפּוּרִים אִיהִי בַּאֲרִיכוּת, וְאִיהִי כְּלִילָא מִתְּלַת דַּרְגִּין, בְּמַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה.","(ויקרא כ״ג:ל״ד) בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ', דְּאִיהִי תִּשְׁרֵי, מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם כָּל מְלֶאכֶת עֲבוֹדָה לֹא תַעֲשׂוּ וְחַגּוֹתֶם אוֹתוֹ חַג לַיְיָ שִׁבְעַת יָמִים וְגוֹ'. בַּחֲמִשָּׁה עָשָׂר, מִסִּטְרָא דְּיָ\"הּ. וְחַגּוֹתֶם אוֹתוֹ, דָּא אוֹת ו', עַמּוּדָא דְּאֶמְצָעִיתָא. (ח\"ג חסד גבורה) שִׁבְעַת יָמִים, מִסִּטְרָא דְּבַת שֶׁבַע, דְּאִיהִי מַלְכוּת. אֲבָהָן, וְרַעְיָא מְהֵימָנָא, וְאַהֲרֹן, דָּוִד וּשְׁלֹמֹה, הָא אִינּוּן שֶׁבַע, לָקֳבֵל שֶׁבַע סְפִירָאן. אֲנָא בָּעֵינָא לְתַקְּנָא לְכוֹן סֻכָּה, דְּאִיהִי אִימָּא עִלָּאָה, לְסַכְּכָא עָלַיְיהוּ, כְּאִמָּא עַל בְּנִין.","וּבְגִין ז' סְפִירָאן אָמַר קְרָא, (ויקרא כ״ג:מ״ג) כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי אֶת בְּנֵי יִשְׂרָאֵל, בְּמַפְקָנוּתְהוֹן מֵאַרְעָא דְּמִצְרַיִם, בְּז' עֲנָנֵי כָּבוֹד. סוּכָּה (אית באת ו', בסוכות חסר ו', דאתמר בה בסכת תשבו שבעת ימים, איהי אימא אבל סוכה) בְּאָת ו', אִיהוּ בְּרָזָא (דתיבין) דִּתְרֵין בְּנִין, יְדוָֹד אֲדֹנָי. וְהָכִי סָלִיק סוּכָּ\"ה בְּחוּשְׁבַּן יְאֲהדוָֹנָהי. תְּרֵין כְּרוּבִים, דְּהֵם (שמות כ״ה:כ׳) סוֹכְכִים בְּכַנְפֵיהֶם עַל הַכַּפּוֹרֶת וּפְנֵיהֶם אִישׁ אֶל אָחִיו.","וְאִית עַשְׂרָה טְפָחִים בַּכְּרוּבִים מִתַּתָּא לְעֵילָּא, מֵרַגְלֵיהוֹן עַד רֵישֵׁיהוֹן, וּמֵרֵישֵׁיהוֹן וְעַד רַגְלֵיהוֹן, וְשַׁרְיָין עַל טֶפַח דְּאִיהוּ י'. וְעַשְׂרָה עַשְׂרָה מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא, הַיְינוּ יוֹ\"ד. וּבְגִין כָּךְ, שִׁיעוּרָא דְּסֻּכָּה אָמְרוּ רַבָּנָן, לֹא פָּחוּת מֵעֲשָׂרָה, וְלֹא לְמַעְלָה מֵעֶשְׂרִים. סֻכָּה הַעֲשׂוּיָה כְּכִבְשָׁן מִסִּטְרָא דְּאִימָּא, עָלָהּ אִתְּמַר, (שמות י״ט:י״ח) וְהַר סִינַי עָשָׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו יְיָ בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. (ואוקמוה מאי (יחזקאל א׳:י״ד) והחיות רצוא ושוב, כאור היוצא מפי הכבשן) וְכֹלָּא חַד.","(ישעיהו ד׳:ו׳) וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם, דִּסְכַךְ בָּעֵינָן. וּסְכַךְ אִתְעָבִיד לַצֵל. דְּאִתְּמַר בֵּיהּ, (תהילים צ״א:א׳) בְּצֵל שַׁדַּי יִתְלוֹנָן. וְלֹא בְּצֵל סֻכַּת הֶדְיוֹט, דְּאָגִין עַל גּוּפָא מִשִׁמְּשָׁא. אֶלָּא צֵל לְאַגָּנָא עַל נִשְׁמְתָא. (שיר השירים ב׳:ג׳) בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי. (איכה ד׳:כ׳) אֲשֶׁר אָמַרְנוּ בְּצִלּוֹ נִחְיֶה בַגּוֹיִם. צֵל עִם ם', אִיהִי צֶלֶם. דְּאִתְּמַר בֵּיהּ, (תהילים ל״ט:ז׳) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. ם' סְתוּמָה אִית לָהּ אַרְבָּעָה דְּפָנוֹת.","וּמַה דְּאוּקְמוּהָ שְׁתַּיִם כְּהִלְכָתָן וּשְׁלִישִׁית אֲפִילּוּ טֶפַח. וּלְמַאן דְּאָמַר שְׁלֹשָׁה כְּהִלְכָתָן וּרְבִיעִית אֲפִילּוּ טֶפַח. וְאִינּוּן בְּגִין דָּא, תְּרֵין, תְּלַת, אַרְבַּע, הָא תֵּשַׁע, טֶפַח אִיהִי עֲשִׁירָאָה, לְאַשְׁלְמָא כָּל חֶסְרוֹן. וּבְגִין דָּא, שִׁיעוּר סֻכָּה לֹא פָּחוּת מֵעֶשֶׂר, דְּאִיהִי מַלְכוּת, עֲשִׁירָאָה דְּכָל דַּרְגִּין. וְלָא לְמַעְלָה מֵעֶשְׂרִין, דְּאִיהִי כ', כֶּתֶר עֶלְיוֹן, דְּלָא שַׁלְטָא בֵּיהּ עֵינָא. כָּבוֹד עִלָּאָה, עָלֵיהּ אָמַר מֹשֶׁה, (שמות ל״ג:י״ח) הַרְאֵנִי נָא אֶת כְּבוֹדֶךָ. וְאָתִיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, לֹא תּוּכַל לִרְאוֹת אֶת פָּנָי. וְלֵית כָּבוֹד, בְּלָא כ'.","וּבְגִין דָּא שִׂעֵרוּ מָארֵי מַתְנִיתִין לָקֳבְלַיְיהוּ, סֻכָּה הַעֲשׂוּיָה כְּמָבוֹי, מִסִּטְרָא דְּאָת ב', כְּמִין גא\"ם, מִסִּטְרָא דְּאָת ג'. כְּמִין צְרִיף, מִסִּטְרָא דְּאָת ד'. וְשֶׁבַע אַתְוָון אִינּוּן, בְּגִין דָּא כּפר\"ת. כ', כִּבְשָׁן. ב', בּוּרְגָנִין. וּשְׁאַר סֻכּוֹת. וְכֻלְּהוּ רְמִיזֵי לְגַבֵּי מָארֵי מַתְנִיתִין. וְלֵית לְאַרָכָא בְּהוֹן.","וְאִינּוּן לָקֳבְלַיְיהוּ שִׁבְעָה כֹּכְבֵי לֶכֶת, וְאִינּוּן דְּכַר וְנוּקְבָּא. וּבְגִין דָּא אִתְקְרִיאוּ ז' כְּפוּלוֹת. כְּגוֹן שִׁבְעָה שַׁרְגִּין דִּמְנַרְתָּא, דְּאִתְּמַר בָּהּ (תהילים קי״ט:קס״ד) שֶׁבַע בַּיוֹם הִלַּלְתִּיךָ. הָכִי (זכריה ד׳:ב׳) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת. הָכִי שִׁבְעָה סְפִירָאן כְּפוּלוֹת. וְשִׁבְעָה יוֹמֵי בְּרֵאשִׁית לְתַתָּא, שִׁבְעָה לְעֵילָּא, (קהלת א׳:ט׳) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ.","לוּלָב דָּא צַדִּיק. דְּדָמֵי לְחוּט הַשִּׁדְרָה, דְּבֵיהּ ח\"י חוּלְיָין, לָקֳבֵל ח\"י נִעְנוּעִין דְּלוּלָב. וְאִינּוּן לָקֳבֵל ח\"י בִּרְכָאן דִּצְלוֹתָא. לָקֳבֵל שְׁמֹנֶה עֲשַׂר אַזְכָּרוֹת, (תהילים כ״ט:א׳) דְּהָבוּ לַיְיָ בְּנֵי אֵלִים. לָקֳבֵל שְׁמֹנֶה עֲשַׂר אַזְכָּרוֹת דִּקְרִיאַת שְׁמַע. וְנִעְנוּעַ לְשִׁית סִיטְרִין, בְּחוּשְׁבַּן ו'. תְּלַת נִעְנוּעִין בְּכָל סִטְרָא, אִינּוּן ח\"י."],[[0,"ואוף הכי אית","וכו': ואף כך, יש סוד אחר, חיי המלך הם חכמה, ז\"ש החכמה תחיה בעליה. לפיכך, כל הנודר בהויה, שהוא תפארת, הוא כאלו נדר בחכמה דז\"א, שהוא הויה במילוי אלפין כזה, יוד הא ואו הא, שהוא חיי המלך, שהוא חיי ז\"א. וכל הנשבע באדני, היא כאלו נשבע במלך עצמו. היינו, כי \u0003עצמו,\u0004 היא אמא עליונה, דהיינו בינה, שדומה כאלו נשבע בה, שהיא \u0003עצם\u0004 השמים לטהר. שהם המוחין של המלכות. כי מצד החסד נקראת המלכות \u0003עצם\u0004 מעצמי. ומצד הגבורה נקראת המלכות ו \u0003בשר\u0004 מבשרי. ובחכמה שהיא חיי התפארת, דהיינו המוחין שלו, הוא, תפארת, עולה להקרא \u0003אדם,\u0004 שהוא בגימטריא \u0003מ\"ה\u0004 כהויה במילוי אלפין הנ\"ל, ז\"ש, כתפארת אדם. כי תפארת נקרא אדם בזמן שיש לו המוחין דחכמה. שה\"ס, שנקרא בהויה דאלפין שבגי' מ\"ה."],[1,"ואתמר ביום הכפורים","וכו': ונאמר ביום הכפורים, ועניתם את נפשותיכם. וכן ובעשור לחדש השביעי הזה תענו את נפשותיכם. והתקינו בה, \u0003ה'\u0004 עינוים, כדי שתתלבן \u0003ה'\u0004 הקטנה, שהיא מלכות, ב \u0003ה'\u0004 עליונה שהיא בינה, שממנה נמשכים העינוים, דהיינו מקו שמאל שלה, שהם ה' תפלות, לקיים בישראל, אם יהיו חטאיכם כשנים כשלג \u0003ילבינו.\u0004 וזה הוא סוד של לשון של זהורית, שהיו קושרים על פתח האולם מבפנים, וכיון שהגיע השעיר למדבר היה \u0003מלבין.\u0004 (יומא סז.) משום שכל עונות בית ישראל מגיעים למלכות, והתשובה, שהיא בינה, \u0003מלבנת\u0004 אותם. משום שכתוב בה, במלכות אני ה' השוכן אתם בתוך טומאותם. וד' בגדי לבן וד' בגדי זהב, ללבוש, ה\"ס \u0003יאהדונהי.\u0004 שהוא שילוב הוי\"ה אדני, כי ד' בגדי לבן ה\"ס ד' אותיות הוי\"ה. וד' בגדי זהב ה\"ס ד' אותיות אדנ\"י."],[2,"ותקינו לתקוע שופר","וכו': והתקינו לתקוע שופר ביום הכפורים, להעלות קול, שהוא \u0003ו'\u0004 דהויה, דהיינו ז\"א, לחרות, שהוא בינה. שנאמר בה, בכל צרתם לו צר. אשר לו הוא ב \u0003א'\u0004 ובו' דהיינו קרי וכתיב, כי כתיב ב \u0003א'\u0004 וקרי ב \u0003ו'.\u0004 כי \u0003בכל צרתם\u0004 רומז על ה' עינוים, והדינים שמקורם הוא בבינה בקו שמאל שלה. ובסוד תקיעת שופר מעלים ז\"א ג\"כ שם לבינה, וע\"כ יש כתיב וקרי ב \u0003א'\u0004 וב \u0003ו'.\u0004 אשר ה \u0003א'\u0004 רומזת על הבינה, בסוד אלף בינה. וה \u0003ו'\u0004 רומזת על ז\"א שעלה לבינה. ועבודת יום הכפורים היא באריכות, והיא כלולה מג' מדרגות, מחשבה, דבור, ומעשה."],[3,"בחמשה עשר יום","וגו': בחמשה עשר יום לחדש השביעי וגו' שהוא תשרי, מקרא קדש יהיה לכם כל מלאכת עבודה לא תעשו וחגותם אותו חג לה' שבעת ימים וגו'. \u0003בחמשה עשר,\u0004 היינו מצד י\"ה, שהם חכמה ובינה, \u0003וחגותם אותו,\u0004 הוא אותיות \u0003אות ו',\u0004 שהוא עמוד האמצעי דהיינו ז\"א. \u0003שבעת ימים,\u0004 היינו מצד בת שבע שהיא מלכות, שהיא \u0003ה'\u0004 אחרונה. האבות שהם חג\"ת, ורעיא מהימנא, שהוא נצח, ואהרן, שהוא הוד, ודוד שהוא מלכות, ושלמה, שהוא יסוד הנקרא שלום. הרי הם שבע כנגד שבע ספירות. אני רוצה לתקן לכם סוכה, שהיא אמא עליונה, שתסכך עליהם על שבע הספירות, כאם על הבנים."],[4,"ובגין ז' ספיראן","וכו': ומשום ז' הספירות, אמר הכתוב, כי בסכות הושבתי את בני ישראל בהוציאי אותם מארץ מצרים, דהיינו בז' ענני כבוד. שה\"ס ז' ספירות. \u0003סוכה\u0004 עם אות \u0003ו'\u0004 היא בסוד ב' בנים, שבינה מסככת עליהם, שהם הויה אדני, דהיינו ז\"א ומלכות, שכך עולה סוכה בחשבון \u0003יאהדונה\"י,\u0004 כי סוכה היא אותיות \u0003כ\"ו\u0004 שהיא בגי' הוי\"ה, ו \u0003ס\"ה\u0004 שהיא בגי' אדני. והם סוד ב' כרובים שהם סוככים בכנפיהם על הכפורת, ופניהם איש אל אחיו. שה\"ס ז\"א ומלכות."],[5,"ואית עשרה טפחים","וכו': ויש עשרה טפחים בכרובים, שהם זו\"ן, ממטה למעלה, דהיינו ע\"ס דאור חוזר, מרגליהם עד ראשיהם, וע\"ס דאור ישר מראשיהם עד רגליהם, ושורים על טפח, שה\"ס \u0003י'.\u0004 ועשרה עשרה שבהם שממעלה למטה וממטה למעלה, דהיינו ע\"ס דאור ישר וע\"ס דאור חוזר, היינו \u0003יוד,\u0004 שהיא בגי' עשרים. ומשום זה אמרו חכמים, ששיעור סוכה לא פחות מעשרה ולא למעלה מעשרים. סוכה העשויה ככבשן היא מצד אמא, שהיא דין, עליה נאמר, והר סיני עשן כולו מפני אשר ירד עליו ה' באש ויעל עשנו כעשן הכבשן. והכל אחד."],[6,"וסכה תהיה לצל יומם:","היינו שצריכים לסכך. וסכך נעשה לצל, שנאמר בה, בצל שדי יתלונן, ולא בצל סוכת הדיוט המגין על הגוף משמש, אלא צל להגין על הנשמה. בסו\"ה, בצלו חמדתי וישבתי. אשר אמרנו בצלו נחיה בגוים. \u0003צל\u0004 עם \u0003ם'\u0004 הוא \u0003צלם,\u0004 שצל ה\"ס הסכך, וה \u0003ם'\u0004 ה\"ס ארבע דפנות הסוכה. שנאמר בו אך בצלם יתהלך איש. \u0003ם'\u0004 סתומה יש לה ארבעה דפנות. שה\"ס ד' דפנות הסוכה."],[7,"ומה דאוקמוה שתים","וכו': ומה שהעמידו שתים כהלכתן ושלישית אפילו טפח. וכן למי שאומר שלשה כהלכתן ורביעית אפילו טפח, הם משום זה ג' שיעורים, שתים שלש ארבע, שהם ביחד תשע, ששתים, הם חו\"ב. שלש, הם חג\"ת. ארבע, הם נהי\"מ, והטפח שאמרו בשתים ובשלש הוא העשירי, שהיא מלכות, המשלמת כל חסרון. ומשום זה שיעור סוכה לא פחות מעשר שהיא מלכות, שהיא העשירית של כל הספירות, ולא למעלה מעשרים, שהיא \u0003כ',\u0004 הרומזת על כתר עליון שאין העין שולטת בו. שאין שם השגה. כבוד עליון, עליו אמר משה, הראני נא את כבודך. והשיב לו הקב\"ה, לא תוכל לראות את פני. ואין כבוד בלא \u0003כ'.\u0004"],[8,"ובגין דא שערו","וכו': ומשום זה שערו בעלי המשנה כנגדם, סוכה העשויה כמבוי, שהיא מצד אות \u0003ב'.\u0004 וכמין גאם, שהיא מצד אות \u0003ג'.\u0004 וכמין צריף שהיא מצד אות \u0003ד'.\u0004 ושבע אותיות הן \u0003בג\"ד כפר\"ת,\u0004 שהן הכפולות בדגש, הרומזות על ז\"ס חג\"ת נהי\"מ על בחינת הדין שבהם, והם ראשי תיבות הרומזים על ז' סוכות הפסולות, מחמת הדין שבהם, ה \u0003כ'\u0004 רומזת על סוכה העשויה ככבשן, ה \u0003ב',\u0004 על סוכת בורגנין, ושאר האותיות על שאר סוכות הפסולות שכולן רמוזות אצל בעלי המשנה. כגון סכת שומרי \u0003פ\u0004 ירות סוכת \u0003ר\u0004 ועים, סוכת כו \u0003ת\u0004 ים. וכו' (סוכה ח' ע\"ב) ואין להאריך בהם."],[9,"ואינון לקבלייהו שבעה","וכו': והם כנגדם, דבג\"ד כפר\"ת, שבעה ככבי לכת. והם דכר ונוקבא. שבג\"ד כפר\"ת הרפויות הן בדכר, והדגושות הן בנוקבא. ומשום זה נקראים ז' כפולות, וכמו שבעה נרות המנורה, שה\"ס ז\"ס חג\"ת נהי\"מ. שנאמר בה, שבע ביום הללתיך. וכך נאמר שבעה ושבעה מוצקות, שה\"ס ז' כפולות, שהם שבע אותיות רפויות, ושבע אותיות דגושות, וכך שבע ספירות הן כפולות, שיש בהם ז' של דין וז' של רחמים. וכך שבעת ימי בראשית למטה, דהיינו ז' ספירות דמלכות, שהן דגושות בדינים, ושבע למעלה, דהיינו ז\"ס דז\"א, שהן רפויות מדינים. שעל ז\"ס שלמטה, נאמר, אין כל חדש תחת השמש. כי כל החידושים באים משמש, שהוא ז\"ס דז\"א. ולא מתחת השמש, שהוא ז\"ס דמלכות."],[10,"לולב דא צדיק","וכו': לולב זה צדיק, שהוא יסוד, כי הלולב דומה לחוט השדרה, שיש בו ח\"י טבעות, כנגד ח\"י נענועים שבלולב. והם כנגד ח\"י ברכות של תפלת העמידה, והם כנגד ח\"י אזכרות, דהיינו שמות הויה, שבהבו לה' בני אלים. וכנגד ח\"י אזכרות שבקריאת שמע. והנענוע של הלולב, הוא לששה צדדים, דרום, צפון, מזרח, מעלה, מטה, ומערב. שהוא בחשבון ששה, וג' נענועים לכל צד, הם בחשבון ח\"י."]],[[0,"","וְאַף כָּךְ יֵשׁ סוֹד אַחֵר, חַיֵּי הַמֶּלֶךְ - חָכְמָה. זֶהוּ שֶׁכָּתוּב (קהלת ז) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. כָּל הַנּוֹדֵר בַּיהֹוָה, שֶׁהוּא תִּפְאֶרֶת, כְּאִלּוּ נוֹדֵר בַּחָכְמָה, שֶׁהוּא שֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, חַיֵּי הַמֶּלֶךְ. וְכָל הַנִּשְׁבָּע בַּאדנָי, כְּאִלּוּ נִשְׁבָּע בַּמֶּלֶךְ עַצְמוֹ. עַצְמוֹ, זוֹ אִמָּא עֶלְיוֹנָה, כְּאִלּוּ נִשְׁבָּע בָּהּ, שֶׁהִיא (שמות כד) עֶצֶם הַשָּׁמַיִם לָ הַר. מִצַּד הַחֶסֶד - (בראשית ב) עֶצֶם מֵעֲצָמַי. וּבָשָׂר מִבְּשָׂרִי - מִצַּד הַגְּבוּרָה, זוֹ מַלְכוּת. וּבַחָכְמָה, שֶׁהִיא חַיֵּי תִפְאֶרֶת, הוּא עוֹלֶה לִקְרַאת אָדָם. זֶהוּ שֶׁכָּתוּב (ישעיה מד) כְּתִפְאֶרֶת אָדָם."],[1,"","וְנֶאֱמַר בְּיוֹם הַכִּפּוּרִים, (ויקרא טז) וְעִנִּיתֶם אֶת נַפְשּתֵיכֶם. וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה תְּעַנּוּ אֶת נַפְשּתֵיכֶם. תִּקְּנוּ בוֹ חֲמִשָּׁה עִנּוּיִים, כְּדֵי שֶׁתִּתְלַבֵּן ה' קְטַנָּה בְּה' עֶלְיוֹנָה, שֶׁהִיא חָמֵשׁ תְּפִלּוֹת. לְקַיֵּם בְּיִשְׂרָאֵל, (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְזֶהוּ סוֹד שֶׁל לְשׁוֹן זְהוֹרִית, מִשּׁוּם שֶׁכָּל הַחוֹבוֹת שֶׁל יִשְׂרָאֵל מַגִּיעִים אֵצֶל הַמַּלְכוּת, וּתְשׁוּבָה, שֶׁהִיא בִּינָה, מְלַבֶּנֶת אוֹתָם, מִשּׁוּם שֶׁנֶּאֱמַר בָּהּ (ויקרא טז) הַשֹּׁכֵן אִתָּם בְּתוֹךְ טֻמְאֹתָם. וְאַרְבָּעָה בִּגְדֵי לָבָן וְאַרְבָּעָה בִּגְדֵי זָהָב לְהַלְבִּישׁ - יְאֲהדוָנָהי."],[2,"","וְתִקְּנוּ לִתְקֹעַ שׁוֹפָר בְּיוֹם הַכִּפּוּרִים, לְהַעֲלוֹת קוֹל, שֶׁהוּא אוֹת ו', לְחֵרוּת, שֶׁנֶּאֱמַר בָּהּ (ישעיה סג) בְּכָל צָרָתָם לוֹ צָר - בְּא' וּבְו', קְרִי וּכְתִיב. וַעֲבוֹדַת יוֹם הַכִּפּוּרִים הִיא בַּאֲרִיכוּת, וְהִיא כְּלוּלָה מִשָּׁלֹשׁ מַדְרֵגוֹת - בְּמַחֲשָׁבָה, דִּבּוּר וּמַעֲשֶׂה."],[3,"","בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ' (ויקרא כג), שֶׁהוּא תִּשְׁרֵי, מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם. כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ. וְחַגֹּתֶם אֹתוֹ חַג לַה' שִׁבְעַת יָמִים וְגוֹ'. בַּחֲמִשָּׁה עָשָׂר - מִצַּד שֶׁל יָ\"הּ. וְחַגֹּתֶם אֹתוֹ - זוֹ אוֹת ו', הָעַמּוּד הָאֶמְצָעִי. (ח\"ג חסד גבורה) שִׁבְעַת יָמִים - מִצַּד שֶׁל בַּת שֶׁבַע, שֶׁהִיא מַלְכוּת. הָאָבוֹת, וְהָרוֹעֶה הַנֶּאֱמָן, וְאַהֲרֹן, דָּוִד וּשְׁלֹמֹה - הֲרֵי הֵם שִׁבְעָה, כְּנֶגֶד שֶׁבַע סְפִירוֹת. אֲנִי רוֹצֶה לְתַקֵּן לָכֶם סֻכָּה, שֶׁהִיא אִמָּא עֶלְיוֹנָה, לְסַכֵּךְ עֲלֵיהֶם כְּאִמָּא עַל בָּנִים."],[4,"","וּמִשּׁוּם שֶׁבַע סְפִירוֹת אָמַר הַפָּסוּק, (ויקרא כג) כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי אֶת בְּנֵי יִשְׂרָאֵל, בְּצֵאתָם מֵאֶרֶץ מִצְרַיִם, בְּשִׁבְעָה עַנְנֵי כָבוֹד. סֻכָּה (יש שכתובה באות ו', בסכת חסר ו', שנאמר בה בסכת תשבו שבעת ימים. היא אמא. אבל סכה) בְּאוֹת ו' הִיא בְּסוֹד (התבות) שֶׁל שְׁנֵי בָנִים - יְהֹוָה אֲדנָי. וְכָךְ עוֹלָה סוּכָּ\"ה בְּחֶשְׁבּוֹן יְאֲהדוָנָהי. שְׁנֵי כְרוּבִים, שֶׁהֵם (שמות כה) סֹכֲכִים בְּכַנְפֵיהֶם עַל הַכַּפֹּרֶת וּפְנֵיהֶם אִישׁ אֶל אָחִיו."],[5,"","וְיִשִׁ עֲשָׂרָה טְפָחִים בַּכְּרוּבִים מִמַּטָּה לְמַעְלָה, מֵרַגְלֵיהֶם עַד רָאשֵׁיהֶם, וּמֵרָאשֵׁיהֶם עַד רַגְלֵיהֶם, וְשׁוֹרִים עַל טֶפַח שֶׁהוּא י'. וַעֲשָׂרָה עֲשָׂרָה מִמַּעְלָה לְמַטָּה, וּמִמַּטָּה לְמַעְלָה, כְּלוֹמַר יוֹ\"ד. וּמִשּׁוּם זֶה שִׁעוּר סֻכָּה אָמְרוּ חֲכָמִים, לֹא פָחוֹת מֵעֲשָׂרָה, וְלֹא לְמַעְלָה מֵעֶשְׂרִים. סֻכָּה הָעֲשׂוּיָה כְּכִבְשָׁן מִצַּד שֶׁל אִמָּא, עָלֶיהָ נֶאֱמַר (שמות יט) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. (ופרשוהו, מהו (יחזקאל א) והחיות רצוא ושוב, ' כאור היוצא מפי הכבשן) וְהַכֹּל אֶחָד."],[6,"","וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם (ישעיה ד), שֶׁצָּרִיךְ סְכָךְ. וּסְכָךְ נַעֲשֶׂה לְצֵל, שֶׁנֶּאֱמַר בּוֹ (תהלים צא) בְּצֵל שַׁדַּי יִתְלוֹנָן. וְלֹא בְצֵל סֻכַּת הֶדְיוֹט, שֶׁמֵּגֵן עַל הַגּוּף מִשֶּׁמֶשׁ. אֶלָּא צֵל לְהָגֵן עַל הַנְּשָׁמָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ב) בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי. (איכהד) אֲשֶׁר אָמַרְנוּ בְּצִלּוֹ נִחְיֶה בַגּוֹיִם. צֵל עִם ם' הוּא צֶלֶם, שֶׁנֶּאֱמַר בּוֹ (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. ם' סְתוּמָה יֵשׁ לָהּ אַרְבַּע דְּפָנוֹת."],[7,"","וּמַה שֶּׁפֵּרְשׁוּהוּ שְׁתַּיִם כְּהִלְכָתָן וּשְׁלִישִׁית אֲפִלּוּ טֶפַח, וּלְמִי שֶׁאָמַר שְׁלֹשָׁה כְּהִלְכָתָן וּרְבִיעִית אֲפִלּוּ טֶפַח, וְהֵם בִּגְלַל זֶה, שְׁתַּיִם, שָׁלֹשׁ, אַרְבַּע - הֲרֵי תֵּשַׁע. וְטֶפַח הוּא עֲשִׂירִי, לְהַשְׁלִים כָּל חִסָּרוֹן. וּמִשּׁוּם זֶה שִׁעוּר סֻכָּה לֹא פָחוֹת מֵעֶשֶׂר, שֶׁהִיא מַלְכוּת, עֲשִׂירִית שֶׁל כָּל הַדְּרָגוֹת. וְלֹא לְמַעְלָה מֵעֶשְׂרִים, שֶׁהִיא אוֹת כ', כֶּתֶר עֶלְיוֹן, שֶׁלֹּא שׁוֹלֶטֶת בּוֹ עַיִן. כָּבוֹד עֶלְיוֹן, עָלָיו אָמַר מֹשֶׁה, (שמות לג) הַרְאֵנִי נָא אֶת כְּבֹדֶךְ. וְהֵשִׁיב לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא תוּכַל לִרְאֹת אֶת פָּנָי. וְאֵין כָּבוֹד בְּלִי אוֹת כ'."],[8,"","וּמִשּׁוּם זֶה שִׁעֲרוּ בַּעֲלֵי הַמִּשְׁנָה כְּנֶגְדָּם, סֻכָּה הָעֲשׂוּיָה כְּמָבוֹי, מִצַּד אוֹת ב', כְּמִין גא\"ם, מִצַּד אוֹת ג'. כְּמִין צְרִיף, מִצַּד אוֹת ד'. וְשֶׁבַע אוֹתִיּוֹת הֵן, בִּגְלַל זֶה כפר\"ת: כ' - כִּבְשָׁן. ב' - בּוּרְגָנִין. וּשְׁאָר סֻכּוֹת. וְכֻלָּם רְמָזִים אֵצֶל בַּעֲלֵי הַמִּשְׁנָה, וְאֵין לְהַאֲרִיךְ בָּהֶם."],[9,"","וְאֵלּוּ לְעֻמָּתָם שִׁבְעָה כּוֹכְבֵי לֶכֶת, וְהֵם זָכָר וּנְקֵבָה. וּמִשּׁוּם זֶה נִקְרָאִים שֶׁבַע כְּפוּלוֹת, כְּמוֹ שִׁבְעָה קָנִים שֶׁל הַמְּנוֹרָה שֶׁנֶּאֱמַר בָּהּ (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ. כָּךְ (זכריה ד) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת. כָּךְ שֶׁבַע סְפִירוֹת כְּפוּלוֹת. וְשִׁבְעָה יְמֵי בְרֵאשִׁית לְמַטָּה, שִׁבְעָה לְמַעְלָה, (קהלת א) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ."],[10,"","לוּלָב זֶה צַדִּיק, שֶׁדּוֹמֶה לְחוּט הַשִּׁדְרָה, שֶׁבּוֹ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, כְּנֶגֶד שְׁמוֹנָה עָשָׂר נִעְנוּעִים שֶׁל הַלּוּלָב. וְהֵם כְּנֶגֶד שְׁמוֹנֶה עֶשְׂרֵה בִּרְכוֹת הַתְּפִלָּה, כְּנֶגֶד שְׁמוֹנָה עָשָׂר שֵׁמוֹת שֶׁל (תהלים כט) הָבוּ לַה' בְּנֵי אֵלִים, כְּנֶגֶד שְׁמוֹנָה עָשָׂר שֵׁמוֹת שֶׁל קְרִיאַת שְׁמַע. וְנִעְנוּעַ לְשִׁשָּׁה צְדָדִים, בְּחֶשְׁבּוֹן ו'. וּשְׁלֹשָׁה נִעְנוּעִים בְּכָל צַד, הֵם שְׁמוֹנָה עָשָׂר."]]],[["לוּלָב בַּיָּמִין, כָּלִיל שִׁשָׁה מִינִין (דאינון) ג' הֲדַסִּין, גְּדוּלָּה גְּבוּרָה תִּפְאֶרֶת. וְדַמְיָין לִתְלַת גְּוָונֵי עֵינָא. ב' בַּדֵּי עֲרָבוֹת, נֶצַח וְהוֹד. וְדַמְיָין לִתְרֵין שִׂפְוָון. לוּלָב, יְסוֹד, דּוֹמֶה לַשִּׁדְרָה. דְּבֵיהּ קִיּוּם דְּכָל גַּרְמִין. וְעָלֵיהּ אָמַר דָּוִד, (תהילים ל״ה:י׳) כָּל עַצְמוֹתַי תֹּאמַרְנָּה יְיָ מִי כָמוֹךָ. אֶתְרוֹג, מַלְכוּת. דּוֹמֶה לְלִבָּא. דְּבֵיהּ הִרְהוּרִין.","וְנִעְנוּעִין דְּהַלֵל, אִינּוּן מְשׁוּתָּפִין בְּנִעְנוּעִין דִּנְטִילַת לוּלָב, וְאִינּוּן ח\"י בְּאָנָא. ח\"י ח\"י, בְּהוֹדוּ תְּחִלָּה וָסוֹף. ח\"י דִּנְטִילַת לוּלָב, הֲרֵי ע\"ב. וּבְגִין דָּא לוּלָב בְּחוּשְׁבַּן ח\"ס, וְד' מִינִין דְּלוּלָב, הָא חֶסֶד, דְּרוֹעָא יְמִינָא. וּבְגִין דָּא תַּקִּינוּ לוּלָב בַּיָּמִין, לְסִטְרָא דְּחֶסֶד. אֶתְרוֹג לְסִטְרָא דִּגְבוּרָה, לִשְׂמָאלָא לִבָּא. וּבְגִין דָּא אֶתְרוֹג הַדּוֹמֶה לַלֵּב, תַּקִּינוּ לְמֶהֱוִי בְּיַד שְׂמֹאל. כְּמָה דְּאוּקְמוּהָ, לוּלָב בַּיָּמִין, וְאֶתְרוֹג בִּשְׂמֹאלוֹ. אִינּוּן לָקֳבֵל זָכוֹר וְשָׁמוֹר. וּמַאן נָטִיל תַּרְוַויְיהוּ. עַמּוּדָא דְּאֶמְצָעִיתָא. לוּלָב בִּימִינֵיהּ, וְאֶתְרוֹג בִּשְׂמָאלֵיהּ.","אָתוּ אֲבָהָן, וְרַעְיָא מְהֵימָנָא, וְאַהֲרֹן וְדָוִד וּשְׁלֹמֹה, וּבָרִיכוּ לֵיהּ, וְאָמְרוּ לֵיהּ, אַנְתְּ בּוּצִינָא קַדִּישָׁא, וְחַבְרַיָּיא דִּילָךְ דְּאִינּוּן שִׁית, לָקֳבֵל אִינּוּן ז'. וְאַנְתְּ בּוּצִינָא קַדִּישָׁא נֵר מַעֲרָבִי בְּאֶמְצַע, דְּכָל שִׁית נֵרוֹת נְהִרִין מִנָךְ. בְּכָל חַד אִתְּמַר בֵּיהּ, (משלי כ׳:כ״ז) נֵר יְיָ נִשְׁמַת אָדָם. וְרַעְיָא מְהֵימָנָא נָהִיר בָּךְ, וְאַנְתְּ בְּחַבְרַיָּיא דִּילָךְ, וְכֹלָּא חַד, בְּלָא פִּרוּדָא כְּלָל. וּמִתַּמָּן וְאִילָךְ מִתְפַּשְּׁטִין עַנְפִין לְכָל מָארֵי חָכְמְתָא, אַשְׁלִים מִלִּין דַּחֲבוּרָא קַדְמָאָה דִּילָךְ לְאַעְטְּרָא לוֹן.","פָּתַח בּוּצִינָא קַדִּישָׁא וְאָמַר, בְּחִבּוּרָא קַדְמָאָה אִתְּמַר (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה וְגוֹ'. מַאי בּוּז. יוֹמָא תִּנְיָינָא, וְיוֹמָא שְׁתִיתָאָה, וְיוֹמָא שְׁבִיעָאָה דְּסוּכּוֹת. דִּבְהוֹן הֲווֹ מְנַסְּכִים מַיִם וְיַיִן.","דְּשֶׁבַע יוֹמִין דְּסוּכּוֹת, בְּהוֹן הָיוּ מַקְרִיבִין יִשְׂרָאֵל שִׁבְעִים פָּרִים, לְכַפְּרָא עַל שִׁבְעִין מְמָנָן, בְּגִין דְּלָא יִשְׁתְּאַר עָלְמָא חָרוּב מִנַּיְיהוּ. הֲדָא הוּא דִכְתִיב, וּבַחֲמִשָּׁה עָשָׂר יוֹם וְהִקְרַבְתֶּם עוֹלָה אִשֶּׁה לְרֵיחַ נִיחֹחַ לַיְיָ פָּרִים בְּנֵי בָקָר שְׁלֹשָׁה עָשָׂר תְּמִימִים. וּבַיּוֹם הַשֵּׁנִי פָּרִים י\"ב. וּבַיּוֹם הַשְּׁלִישִׁי י\"א. וּבַיּוֹם הָרְבִיעִי עֲשָׂרָה. וּבַיּוֹם הַחֲמִישִׁי פָּרִים תִּשְׁעָה. וּבַיּוֹם הַשִּׁשִּׁי פָּרִים שְׁמֹנֶה. וּבַיּוֹם הַשְּׁבִיעִי שִׁבְעָה. וְכֻלְּהוּ שִׁבְעִין. וּבְכָל יוֹמָא הֲווֹ חָסֵרִים. אֲמַאי חָסֵרִים.","אֶלָּא הָכָא קָא רָמִיז, (בראשית ח׳:ד׳) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי. וּמַה הָתָם בְּימֵי טוֹפָנָא, (בראשית ח׳:ד׳) וְהַמַּיִם הָלְכוּ הָלוֹךְ וְחָסוֹר. אוּף הָכִי בְּתִשְׁרֵי, דְּאִיהוּ יַרְחָא שְׁבִיעָאָה, דְּבֵיהּ כַּמָה פִּקוּדִין, רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, סֻכָּה וְלוּלָב אֶתְרוֹג, מִינִין דְּלוּלָב שׁוֹפָר. שְׁכִינְתָּא עִלָּאָה שַׁרְיָיא עַל יִשְׂרָאֵל, דְּאִיהִי תְּשׁוּבָה, סוּכָּה. אֶתְרוֹג, וְקוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ לוּלָב. מִיַּד וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר, מִתְמַעֲטִין חוֹבִין דְּיִשְׂרָאֵל, אוּף הָכִי מִתְמַעֲטִין מְמָנָן דְּאִינּוּן מַלְאֲכֵי חַבָּלָה, דִּמְמָנָן עָלַיְיהוּ, דְּדַמְיָין לְמֵי טוֹפָנָא. כְּמָה דְּאוֹקְמוּהָ, עָשָׂה עֲבֵרָה אַחַת קָנָה לוֹ קַטֵיגוֹר אֶחָד. בְּהַהוּא זִמְנָא דְּמִתְמָעֲטִין חוֹבִין, מִתְמַעֲטִין פָּרִים דִּלְהוֹן, מִתְמַעֲטִין מְמָנָן דְּע' אוּמִין, מִתְמַעֲטִין ע' אוּמִין, מִתְמַעֵט טוּבָא דִּלְהוֹן.","תֵּיבַת נֹחַ, מָנֵי קוּדְשָׁא בְּרִיךְ הוּא, לְאַעֲלָא עִמֵּיהּ (בראשית ז׳:ג׳) שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה זָכָר וּנְקֵבָה, לְקָרְבָּנָא, לְאַגָּנָא עַל נֹחַ, וְעַל כָּל אִינּוּן דְּעָאלִין עִמֵּיהּ לַתֵּיבָה. אוּף הָכִי אִלֵּין דִּמְנַטְּרִין חַגִּין וּזְמַנִין, דְּאִינּוּן יָמִים טוֹבִים, שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה, שְׁנַיִם שְׁנַיִם תְּרֵין יוֹמִין דְרֹאשׁ הַשָּׁנָה, וּתְרֵין יוֹמִין דְּשָׁבוּעוֹת, וּבְגִין דְּאִינּוּן תְּרֵין מִנַּיְיהוּ בְּסָפֵק, הָא אִית שְׁנֵי יְמֵי הַפּוּרִים בְּאַתְרַיְיהוּ. שִׁבְעָה שִׁבְעָה, ז' יוֹמִין דְּפֶסַח, ז' יוֹמִין דְּסוּכּוֹת. נֹחַ לָקֳבֵל יוֹם הַשַּׁבָּת, וְהַאי אִיהוּ מִכָּל הַחַי.","סֻכָּה קָא אֲגִינָת עָלַיְיהוּ דְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (ישעיהו ד׳:ו׳) וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם מֵחֹרֶב. סֻכָּה קָא אֲגִינָת. מַה תֵּיבַת נֹחַ לְאַגָּנָא, אוּף הָכִי סֻכָּה לְאַגָּנָא. (תיקונין ב ע\"א) וְעוֹד מִכָּל הַחַי, ח\"י בִּרְכָאן דִּצְלוֹתָא, מֵאִינּוּן ט' ט', בִּרְכָתָא דְּמִינִין בָּהּ אִשְׁתְּלִימוּ י' סְפִירָאן מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא. וְאִיהוּ לָקֳבֵל נֹחַ.","וְעוֹד מִכָּל הַחַי, שְׁכִינְתָּא אֲגִינָת עַל אִלֵּין דְּנַטְרִין י', אוֹת שַׁבָּת בִּתְחוּמָא דִּילֵיהּ, דְּאִיהוּ ח' אֲלָפִים, תְּרֵין אַלְפִין לְכָל צַד. וְעוֹד, מִכָּל הַחַי, אִלֵּין דְּנַטְרִין י' אוֹת בְּרִית, דְּאִיהוּ בְּח' יוֹמִין, דְּאִתְּמַר עָלַיְיהוּ, (ויקרא י״ב:ג׳) וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. וְעוֹד, מִכָּל הָחַי, אִלֵּין דְּנַטְרִין אוֹת י', תְּפִלִּין בִּתְמַנְיָיא פָּרַשְׁיָין.","שְׁכִינְתָּא דְּאִיהִי סוּכָּה, אֲגִינָת עָלַיְיהוּ, וּפְרִישַׁת גַּדְפָּאָה עָלַיְיהוּ, כְּאִמָּא עַל בְּנִין, וּבְגִין דָּא תַּקִּינוּ לְבָרְכָא, הַפּוֹרֵס סוּכַּת שָׁלוֹם עָלֵינוּ. וּבְגִין דָּא בְּיַרְחָא שְׁבִיעָאָה, דְּבֵיהּ כָּל פִּקּוּדִין אִלֵּין, (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. עַם יִשְׂרָאֵל בַּאֲבוּהוֹן שֶׁבַּשָּׁמַיִם. וְלֵית מַיִם רַבִּים, אֶלָּא כָּל אוּמִין וּמְמָנָן דִּלְהוֹן. אִם יִתֵּן אִישׁ, דְּאִיהוּ סָמָאֵל, כָּל מַה דְּאִית לֵיהּ בְּעָלְמָא דֵּין, בְּגִין דְּיִשְׁתָּתַּף בְּאִלֵּין פִּקוּדִין עִם יִשְׂרָאֵל, בּוֹז יָבוּזוּ לוֹ."],[[0,"לולב בימין כליל","וכו': הלולב נלקח ביד, ימין, וכלול ששה, שהם, ג' הדסים, כנגד גדולה גבורה תפארת, והם דומים לג' צבעים שבעין, שהם לבן אדום ירוק. ב' בדי ערבות הם, נצח והוד, ודומים לב' שפתיים. הלולב, הוא יסוד, ודומה לשדרה, שבו קיום כל העצמות, ועליו אמר דוד, כל עצמותי תאמרנה ה' מי כמוך. האתרוג הוא מלכות, ודומה ללב, שבו הרהורים."],[1,"ונענועין דהלל אינון","וכו': והנענועים של הלל הם משותפים בנענועים של נטילת לולב, והם ח\"י נענועים באנא ה' הושיעה נא, ח\"י ח\"י בהודו הראשון והאחרון, ח\"י שבנטילת לולב, הרי ע\"ב נענועים. ומשום זה לולב בחשבון ס\"ח, ועם ד' מינים דלולב הוא בחשבון ע\"ב, והוא בחשבון חסד, שהוא זרוע הימין. ומשום זה, התקינו, שהלולב יהיה בימין, לצד החסד, והאתרוג לצד הגבורה לשמאל, כנגד הלב. ומשום זה אתרוג הדומה ללב, התקינו שיהיה ביד שמאל. כמו שהעמידו, לולב בימין ואתרוג בשמאלו, והם כנגד זכור ושמור. ומי הוא הנוטל את שניהם, הלולב והאתרוג, הוא עמוד האמצעי, דהיינו ז\"א, הלולב הוא בימינו ואתרוג בשמאלו."],[2,"אתו אבהן","וכו': באו האבות, ורעיא מהימנא, ואהרן דוד ושלמה (עי' לעיל אות תתי\"ד) וברכו אותו, את ר\"ש, ואמרו אליו, אתה מאור קדוש, והחברים שלך שהם ששה, כנגד אלו ז' ספירות, ואתה מאור הקדוש נר מערבי באמצע של כל ששה נרות שהם מאירים ממך. ובכל אחד נאמר בו, נר ה' נשמת אדם. ורעיא מהימנא מאיר בך, ואתה בהחברים שלך וכולכם אחד בלא פרוד כלל. ומשם ואילך מתפשטים ענפים, דהיינו הארות, לכל בעלי החכמה. השלם הדברים, של חבור הראשון שלך, לעטר אותם."],[3,"פתח בוצינא קדישא","וכו': פתח המאור הקדוש ואמר, מים רבים לא יוכלו לכבות את האהבה וגו' \u0003בוז\u0004 יבוזו לו, מהו \u0003בוז.\u0004 הוא יום השני ויום הששי, ויום השביעי של סוכות, שבהם היו מנסכים יין ומים."],[4,"דשבע יומין דסוכות","וכו': כי שבעת ימים של סוכות, בהם היו מקריבים ישראל ע' פרים, לכפר על ע' שרים של ע' האומות, כדי שלא ישאר העולם חרוב מהם. ז\"ש ובחמשה עשר יום והקרבתם עולה אשה לריח ניחוח לה' פרים בני בקר שלשה עשר תמימים. וביום השני פרים י\"ב, וביום השלישי י\"א, וביום הרביעי יוד, וביום החמישי פרים תשעה, וביום הששי פרים שמונה, וביום השביעי שבעה. וכולם יחד הם שבעים פרים, ובכל יום היו מתמעטים. שואל, למה מתמעטים."],[5,"אלא הכא קא רמיז","וכו': ומשיב, אלא כאן מרמז הכתוב, ותנח התיבה בחדש השביעי, שהוא תשרי, ומה שם בימי המבול, והמים הלכו הלוך וחסור, אף כאן בתשרי שהוא חדש השביעי, שבו כמה מצות ראש השנה ויום הכפורים, סוכה לולב ואתרוג, ומינין של הלולב ושופר, הנה השכינה העליונה שורה על ישראל, שהיא תשובה, דהיינו בינה הנקראת תשובה, שה\"ס סוכה. ואתרוג שהוא מלכות, ולולב, שהוא הקב\"ה, דהיינו ז\"א. מיד והמים היו הלוך וחסור, שמתמעטים עונות ישראל, אף כך מתמעטים הממונים שהם מלאכי חבלה שממונים עליהם, על העונות, הדומים למי המבול. כמו שהעמידו, עשה עבירה אחת קנה לו קטיגור אחד. ובעת ההיא שמתמעטים העונות, מתמעטים הפרים שלהם, ומתמעטים הממונים של ע' אומות, ומתמעטים ע' אומות, ומתמעט הטוב שלהם."],[6,"תיבת נח מני","וכו': בתיבת נח, צוה הקב\"ה, להכניס עמו \u0003שנים שנים שבעה שבעה\u0004 זכר ונקבה, להיות לקרבן להגין על נח ועל כל אלו שנכנסו עמו לתיבה. אף כך, אלו השומרים חגים וזמנים, שהם ימים טובים, הם \u0003שנים שנים שבעה שבעה,\u0004 שנים שנים הם ב' ימים דראש השנה וב' ימים דשבועות, ומשום שאלו השנים דשבועות הם מחמת ספק, הרי יש שני ימי הפורים במקומם. \u0003שבעה שבעה,\u0004 הם, שבעת ימי הפסח, ושבעת ימי סוכות. נח הוא כנגד יום השבת. וזה הוא שכתוב \u0003מכל החי.\u0004 כי שנים שנים ושבעה שבעה הם ביחד בחשבון \u0003ח\"י.\u0004"],[7,"סכה קא אגינת","וכו': הסוכה מגינה על ישראל, ז\"ש, וסכה תהיה לצל יומם מחרב וגו'. הרי שהסוכה מגינה. מה תיבת נח היא להגין אף סוכה היא להגין. ועוד, \u0003מכל החי.\u0004 היינו ח\"י ברכות התפלה. מהן מתחלקות לתשע תשע ברכות, ועם ברכת המינים נשלמות יוד ספירות, שהיא משלמת ל \u0003י',\u0004 לט' הראשונות ולט' האחרונות. והם כנגד עשר ספירות דאור ישר שממעלה למטה, וע\"ס דאור חוזר, שממטה למעלה. והוא כנגד נח. כלומר שח\"י ברכות התפלה הם כנגד \u0003ח\"י\u0004 דנח, שהם שנים שנים שבעה שבעה שבגימטריא \u0003ח\"י\u0004."],[8,"ועוד מכל החי","וכו': ועוד. מכל החי, היינו שהשכינה מגינה על אלו השומרים את ה \u0003י'\u0004 שהיא אות שבת. ובגבול שלו, שהוא ח' אלפים אמה, דהיינו ב' אלפים לכל צד. וה \u0003י'\u0004 דאות שבת וח' של הגבול, הם \u0003ח\"י,\u0004 ועוד. מכל החי. היינו אלו השומרים אות ברית שהוא \u0003י'\u0004 שהוא לשמונת ימים שנאמר עליהם, וביום השמיני ימול בשר ערלתו. ה \u0003י'\u0004 דאות ברית וה \u0003ח'\u0004 של ח' ימים הם \u0003ח\"י,\u0004 ועוד. מכל החי. אלו השומרים אות תפלין שהוא \u0003י',\u0004 שבהם שמונה פרשיות, הרי הם \u0003ח\"י.\u0004"],[9,"שכינתא דאיהי סוכה","וכו': השכינה שהיא הסוכה, מגינה עליהם ופורשת כנפיה עליהם כמו אם על הבנים. ומשום זה התקינו לברך הפורס סוכת שלום עלינו. ומשום זה, בחדש השביעי, שבו כל אלו המצות, מים רבים לא יוכלו לכבות את האהבה של ישראל באביהם שבשמים. ואין מים רבים, אלא כל האומות והשרים שלהם. אם יתן איש, שזה סמאל, כל מה שיש לו בעולם הזה, כדי שישתתף באלו המצות עם ישראל, בוז יבוזו לו."]],[[0,"","לוּלָב בְּיָמִין, כּוֹלֵל שִׁשָּׁה מִינִים (שהם) שְׁלֹשָׁה הֲדַסִּים - גְּדֻלָּה גְּבוּרָה תִּפְאֶרֶת. וְדוֹמִים לִשְׁלֹשֶׁת גּוֹנֵי הָעַיִן. שְׁנֵי בַּדֵּי עֲרָבוֹת - נֵצַח וְהוֹד, וְדוֹמִים לִשְׁתֵּי שְׂפָתַיִם. לוּלָב - יְסוֹד, דּוֹמֶה לַשִּׁדְרָה, שֶׁבּוֹ קִיּוּם שֶׁל כָּל הָעֲצָמוֹת, וְעָלָיו אָמַר דָּוִד, (תהלים לה) כָּל עַצְמוֹתַי תֹאמַרְנָה ה' מִי כָמוֹךְ. אֶתְרוֹג - מַלְכוּת, דּוֹמֶה לַלֵּב, שֶׁבּוֹ הַהִ רְהוּרִים."],[1,"","וְנִעִִנוּעֵי הַהַלֵּל הֵם מְשֻׁתָּפִים בַּנִּעְנוּעִים שֶׁל נְטִילַת לוּלָב, וְהֵם שְׁמוֹנָה עָשָׂר בְּ\"אָנָּא\". שְׁמוֹנָה עָשָׂר שְׁמוֹנָה עָשָׂר בְּהוֹדוּ תְּחִלָּה וָסוֹף, שְׁמוֹנָה עָשָׂר שֶׁל נְטִילַת לוּלָב - הֲרֵי ע\"ב. וּמִפְּנֵי זֶה לוּלָב בְּחֶשְׁבּוֹן ח\"ס, וְאַרְבָּעָה מִינֵי הַלּוּלָב - הֲרֵי חֶסֶד, זְרוֹעַ יָמִין. וּמִפְּנֵי זֶה תִּקְּנוּ לוּלָב בְּיָמִין, לְצַד הַחֶסֶד. אֶתְרוֹג לְצַד הַגְּבוּרָה, לִשְׂמֹאל הַלֵּב. וּמִפְּנֵי זֶה אֶתְרוֹג הַדּוֹמֶה לַלֵּב, תִּקְּנוּ לִהְיוֹת בְּיַד שְׂמֹאל. כְּמוֹ שֶׁפֵּרְשׁוּהוּ, לוּלָב בְּיָמִין, וְאֶתְרוֹג בִּשְׂמֹאלוֹ. וְהֵם כְּנֶגֶד זָכוֹר וְשָׁמוֹר. וּמִי נָטַל שְׁנֵיהֶם? הָעַמּוּד הָאֶמְצָעִי. לוּלָב בִּימִינוֹ, וְאֶתְרוֹג בִּשְׂמֹאלוֹ."],[2,"","בָּאוּ הָאָבוֹת, וְהָרוֹעֶה הַנֶּאֱמָן, וְאַהֲרֹן וְדָוִד וּשְׁלֹמֹה, וּבֵרְכוּ אוֹתוֹ וְאָמְרוּ לוֹ, אַתָּה הַמְּנוֹרָה הַקְּדוֹשָׁה, וְהַחֲבֵרִים שֶׁלְּךְ שֶׁהֵם שִׁשָּׁה, כְּנֶגֶד אֵלּוּ שֶׁהֵם שִׁבְעָה. וְאַתָּה הַמְּנוֹרָה הַקְּדוֹשָׁה, נֵר מַעֲרָבִי בָּאֶמְצַע, שֶׁכָּל שִׁשָּׁה נֵרוֹת מְאִירִים מִמְּךְ. בְּכָל אֶחָד נֶאֱמַר בּוֹ, (משלי כ) נֵר ה' נִשְׁמַת אָדָם. וְהָרוֹעֶה הַנֶּאֱמָן מֵאִיר בְּךְ, וְאַתָּה בַּחֲבֵרִים שֶׁלְּךְ, וְהַכֹּל אֶחָד בְּלִי פֵרוּד כְּלָל. וּמִשָּׁם וְאֵילָךְ מִתְפַּשְּׁטִים עֲנָפִים לְכָל בַּעֲלֵי הַחָכְמָה, הַשְׁלֵם דִּבְרֵי הַחֲבוּרָה הָרִאשׁוֹנָה שֶׁלְּךְ לְעַטֵּר אוֹתָם."],[3,"","פָּתַח הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, בַּחִבּוּר הָרִאשׁוֹן נֶאֱמַר, (שיר השירים ח) מַיִם לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה וְגוֹ'. מַהוּ בּוֹז? יוֹם שֵׁנִי וְיוֹם שִׁשִּׁי וְיוֹם שְׁבִיעִי שֶׁל סֻכּוֹת, שֶׁבָּהֶם הָיוּ מְנַסְּכִים מַיִם וְיַיִן."],[4,"","שִׁבְעָה יְמֵי סֻכּוֹת בָּהֶם הָיוּ מַקְרִיבִים יִשְׂרָאֵל שִׁבְעִים פָּרִים לְכַפֵּר עַל שִׁבְעִים מְמֻנִּים כְּדֵי שֶׁלֹּא יִשָּׁאֵר הָעוֹלָם חָרוּב מֵהֶם. זֶהוּ שֶׁכָּתוּב וּבַחֲמִשָּׁה עָשָׂר יוֹם וְהִקְרַבְתֶּם עֹלָה אִשֶּׁה לְרֵיחַ נִיחֹחַ לַה' פָּרִים בְּנֵי בָקָר שְׁלֹשָׁה עָשָׂר תְּמִימִים. וּבַיּוֹם הַשֵּׁנִי פָּרִים שְׁנֵים עָשָׂר. וּבַיּוֹם הַשְּׁלִישִׁי אַחַד עָשָׂר. וּבַיּוֹם הָרְבִיעִי עֲשָׂרָה. וּבַיּוֹם הַחֲמִישִׁי פָּרִים תִּשְׁעָה. וּבַיּוֹם הַשִּׁשִּׁי פָּרִים שְׁמוֹנָה. וּבַיּוֹם הַשְּׁבִיעִי שִׁבְעָה. וְכֻלָּם שִׁבְעִים. וּבְכָל יוֹם הָיוּ חֲסֵרִים. מַדּוּעַ חֲסֵרִים?"],[5,"","אֶלָּא כָּאן הוּא רָמוּז, (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי. וּמַה שָּׁם בִּימֵי הַמַּבּוּל (שם) וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר - אַף כָּךְ בְּתִשְׁרֵי, שֶׁהוּא הַחֹדֶשׁ הַשְּׁבִיעִי, שֶׁבּוֹ כַּמָּה מִצְווֹת: רֹאשׁ הַשָּׁנָה, וְיוֹם הַכִּפּוּרִים, סֻכָּה וְלוּלָב, אֶתְרוֹג, מִינִים שֶׁל הַלּוּלָב, שׁוֹפָר - הַשְּׁכִינָה הָעֶלְיוֹנָה שׁוֹרָה עַל יִשְׂרָאֵל, שֶׁהִיא תְּשׁוּבָה, סֻכָּה, אֶתְרוֹג, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא לוּלָב. מִיָּד - וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר. מִתְמַעֲטִים הַחֲטָאִים שֶׁל יִשְׂרָאֵל. אַף כָּךְ מִתְמַעֲטִים הַמְמֻנִּים, שֶׁהֵם מַלְאֲכֵי הַחַבָּלָה שֶׁמְּמֻנִּים עֲלֵיהֶם שֶׁדּוֹמִים לְמֵי הַמַּבּוּל. כְּמוֹ שֶׁפֵּרְשׁוּהוּ, עָשָׂה עֲבֵרָה אַחַת, קָנָה לוֹ קָטֵגוֹר אֶחָד. בְּאוֹתוֹ זְמַן שֶׁמִּתְמַעֲטִים הַחֲטָאִים, מִתְמַעֲטִים הַפָּרִים שֶׁלָּהֶם, מִתְמַעֲטִים הַמְמֻנִּים שֶׁל שִׁבְעִים אֻמּוֹת, מִתְמַעֲטִים שִׁבְעִים אֻמּוֹת, מִתְמַעֵט הַטּוֹב שֶׁלָּהֶם."],[6,"","תֵּבַת נֹחַ, צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכְנִיס עִמּוֹ שְׁנַיִם שְׁנַיִם (בראשית ז) שִׁבְעָה שִׁבְעָה זָכָר וּנְקֵבָה, לְקָרְבָּן, לְהָגֵן עַל נֹחַ וְעַל כָּל אֵלּוּ שֶׁנִּכְנָסִים עִמּוֹ לַתֵּבָה. אַף כָּךְ אֵלּוּ שֶׁשּׁוֹמְרִים חַגִּים וּזְמַנִּים, שֶׁהֵם יָמִים טוֹבִים, שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה. שְׁנַיִם שְׁנַיִם - שְׁנֵי יְמֵי רֹאשׁ הַשָּׁנָה וּשְׁנֵי יָמִים שֶׁל שָׁבוּעוֹת. וּמִפְּנֵי שֶׁאֵלּוּ שְׁנַיִם מֵהֶם בְּסָפֵק, הֲרֵי שְׁנֵי יְמֵי הַפּוּרִים בִּמְקוֹמָם. שִׁבְעָה שִׁבְעָה - שִׁבְעַת יְמֵי הַפֶּסַח, שִׁבְעַת יְמֵי הַסֻּכּוֹת. נֹחַ כְּנֶגֶד יוֹם הַשַּׁבָּת, וְזֶהוּ (שם ו) מִכָּל הָחַי."],[7,"","הַסֻּכָּה מְגִנָּה עַל יִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב (ישעיה ד) וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם מֵחֹרֶב. הַסֻּכָּה הִיא מְגִנָּה. מַה תֵּבַת נֹחַ לְהָגֵן, אַף כָּךְ סֻכָּה לְהָגֵן. וְעוֹד מִכָּל הָחַי - ח\"י בִּרְכוֹת הַתְּפִלָּה, וְהֵן תֵּשַׁע תֵּשַׁע. בִּרְכַּת הַמִּינִים בָּהּ נִשְׁלָמוֹת עֶשֶׂר סְפִירוֹת מִמַּעְלָה לְמַטָּה וּמִמַּטָּה לְמַעְלָה, וְהִיא כְּנֶגֶד נֹחַ."],[8,"","וְעוֹד מִכָּל הָחַי - הַשְּׁכִינָה מְגִנָּה עַל אֵלּוּ שֶׁשּׁוֹמְרִים י', אוֹת שַׁבָּת בַּתְּחוּם שֶׁלּוֹ, שֶׁהוּא שְׁמוֹנַת אֲלָפִים, אַלְפַּיִם לְכָל צַד. וְעוֹד מִכָּל הָחַי - אֵלּוּ שֶׁשּׁוֹמְרִים י', אוֹת בְּרִית, שֶׁהוּא בִּשְׁמוֹנָה יָמִים, שֶׁנֶּאֱמַר עֲלֵיהֶם, (ויקרא יב) וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. וְעוֹד מִכָּל הָחַי - אֵלּוּ שֶׁשּׁוֹמְרִים אוֹת י', תְּפִלִּין בִּשְׁמוֹנֶה פָּרָשִׁיּוֹת."],[9,"","הַשְּׁכִינָה, שֶׁהִיא סֻכָּה, מְגִנָּה עֲלֵיהֶם, וּפוֹרֶשֶׂת כְּנָפָהּ עֲלֵיהֶם כְּאִמָּא עַל בָּנִים, וּמִפְּנֵי זֶה תִּקְּנוּ לְבָרֵךְ הַפּוֹרֵס סֻכַּת שָׁלוֹם עָלֵינוּ. וּמִפְּנֵי זֶה בַּחֹדֶשׁ הַשְּׁבִיעִי, שֶׁבּוֹ כָּל מִצְווֹת אֵלּוּ, (שיר השירים ח) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה, עַם יִשְׂרָאֵל בַּאֲבִיהֶם שֶׁבַּשָּׁמַיִם. וְאֵין מַיִם רַבִּים אֶלָּא כָּל הָאֻמּוֹת וְהַמְמֻנִּים שֶׁלָּהֶם. אִם יִתֵּן אִישׁ, שֶׁהוּא סָמָאֵל, כָּל מַה שֶּׁיֵּשׁ לוֹ בָּעוֹלָם הַזֶּה, כְּדֵי שֶׁיִּשְׁתַּתֵּף בְּאֵלּוּ הַמִּצְווֹת עִם יִשְׂרָאֵל - בּוֹז יָבוּזוּ לוֹ."]]],[["וּבַיּוֹם הַשְּׁמִינִי עֲצֶרֶת פַּר אֶחָד אַיִל אֶחָד, הָא אוּקְמוּהָ מָארֵי מַתְנִיתִין, לְמַלְכָּא דְּזַמִּין אוּשְׁפִּיזִין, לְבָתַר דְּשָׁלַח לוֹן, אָמַר לְאִלֵּין בְּנֵי בֵּיתָא דִּילֵיהּ, אֲנָא וְאַתּוּן נַּעְבִיד סְעוּדָה קְטַנָּה. וּמַאי עֲצֶרֶת. כְּמָה דְאַתְּ אָמֵר, (שמואל א ט׳:י״ז) זֶה יַעְצוֹר בְּעַמִּי, וְלֵית עֶצֶר אֶלָּא מַלְכוּת. מִסִּטְרָא דִּשְׁכִינְתָּא עִלָּאָה, עָבִיד סְעוּדָתָא רַבְרְבָא, וּמִסִּטְרָא דְּמַלְכוּתָא, סְעוּדָתָא זְעֵירָא. וְנוֹהֲגִין לְמֶעְבַּד יִשְׂרָאֵל עִמָּהּ חֶדְוָה, וְאִתְקְרִיאַת שִׂמְחַת תּוֹרָה. וּמְעַטְּרָן לְסֵפֶר תּוֹרָה בְּכֶתֶר דִּילֵיהּ, רֶמֶז סֵפֶר תּוֹרָה לְתִפְאֶרֶת, שְׁכִינְתָּא עֲטֶרֶת תִּפְאֶרֶת.","אָמַר רִבִּי אֶלְעָזָר, אַבָּא, אֲמַאי מִסִּטְרָא דְּאִמָּא עִלָּאָה, זַמִּין לְכָל מְמָנָן דְּכָל אוּמִין, וּמִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה, לָא זַמִּין אֶלָּא לְאוּמָה יְחִידָה, לָקֳבֵל פַּר יְחִידָא.","אָמַר לֵיהּ בְּרִי, שַׁפִּיר שְׁאִילַת. בְּגִין דְּמַלְכוּת אִיהִי רְמִיזָא לִבְרַתָּא, דְּאִיהִי צְנוּעָה בְּבֵית אָבִיהָ וְאִמָּהּ. וְאִיהִי אֲרוּסָה וְלָא נְשׂוּאָה. לָאו אוֹרַח אַרְעָא, לְמֵיכַל עִם אוֹשְׁפִּיזִין. אֲבָל אִימָּא דְּהִיא נְשׂוּאָה, אוֹרַח אַרְעָא אִיהוּ (למיכל עם אורחי) בָּתַר דִּמַזְמִּין בַּעְלָהּ אוֹשְׁפִּיזֵי, לְמֵיכַל עַל פָּתוֹרָא עִם בַּעְלָהּ. וְאִי אִינּוּן אוּשְׁפִּיזִין נֻכְרָאִין, לָא אַכְלֵי עִמְּהוֹן, לָא אַבָּא, וְלָא אִמָּא, וְכָל שֶׁכֵּן בְּרַתָּא. וּבְגִין כַּךְ בִּסְעוּדָתָא דְּשִׁבְעִין מְמָנָן, לָא אִשְׁתְּתַּף לְמֵיכַל עִמְּהוֹן, חַד מִן מָארֵי מַלְכָּא, בְּגִין דְּאִינּוּן נוּכְרָאִין. אָמַר לֵיהּ ודַּאי כְּעַן אִתְיַישְּׁבַת מִלָּה בְּלִבָּאִי, עַל בּוּרְיֵיהּ.","עוֹלַת תָּמִיד, דָּא שְׁכִינְתָּא, דִּסְלִיקַת לְעֵילָּא בְּהַהוּא דַּרְגָּא, דְּאִתְּמַר בָּהּ עֶרֶב וָבוֹקֶר בְּכָל יוֹם תָּמִיד, וְאוֹמְרִים פַּעֲמַיִם שְׁמַע יִשְׂרָאֵל. וְאִיהִי סְלִיקַת בְּעַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִיהוּ תָּדִיר עִמָּהּ בְּלָא פִּרוּדָא כְּלָל.","וּלְאָן סְלִיקַת. לְאֲתָר דְּאִתְגְּזָרַת מִתַּמָּן, דְּאִיהוּ אֵין סוֹף, וְאִיהוּ גָּבוֹהַּ מִכָּל סְפִירָאן. וּבְגִין דָּא אוֹקְמוּהָ. עוֹלָה כֻּלָהּ לַגָּבוֹהַּ סַלְּקָא. וְכַד אִיהִי סְלִיקַת, אֲחִידָן בָּהּ כָּל סְפִירָן, וְאִינּוּן סַלְּקִין עִמָּהּ. וּמַאי סְלִיקוּ דִּילָהּ. לְרֵיחַ נִיחֹחַ, לְמֵיהַב רֵיחָא טָבָא קֳדָם יְיָ, וּלְבָתַר אִתְּמַר בָּהּ, (ויקרא ט׳:כ״ב) וַיֵּרֶד מֵעֲשׂוֹת הַחַטָּאת וְהָעוֹלָה. נַחְתַּת מַלְיָא כַּפָּרָה מִכָּל חוֹבִין דְּיִשְׂרָאֵל.","וְהָא סְלִיקוּ דִּילָהּ אִיהוּ, בְּעַמּוּדָא דְּאֶמְצָעִיתָא. אוּף הָכִי נְחִיתוּ דִּילָהּ אִיהוּ בֵּיהּ, וְכָל חַיָּילִין דִּילָהּ, וּבְגִין דָּא אִקְרֵי סֻלָּם, דְּבֵיהּ כָּל הַוָויָין (נ\"א כנויין) סַלְּקִין וְנַחְתִּין, דְּאִינּוּן תַּלְיָין מִן יְדוָֹד. וּבְגִין דָּא, כָּל קָרְבְּנִין וְעִלָּוָון אִינּוּן לַיְדוָֹד. וְאִתְקְרִיאַת קָרְבָּן, עַל שֵׁם דְּאִתְקְרִיבוּ בָּהּ כָּל כִּנּוּיִין לַיְדוָֹד.","וּבְגִין דָּא אִתְּמַר עָלָהּ, (במדבר ז׳:י״ט) קָרְבָּנוֹ קַעֲרַת כֶּסֶף אַחַת. לֵית דַּרְגָּא דְּאִתְקְרִיב לְגַבֵּי יְדוָֹד, פָּחוּת מִנָּהּ. וְלֵית צְלוֹתָא וּפִקּוּדָא מִכָּל פִּקוּדִין דְּאוֹרַיְיתָא, וְכָל קָרְבְּנִין וְעִלָּוָון, דְּאִינּוּן לְבַר מִנָּהּ. בְּכָל דַּרְגִּין דִּסְפִירָאן לָא מִתְקַבְּלָן קֳדָם יְדוָֹד, לְבַר מִנָּהּ. וּבְגִין דָּא אִתְּמַר עָלָהּ, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. וּבְגִין דָּא אָמַר נָבִיא, (ירמיהו ט׳:כ״ג) כִּי אִם בְּזֹאת יִתְהַלֵּל הַמִּתְהַלֵּל.","אִיהִי שְׁלָמִים, שְׁלִימוּ דִּשְׁמָא דַּיְדוָֹד, בְּכָל דַּרְגָּא וְדַרְגָּא. אִיהִי ה'. אֲדֹנָי. י' דַּיְדוָֹד. אִיהִי ה' מִן אֱלֹהִים. אִיהִי ה' מִן אֶהְיֶה. י' מִן שַׁדַּי. סוֹף דְּכָל הֲוָיָה וְכִנּוּי. וּבְגִין דָּא אִתְּמַר בָּהּ, (קהלת י״ב:י״ג) סוֹף דָּבָר הַכֹּל נִשְׁמָע אֶת הָאֱלֹהִים יְרֵא וְאֶת מִצְוֹתָיו שְׁמוֹר. אִיהִי סוֹף מֵעֶשֶׂר סְפִירָאן, יַם סוּף. שְׁלִימוּ דְּעִלָּאִין וְתַתָּאִין. אִיהוּ תַּרְעָא לְאַעֲלָא לְכָל חָכְמְתָא, לְכָל כִּנּוּי וַהֲוָיָה, וּלְאַעֲלָא בְּכָל סְפִירָה וּסְפִירָה, יְדִיעָה דְּכֹלָּא. וּפָחוּת מִינָהּ, לֵית רְשׁוּ לְשׁוּם בִּרְיָה, לְאַשְׁגָּחָא לְשׁוּם יְדִיעָה בָּעוֹלָם. עָלָהּ אִתְּמַר, (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַיְיָ צַדִּיקִים יָבֹאוּ בוֹ.","אִיהוּ שֵׁם מ\"ב אַתְוָון, דִּבְהוֹן אִתְבְּרִיאוּ עִלָּאִין וְתַתָּאִין. (ואלין אינון אתוון כנויין לאתוון דהוויין דבהון אתבריאו עלאין) אִיהִי אִתְקְרִיאַת עַיִן מִסִּטְרָא דִּימִינָא, (תהילים ל״ג:י״ח) הִנֵּה עֵין יְדוָֹד אֶל יְרֵאָיו. וְאִתְקְרִיאַת אֹזֶן מִסִּטְרָא דִּשְׂמָאלָא, (דניאל ט׳:י״ח) הַטֵּה אֱלֹהַי אָזְנְךָ וּשֲׁמָע. וְאִתְקְרִיאַת רֵיחַ מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְאִתְקְרִיאַת פֶּה, מִגַּרְמָהּ. הֲדָא הוּא דִכְתִיב, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ.","אִתְקְרִיאַת פִּקּוּדָא קַדְמָאָה אָנֹכִי, מִסִּטְרָא דְּכֶתֶר, דְּאִיהוּ אַיִ\"ן מֵאֱלֹהֵינוּ. אָנֹכִי בֵּיהּ כ', כֶּתֶר. וּבֵיהּ אַיִן. וְכֶתֶר אִתְקְרֵי מִסִּטְרָא דְּאִימָּא עִלָּאָה. דְּאִדְכַּר לְגַבָּהּ חַמְשִׁין זִמְנִין יְצִיאַת מִצְרַיִם בְּאוֹרַיְיתָא. וְאִיהִי בַּ\"ת מִן בְּרֵאשִׁית, דִּכְלִילָא עֶשֶׂר אֲמִירָן, מִסִּטְרָא דְּחָכְמָה בַּת י', (משלי ג׳:י״ט) בְּחָכְמָה יָסַד אֶרֶץ. בְּאַבָּא יָסַד בְּרַתָּא. וְאִיהוּ (איוב כ״ח:ז׳) נָתִיב לֹא יְדָעוֹ עָיִט, דְּכָלִיל ל\"ב נְתִיבוֹת, דְּאִינּוּן ל\"ב אֱלֹהִים מִסִּטְרָא דְּאִימָּא עִלָּאָה, דְּאִתְקְרֵי כָּבוֹד. וְכַד אִתְכְּלִילָן בִּבְרַתָּא, אִתְקְרֵי ל\"ב. וּבְגִין דָּא כָּבוֹד לְעֵילָּא, ל\"ב לְתַתָּא.","וְי' דִּבְּרָן אִתְיְיהִיבוּ. חֲמֵשׁ בְּלוּחָא חֲדָא, וַחֲמֵשׁ בְּלוּחָא תִּנְיָינָא. אִיהִי כָּלִיל לוֹן, ה' מִכֶּתֶר עַד גְּבוּרָה. וְה' מֵעַמוּדָא דְּאֶמְצָעִיתָא, עַד בְּרַתָּא. וְאִינּוּן ה' ה'. וְכִי אִית לְמַלְּלָא בַּעֲשַׂרָה פִּיּוֹת. אֶלָּא כָּלִיל לוֹן בְּבַת יְחִידָה י' וְאִתְעָבִידוּ כֻּלְּהוּ חֲדָא. אוּף הָכִי ו', אִתְקְרֵי קוֹל, וְלָא אִשְׁתְּמוֹדְעִין בֵּיהּ, עַד דְּאִשְׁתָּתַּף עַד (ס\"א עם) דִּבּוּר. וּבְגִין דָּא, (דברים ד׳:י״ב) קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים."],[[0,"וביום השמיני עצרת","וגו': וביום השמיני עצרת וגו'. פר אחד איל אחד. הרי העמידו בעלי המשנה, למלך שהזמין אורחים ולאחר ששלח אותם, אמר לבני ביתו, אני ואתם נעשה סעודה קטנה. ומהו עצרת. הוא כש\"א, זה יעצור בעמי שאין עצר אלא מלכות. כי מצד שכינה עליונה, שהיא בינה עשה סעודה גדולה, ומצד המלכות עשה סעודה קטנה. ונוהגים ישראל לעשות עמה שמחה, ונקראת שמחת תורה. ומעטרים הספרי תורות בכתר שלהם. והרמז, שהספר תורה הוא תפארת, השכינה היא הכתר שלו דהיינו עטרת תפארת."],[1,"אמר רבי אלעזר","וכו': אר\"א, אבי, למה מצד אמא עליונה, שהיא בינה, הזמין לכל הממונים של כל האומות, דהיינו בע' פרים כנ\"ל, ומצד השכינה התחתונה לא הזמין אלא אומה יחידה, כנגד פר אחד. שהיה צריך להיות בהיפך, שישראל יקבלו מאמא עלאה ושרי האומות מן המלכות."],[2,"אמר ליה ברי","וכו': אמר לו בני יפה שאלת. והוא. משום שמלכות רומזת לבת, שהיא צנועה בבית אביה ואמה, והיא ארוסה ולא נשואה, לכן אין דרך העולם, שתאכל עם אורחים. אבל אמא שהיא נשואה, הנה דרך העולם הוא, שאחר שבעלה הזמין אורחים, שהיא תאכל עם האורחים, על השלחן עם בעלה. ואם הם אורחים זרים, אין אוכלים עמהם, לא אבא ולא אמא וכל שכן הבת, שהיא מלכות. ומשום זה בסעודה של שבעים השרים לא נשתתף לאכול עמהם אף אחד מן בני ביתו של המלך, משום שהם נכרים. אמר לו. ודאי עתה נתישב הדבר על לבי על מכונו."],[2,"","פירוש שיש כאן בסוכות ב' בחינות אורחים. כי יש אושפיזין של הסוכה שה\"ס ז' מדות דקדושה, ויש ע' שרים המקבלים מע' פרים. ושניהם מקבלים מצד אמא עלאה, שהיא בינה ולא ממלכות. והוא מטעם, כי בינה היא נשואה לאבא שהוא חכמה. והיא בתכלית השלמות וע\"כ דרכה לאכול עם האורחים שהם אושפיזין של הסוכה. אבל המלכות, היא ארוסה ולא נשואה. כי אע\"פ שיש לה זווגים עם ז\"א אינם מבחינת עצמותה, אלא מבחינת מה ששואלת מאנין דאמא (כמ\"ש בהקדמת ספר הזהר במאמר, אמא אוזיפת לברתא מאנהא דף כ' ד\"ה ואמא) ומבחינת עצמותה אינה נשואה כלל עד גמר התקון, שאז תתגלה בחינת עצמותה ותזדווג עם ז\"א. וע\"כ אינה יכולה להשפיע לאורחים הקדושים ומכ\"ש לאורחים הנכרים שהם ע' שרים. וז\"ש \u0003בגין דמלכות איהי רמיזא לברתא, דאיהי צנועה בבית אביה ואמה,\u0004 כי כל הכלים שלה הם מאבא ואמא, ובחינתה עצמה היא גנוזה וצנועה בפנימיות הכלים דאבא ואמא, דהיינו בבית או\"א. \u0003ואיהי ארוסה ולא נשואה,\u0004 כי אין לה זווג מבחינתה עצמה קודם גמר התקון. \u0003לאו אורח ארעא למיכל עם אושפיזין,\u0004 כי היא צריכה להיות גנוזה ומכוסה בכלים דאמא, ולא להגלות. \u0003אבל אמא\u0004 וכו', היא בתכלית השלמות, וכל השפע שיש בעולמות בשתא אלפי שני ממנה באים. וע\"כ היא מתגלית להאורחים. אמנם לע' שרים, אין אמא מתגלית להם, אלא נותנת להם קיומם בבחינת מה שהם מתמעטים והולכים. משום שהמה זרים ונכרים לקדושה. ורוצים להמשיך החכמה ממעלה למטה. וע\"כ הם נדחים אחר ז' ימי סוכות, ואז עושה סעודה קטנה לבני ביתו מבחינת המלכות. ואע\"פ שגם אז היא צנועה בכלים דאמא, עם כל זה כיון שמזווג הזה מקבלת גם עצמותה של המלכות את תקונה, ע\"כ היא נקראת על שמה. ותוכן הדברים תבין ממה שנתבאר לעיל (צו דף מ\"ג ד\"ה פירוש עש\"ה)."],[3,"עולת תמיד דא וכו':","עולת תמיד היא השכינה, שהיא עולה תמיד במדרגה ההיא שנאמר בה ערב ובקר בכל יום \u0003תמיד,\u0004 ואומרים פעמים שמע ישראל. והיא עולה בעמוד האמצעי, שהוא ז\"א, שהוא תמיד עמה בלי פרוד כלל."],[4,"ולאן סליקת, לאתר וכו':","ואיפה היא עולה. היינו אל המקום שנגזרה משם, שהוא אין סוף. ואז היא גבוהה מכל הספירות. ומשום זה העמידו עולה כולה לגבוה סלקא. וכשהיא עולה, נאחזות בה כל הספירות והן עולות עמה. ומהי העליה שלה לאין סוף. היינו לריח ניחח לתת ריח טוב לפני ה'. ואח\"כ נאמר בה, וירד מעשות החטאת והעולה, דהיינו שיורדת מא\"ס, מלאה כפרה על כל עונות ישראל."],[5,"והא סליקו דילה וכו':","והעליה שלה היא עם עמוד האמצעי, שהוא ז\"א, אף כך הירידה שלה, ושל כל צבאיה, היא בו. ומשום זה נקראת סולם, כי בה כל הכינוים דהיינו כל המדרגות, עולים וירדים, שהם תלוים מן השם \u0003הוי\"ה\u0004 שהוא ז\"א. ומשום זה כל הקרבנות והעולות הם ל \u0003הוי\"ה.\u0004 והיא נקראת קרבן, על שם שכל הכינוים מתקרבים בה אל \u0003הויה.\u0004 שהוא ז\"א."],[6,"ובגין דא אתמר וכו':","ומשום זה נאמר עליה, קרבנו קערת כסף אחת. שהיא המלכות. כי אין מדרגה שתתקרב להויה, בלי המלכות. ואין תפלה ומצוה מכל מצות שבתורה, ומכל הקרבנות ועולות, שיהיו מחוץ למלכות. ובכל המדרגות שבספירות, אינן מתקבלות לפני הויה מחוץ ממנה. ומשום זה נאמר עליה, ב \u0003זאת,\u0004 שהיא המלכות, הנקראת, זאת, \u0003יבא אהרן אל הקדש.\u0004 ומשום זה אמר הנביא, כי אם ב \u0003זאת\u0004 יתהלל המתהלל."],[7,"איהי שלמים שלימו וכו':","היא, המלכות, נקראת שלמים, משום שהיא השלמות של שם הויה בכל מדרגה ומדרגה. היא ה' דהויה, היא אדני, היא \u0003י'\u0004 דהויה, היא ה' של אלקים. היא \u0003ה'\u0004 מן אהיה, היא \u0003י'\u0004 מן שדי. היא סוף של כל הויה וכינוי. ומשום זה נאמר בה, \u0003סוף\u0004 דבר הכל נשמע את האלקים ירא ואת מצותיו שמור. היא סוף מעשר ספירות, שנקראת ים סוף (כנ\"ל אות תת\"ה) היא שלמות העליונים ותחתונים, היא שער לכנס לכל חכמה, לכל כנוי והויה, ולכנס בכל ספירה וספירה, היא ידיעת הכל, וזולת ע\"י המלכות אין רשות לשום בריה להסתכל בשום ידיעה שבעולם, עליה נאמר, זה השער לה' צדיקים יבואו בו."],[8,"איהו שם מ\"ב וכו':","היא, המלכות, שם של מ\"ב אותיות, דהיינו ד' אותיות הויה, ועשר אותיות המלוי, וכ\"ח אותיות דמילוי המילוי, הס מ\"ב אותיות. והמלכות ה\"ס ההין אחרונות שבשם מ\"ב, שבהם נבראו העליונים והתחתונים. היא נקראת עין מצד ימין, שהיא חכמה שבה, שכתוב, הנה עין ה' אל יראיו. ונקראת אזן מצד שמאל, שהיא בינה שבה, שכתוב, הטה אלהי אזנך ושמע. ונקראת ריח מצד עמוד האמצעי, שהוא ת\"ת שבה, ונקראת פה מבחינת עצמה, שהיא מלכות. ז\"ש פה אל פה אדבר בו."],[9,"אתקריאת פקודא קיימא וכו':","היא נקראת מצוה ראשונה, \u0003אנכי,\u0004 דהיינו תחילת גילוי אלקית, מצד הכתר שבה, שהוא \u0003אין\u0004 מן \u0003א\u0004 לה \u0003ינ\u0004 ו, כי הכתר נקרא אין, מטעם אפיסת ההשגה. \u0003אנכי,\u0004 בו \u0003כ',\u0004 שהיא כתר ובו אותיות \u0003אין,\u0004 וכתר נקראת מצד אמא עלאה, שנזכר לה חמשים פעמים יציאת מצרים בתורה. שהם כנגד חמשים שערי בינה. (כנ\"ל יתרו אות שפט) וכתר של מלכות הוא בבינה. והיא בת מן \u0003ב\u0004 ראשי \u0003ת\u0004 הכולל כל עשרה המאמרות דמעשה בראשית. ומצד החכמה היא, בת \u0003י',\u0004 כמ\"ש בחכמה יסד ארץ, דהיינו המלכות שנקראת ארץ. כי אבא, שהוא חכמה, יסד הבת, שהיא המלכות, והיא \u0003הנתיב\u0004 שלא ידעו עיט, הכולל ל\"ב נתיבות, שהם ל\"ב שמות אלקים מצד אמא עלאה הנקראת כבוד. וכשנכללים בבת, שהיא המלכות נקראת המלכות \u0003לב.\u0004 ומשום זה כבוד למעלה, \u0003לב\u0004 למטה. (כנ\"ל אות תשי\"א)."],[10,"ויוד דברן אתייהיבו וכו':","ועשרת הדברות ניתנו חמש בלוח אחד, וחמש בלוח השני, והמלכות כוללת אותן, שהן חמש ספירות מכתר עד גבורה, וחמש ספירות מעמוד האמצעי שהוא ת\"ת עד הבת שהיא מלכות. והן ב\"פ ה' ה'. שואל, אם עשרת הדברות הם מעשר ספירות, וכי אפשר לדבר בעשרה פיות, שכל ספירה תדבר בפה מיוחד שלה. ומשיב, אלא שכלל כל עשרת הדברות בבת יחידה, שהיא המלכות, ונעשו כולן אחת. הרי שעשרת הדברות נכללו במלכות. ואף כך הוא \u0003ו'\u0004 שהיא ת\"ת, הנקראת קול, שאין להשיג בו עד שמתחבר עם דבור, שהוא מלכות. ומשום זה כתוב, \u0003קול דברים\u0004 אתם שומעים, אשר קול רומז לז\"א, ודברים למלכות."]],[[0,"","וּבַיּוֹם הַשְּׁמִינִי עֲצֶרֶת, פָּר אֶחָד אַיִל אֶחָד. הֲרֵי פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, לְמֶלֶךְ שֶׁזִּמֵּן אוֹרְחִים, לְאַחַר שֶׁשָּׁלַח אוֹתָם, אָמַר לְאֵלּוּ בְּנֵי בֵיתוֹ: אֲנִי וְאַתֶּם נַעֲשֶׂה סְעוּדָה קְטַנָּה. וּמָה עֲצֶרֶת? כְּמוֹ שֶׁנֶּאֱמַר (שמואל אט) זֶה יַעְצֹר בְּעַמִּי, וְאֵין עֶצֶר אֶלָּא מַלְכוּת. מִצַּד הַשְּׁכִינָה הָעֶלְיוֹנָה עוֹשֶׂה סְעוּדָה גְּדוֹלָה, וּמִצַּד הַמַּלְכוּת סְעוּדָה קְטַנָּה. וְנוֹהֲגִין לַעֲשׂוֹת יִשְׂרָאֵל עִמָּהּ שִׂמְחָה, וְנִקְרֵאת שִׂמְחַת תּוֹרָה. וּמְעַטְּרִים לַסֵּפֶר תּוֹרָה בַּכֶּתֶר שֶׁלּוֹ, רֶמֶז סֵפֶר תּוֹרָה לְתִפְאֶרֶת, הַשְּׁכִינָה - עֲטֶרֶת תִּפְאֶרֶת."],[1,"","אָמַר רַבִּי אֶלְעָזָר, אַבָּא, מַדּוּעַ מִצַּד הָאִמָּא הָעֶלְיוֹנָה מְזַמֵּן כָּל הַמְמֻנִּים שֶׁל כָּל הָאֻמּוֹת, וּמִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה לֹא מְזַמֵּן אֶלָּא אֻמָּה יְחִידָה, כְּנֶגֶד פַּר יָחִיד?"],[2,"","אָמַר לוֹ, בְּנִי, טוֹב שָׁאַלְתָּ. מִפְּנֵי שֶׁמַּלְכוּת הִיא רוֹמֶזֶת לְבַת, שֶׁהִיא צְנוּעָה בְּבֵית אָבִיהָ וְאִמָּהּ. וְהִיא אֲרוּסָה וְלֹא נְשׂוּאָה. אֵין דֶּרֶךְ אֶרֶץ לֶאֱכֹל עִם אוֹרְחִים. אֲבָל אִמָּא שֶׁהִיא נְשׂוּאָה, דֶּרֶךְ אֶרֶץ הוּא (לאכל עם האורחים) אַחַר שֶׁמַּזְמִין בַּעְלָהּ אוֹרְחִים לֶאֱכֹל עַל הַשֻּׁלְחָן עִם בַּעְלָהּ. וְאִם הֵם אוֹרְחִים נָכְרִים, לֹא אוֹכְלִים עִמָּהֶם לֹא אַבָּא וְלֹא אִמָּא, וְכָל שֶׁכֵּן הַבַּת. וּמִשּׁוּם כָּךְ בַּסְּעוּדָה שֶׁל שִׁבְעִים הַמְמֻנִּים לֹא מִשְׁתַּתֵּף לֶאֱכֹל עִמָּהֶם אֶחָד מִבַּעֲלֵי הַמֶּלֶךְ, מִפְּנֵי שֶׁהֵם נָכְרִים. אָמַר לוֹ, וַדַּאי עַתָּה יִתְיַשֵּׁב הַדָּבָר בְּלִבִּי עַל בֻּרְיוֹ."],[3,"","עֹלַת תָּמִיד - זוֹ הַשְּׁכִינָה, שֶׁעוֹלָה לְמַעְלָה בְּאוֹתָהּ דַּרְגָּה, שֶׁנֶּאֱמַר בָּהּ עֶרֶב וָבֹקֶר בְּכָל יוֹם תָּמִיד אוֹמְרִים פַּעֲמַיִם שְׁמַע יִשְׂרָאֵל. וְהִיא עוֹלָה בָּעַמּוּד הָאֶמְצָעִי, שֶׁהוּא תָּדִיר עִמָּהּ בְּלִי פֵרוּד כְּלָל."],[4,"","וּלְאָן עוֹלָה? לְמָקוֹם שֶׁנִּגְזְרָה מִשָּׁם, שֶׁהוּא אֵין סוֹף, וְהוּא גָּבוֹהַּ מִכָּל הַסְּפִירוֹת. וּמִפְּנֵי זֶה פֵּרְשׁוּהָ, עוֹלָה - כֻּלָּהּ לְגָבוֹהַּ עוֹלָה. וְכַאֲשֶׁר הִא עוֹלָה, אוֹחֲזוֹת בָּהּ כָּל הַסְּפִירוֹת, וְהֵן עוֹלוֹת עִמָּהּ. וּמָה הָעֲלִיָּה שֶׁלָּהּ? לְרֵיחַ נִיחֹחַ, לָתֵת רֵיחַ טוֹב לִפְנֵי ה', וְאַחַר כָּךְ נֶאֱמַר בָּהּ, (ויקרא ט) וַיֵּרֶד מֵעֲשּת הַחַטָּאת וְהָעֹלָה. יָרְדָה מְלֵאָה כַּפָּרָה מִכָּל חֲטָאֵי יִשְׂרָאֵל."],[5,"","וַהֲרֵי הָעֲלִיָּה שֶׁלָּהּ הִיא בָּעַמּוּד הָאֶמְצָעִי. וּמִפְּנֵי כָּךְ הַיְרִידָה שֶׁלָּהּ הִיא בּוֹ, וְכָל הַצְּבָאוֹת שֶׁלָּהּ. וּמִפְּנֵי זֶה נִקְרָא סֻלָּם, שֶׁבּוֹ כָּל הַהֲוָיוֹת (הכנויים) עוֹלוֹת וְיוֹרְדוֹת, שֶׁהֵן תְּלוּיוֹת מִן יְהֹוָה. וּמִפְּנֵי זֶה כָּל הַקָּרְבָּנוֹת וְהָעוֹלוֹת הֵם לַיהֹוָה. וְנִקְרֵאת קָרְבָּן עַל שֵׁם שֶׁמִּתְקָרְבִים בָּהּ כָּל הַכִּנּוּיִים לַיהֹוָה."],[6,"","וּמִפְּנֵי זֶה נֶאֱמַר עָלֶיהָ, (במדבר ז) קָרְבָּנוֹ קַעֲרַת כֶּסֶף אַחַת. אֵין דַּרְגָּה נִקְרֶבֶת לְגַבֵּי יְהֹוָה פְּחוּתָה מִמֶּנָּה. וְאֵין תְּפִלָּה וּמִצְוָה מִכָּל מִצְווֹת הַתּוֹרָה, וְכָל קָרְבָּנוֹת וְעוֹלוֹת, שֶׁהֵם לְחוּץ מִמֶּנָּה. בְּכָל דַּרְגּוֹת הַסְּפִירוֹת לֹא מִתְקַבְּלוֹת לִפְנֵי יְהֹוָה חוּץ מִמֶּנָּה. וּמִפְּנֵי זֶה נֶאֱמַר עָלֶיהָ, (ויקרא טז) בְּזֹּאת יָבא אַהֲרֹן אֶל הַקֹּדֶשׁ. וּמִפְּנֵי זֶה אָמַר הַנָּבִיא, (ירמיה ט) כִּי אִם בְּזֹּאת יִתְהַלֵּל הַמִּתְהַלֵּל."],[7,"","הִיא שְׁלָמִים, שְׁלֵמוּת הַשֵּׁם שֶׁל יְהֹוָה, בְּכָל דַּרְגָּה וְדַרְגָּה. הִיא ה'. אֲדנָי. י' שֶׁל יְהֹוָה. הִיא ה' מֵאֱלֹהִים. הִיא ה' מֵאֶהְיֶה. י' מִשַּׁדַּי. סוֹף כָּל הֲוָיָה וְכִנּוּי. וּמִפְּנֵי זֶה נֶאֱמַר בָּהּ, (קהלת יב) סוֹף דָּבָר הַכֹּל נִשְׁמָע אֶת הָאֱלֹהִים יְרָא וְאֶת מִצְוֹתָיו שְׁמוֹר. הִיא סוֹף מֵעֶשֶׂר סְפִירוֹת, יַם סוּף. שְׁלֵמוּת עֶלְיוֹנִים וְתַחְתּוֹנִים. הִיא שַׁעַר לְהִכָּנֵס לְכָל חָכְמָה, לְכָל כִּנּוּי וַהֲוָיָה, וּלְהִכָּנֵס בְּכָל סְפִירָה וּסְפִירָה, יְדִיעָה שֶׁל הַכֹּל. וּפָחוֹת מִמֶּנָּה אֵין רְשׁוּת לְשׁוּם בְּרִיָּה לְהַשְׁגִּיחַ לְשׁוּם יְדִיעָה בָּעוֹלָם. עָלֶיהָ נֶאֱמַר, (תהלים קיח) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבאוּ בוֹ."],[8,"","הִיא שֵׁם שֶׁל מ\"ב אוֹתִיּוֹת, שֶׁבָּהֶן נִבְרְאוּ עֶלְיוֹנִים וְתַחְתּוֹנִים. (ואלו הן אותיות כנויים לאותיות ההויות שבהן נבראו עליונים). הִיא נִקְרֵאת עַיִן מִצַּד הַיָּמִין, (תהלים לג) הִנֵּה עֵין יְהֹוָה אֶל יְרֵאָיו. וְנִקְרֵאת אֹזֶן מִצַּד הַשְּׂמֹאל, (דניאלט) הַטֵּה אֱלֹהַי אָזְנְךְ וּשֲׁמָע. וְנִקְרֵאת רֵיחַ מִצַּד הָעַמּוּד הָאֶמְצָעִי. וְנִקְרֵאת פֶּה מֵעַצְמָהּ. זֶהוּ שֶׁכָּתוּב (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ."],[9,"","נִקְרֵאת מִצְוָה רִאשׁוֹנָה אָנֹכִי, מִצַּד הַכֶּתֶר, שֶׁהוּא אַיִ\"ן מֵאֱלֹהֵינוּ. אָנֹכִי - בּוֹ כ', כֶּתֶר. וּבוֹ אַיִן. וְכֶתֶר נִקְרָא מִצַּד הָאִמָּא הָעֶלְיוֹנָה, שֶׁהִזְכִּיר אֶצְלָהּ חֲמִשִּׁים פְּעָמִים יְצִיאַת מִצְרַיִם בַּתּוֹרָה. וְהִיא בַּ\"ת מִבְּרֵאשִׁית, שֶׁכּוֹלֶלֶת עֶשֶׂר אֲמִירוֹת מִצַּד הַחָכְמָה, בַּת י', (משלי ג) בְּחָכְמָה יָסַד אֶרֶץ. בְּאַבָּא יָסַד הַבַּת. וְהוּא (איוב כח) נָתִיב לֹא יְדָעוֹ עָיִט, שֶׁכּוֹלֵל ל\"ב נְתִיבוֹת, שֶׁהֵם ל\"ב אֱלֹהִים מִצַּד הָאִמָּא הָעֶלְיוֹנָה, שֶׁנִּקְרֵאת כָּבוֹד. וְכַאֲשֶׁר נִכְלָלִים בַּבַּת, נִקְרָא ל\"ב. וּמִפְּנֵי זֶה כָּבוֹד לְמַעְלָה, ל\"ב לְמַטָּה."],[10,"","וַעָשָׂרָה דִּבְּרוֹת נִתְּנוּ. חֲמִשָּׁה בְּלוּחַ אֶחָד, וַחֲמִשָּׁה בְּלוּחַ שֵׁנִי. הִיא כּוֹלֶלֶת אוֹתוֹ, חֲמִשָּׁה מִכֶּתֶר עַד גְּבוּרָה, וַחֲמִשָּׁה מֵהָעַמּוּד הָאֶמְצָעִי עַד הַבַּת. וְהֵם חֲמִשָּׁה חֲמִשָּׁה. וְכִי יֵשׁ לְדַבֵּר בַּעֲשָׂרָה פִּיּוֹת? אֶלָּא כּוֹלֵל אוֹתָם בְּבַת יְחִידָה י', וְנַעֲשׂוּ כֻלָּם אֶחָד. אַף כָּךְ ו' נִקְרָא קוֹל, וְלֹא מַכִּירִים בּוֹ עַד שֶׁמִּשְׁתַּתֵּף עַד (עם) דִּבּוּר. וּמִפְּנֵי זֶה, (דברים ד) קוֹל דְּבָרִים אַתֶּם שּמְעִים."]]],[["אִיהִי פִּקּוּדָא תִּנְיָנָא מִסִּטְרָא דִּגְבוּרָה, יִרְאָה בְּחוּשְׁבָּן. וּרְמִיזָא בְּמִלַּת בְּרֵאשִׁית, יָרֵא בֹּשֶׁת. וְאוֹקְמוּהָ, מַאן דְּלֵית לֵיהּ בֹּשֶׁת פָּנִים, וַדַּאי דְּלָא עָמְדוּ אֲבָהֲתוֹי עַל טוּרָא דְּסִינַי.","אִיהִי פִּקּוּדָא תְּלִיתָאָה, דְּאִתְקְרֵי אַהֲבַת חֶסֶד. הֲדָא הוּא דִכְתִיב, (ירמיהו ל״א:ג׳) אַהֲבַת עוֹלָם אַהֲבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד. אַהֲבָה כְּלִילָא מֵאֲבָהָן, דְּאִתְקְרֵי בְּהוֹן בַּכֹּל מִכֹּל כֹּל. וְרָזָא דְּמִלָּה, (ירמיהו ב׳:ב׳) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלוֹתָיִךְ.","וְאִיהִי פִּקּוּדָא רְבִיעָאָה, יִחוּד, מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, שְׁמַע יִשְׂרָאֵל. וְאִיהִי כ\"ה כ\"ה אַתְוָון, עִמֵּיהּ בְּשִׁית תֵּיבִין, דְּאִינּוּן שְׁמַע יִשְׂרָאֵל. וּבְגִינָהּ אָמַר אַבְרָהָם (בראשית כ״ב:ה׳) נֵלְכָה עַד כ\"ה וְנִשְׁתַּחֲוְה. (שמות י״ט:ג׳) כֹּ\"ה תֹאמַר לְבֵית יַעֲקֹב.","אִיהוּ א\"ח, עַמּוּדָא דְּאֶמְצָעִיתָא, וְאִיהִי ד', שְׁלִימוּ דְּיִחוּדָא דִּילֵיהּ, לְאַשְׁלְמָא בֵּיהּ אֶחָד. א\"ח, כָּלִיל ט' סְפִירָאן, דְּאִינּוּן א' אֵין סוֹף. ח' תְּמַנְיָא סְפִירָאן, מֵחָכְמָה עַד יְסוֹד. ד' מַלְכוּת, קוֹצָא דִּילָהּ, בָּהּ אִשְׁתְּלִימוּ לְעֲשַׂרָה, דְּאִינּוּן יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. ד' כְּלִילָא מְד' אַתְוָון יְדוָֹד.","פִּקּוּדָא חֲמִישָׁאָה, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. אִיהִי אוֹרַיְיתָא דְּבִכְתָב מִסִּטְרָא דְּחֶסֶד. וְאוֹרַיְיתָא דִּבְעַל פֶּה מִסִּטְרָא דִּגְבוּרָה. דִּבְהוֹן חָכְמָה וּבִינָה. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, הָרוֹצֶה לְהַחְכִּים יַדְרִים. לְהַעֲשִׁיר יַצְפִּין. וְעַמּוּדָא דְּאֶמְצָעִיתָא כָּלִיל תַּרְוַויְיהוּ, וּבְגִין דָּא אִתְקְרֵי שָׁמַיִם, כָּלִיל אֵשׁ וּמַיִם, אֵשׁ דִּגְבוּרָה, וּמַיִם דְּחֶסֶד.","וּבְגִין דָּא כֶּתֶר, (תיקונין קל\"ד) דְּאִיהִי כַּף, (במדבר ז׳:פ״ו) עַשָׂרָה עַשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. דְּאִינּוּן יה\"ה, תְּלַת אַתְוָון, אִתְעָבִידוּ כַּף, עַל ו'. וְהַיְינוּ כְּנֶגֶד כֶּתֶר תּוֹרָה, ו' הַיְינוּ סֵפֶר תּוֹרָה, כַּף עֲטָרָה עַל רֵישֵׁיהּ. וְכֹלָּא יְדוָֹ\"ד, כ\"ו בְּחוּשְׁבַּן.","פִּקּוּדָא שְׁתִּיתָאָה, אִיהִי תְּפִלָּה שֶׁל יַד, בִּדְרוֹעָא שְׂמָאלָא. וּמִסִּטְרָא דִּגְבוּרָה ה' דְּיַד כֵּהָה, מִכֶּתֶר וְעַד גְּבוּרָה, ה' סְפִירָאן, וְאִינּוּן תְּפִילִּין דְּרֵישָׁא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְאִיהִי קֶשֶׁר תְּלַת רְצוּעוֹת, דְּאִינּוּן נֶצַח הוֹד יְסוֹד.","וְאִיהִי פִּקּוּדָא שְׁבִיעָאָה, מִצְוַת צִיצִית, כָּלִיל תְּכֵלֶת וְלָבָן, דִּינָא וְרַחֲמֵי. בְּנוּרָא, אֶשָּׁא חִוָּורָא לָא אָכִיל. תְּכֵלָא, אָכִיל וְשָׁצֵי, (מלכים א י״ח:ל״ח) וַתֹּאכַל אֶת הָעוֹלָה. חִוָּור מִימִינָא, תְּכֵלֶת מִשְּׂמָאלָא, עַמּוּדָא דְּאֶמְצָעִיתָא, יִחוּד בֵּין תַּרְוַויְיהוּ, יָרוֹק. בְּגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחְרִין מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. וּבְגִין דָּא תַּקִּינוּ פָּרָשַׁת צִיצִית, לְמִקְרֵי לָהּ בְּיִחוּדָא.","וְאִיהִי פִּקּוּדָא תְּמִינָאָה, מְזוּזָה. שְׁכִינְתָּא אִתְקְרִיאַת מְזוּזָה, מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, דְּאַתְוָון דַּיְדוָֹ\"ד. וּמִסִּטְרָא דְּצַדִיק, רָזָא דִּבְרִית, אִתְקְרֵי שַׁדַּי. שַׁדַּי חוֹתָמָא דְּמַלְכָּא, דְּאִיהוּ יְדוָֹד.","פִּקּוּדָא תְּשִׁיעָאָה, שְׁכִינְתָּא אִתְקְרִיאַת אוֹת בְּרִית, מִסִּטְרָא דְּצַדִּיק יְסוֹד עוֹלָם. (בראשית ט׳:י״ב) זֹאת אוֹת הַבְּרִית. (שמות לא) בֵּינִי, עַמּוּדָא דְּאֶמְצָעִיתָא, וּבֵין בְּנֵי יִשְׂרָאֵל, נֶצַח הוֹד. אוֹת, דָּא צַדִּיק. הִיא, דָּא שְׁכִינְתָּא. כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ אֶת הַשָּׁמַיִם, מִכֶּתֶר עַד עַמּוּדָא דְּאֶמְצָעִיתָא. דְּלֵית שִׁית בְּכָל אֲתָר, אֶלָּא מִסִּטְרָא דְּאָת ו'. וְלֵית שְׁבִיעִי, אֶלָּא מִסִּטְרָא דְּאָת י', עֲטָרָה עַל רֵישֵׁיהּ חָכְמָה עִלָּאָה. אוֹת הוּא. חָכְמָה תַּתָּאָה, אוֹת הִיא.","וְתַקִּינוּ לְמִגְזַר לִתְמַנְיָא, דְּאִינּוּן ח', מִן חָכְמָה עַד יְסוֹד. לְקַבְּלָא בְּהוֹן י' זְעֵירָא, לְסַלְּקָא לָהּ עַד כֶּתֶר, לְמֶהֱוִי עֲטָרָה עַל רֵאשֵׁיהוֹן. וְתַקִּינוּ לְשָׁוּוּיָא לַעָרְלָה בְּמָנָא דְּעַפְרָא, לְקַיֵּים (ישעיהו ס״ה:כ״ה) וְנָחָשׁ עָפָר לַחְמוֹ.","פִּקּוּדָא עֲשִׁירָאָה, (שמות ל״א:ט״ז) וְשָׁמְרוּ בְּנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת. שְׁכִינְתָּא אִתְקְרִיאַת שַׁבָּת, מִסִּטְרָא דִּתְלַת דַּרְגִּין עִלָּאִין דְּאִינּוּן ש', ג' כִּתְרִין: כֶּתֶר, חָכְמָה, וּבִינָה. וְאִיהִי בַּת, רְבִיעָאָה לוֹן. שִׁית יוֹמִין, מֵחֶסֶד עַד יְסוֹד, בְּהוֹן תַּעֲשֶׂה מְלָאכָה, בְּגִין דְּבִנְיָינָא מַתְחִיל מֵחֶסֶד, הֲדָא הוּא דִכְתִיב, (תהילים פ״ט:ג׳) עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִבִּינָה וּלְעֵילָּא, אִיהִי מְנוּחָה וְעֹנֶג וּשְׁבִיתָה לְכָל עוֹבָדָא.","פִּקּוּדָא חַד סָר, אִיהִי אִתְקְרִיאַת צְלוֹתָא דְּשַׁחֲרִית מִנְחָה עַרְבִית, מִסִּטְרָא דִּתְלַת אֲבָהָן, וְאִיהִי תְּפִלַּת כָּ\"ל פֶּ\"ה, לֵית כָּל, אֶלָּא צַדִּיק דִּכְתִּיב, (דברי הימים א כ״ט:י״א) כִּי כֹל בַּשָׁמַיִם וּבָאָרֶץ, וְתִרְגֵּם יוֹנָתָן בֶּן עוּזִיאֵל, דְּאָחִיד בִּשְׁמַיָּיא וּבְאַרְעָא. פֶּ\"ה כְּחוּשְׁבַּן מִילָה. וּמַה בְּרִית בֵּיהּ מִתְיַחֲדִין דְּכַר וְנוּקְבָּא דִּלְתַּתָּא, אוּף בַּיְסוֹד, מִתְיַיחֵד חָתָן וְכַלָּה דִּלְעֵילָּא, הוּא חַי עָלְמִין כָּלִיל חַ\"י בִּרְכָאן, הֲדָא הוּא דִכְתִיב, (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ צַדִּיק.","וּבְגִין דָּא, כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ וְכָל הַזּוֹקֵף זוֹקֵף בַּשֵּׁם. דָּא שְׁכִינְתָּא, בְּשֵׁם דַּיְדוָֹ\"ד, בֵּיהּ צָרִיךְ לְזַקְפָא שְׁכִינְתָּא. הַהִיא דְּאִתְּמַר בָּהּ, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל, עַל יְדֵי דַּרְגָּא אַחֲרָא, וּבְגִין דָּא (עמוס ט׳:י״א) בַּיוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפֶלֶת. הַהוּא דְּאִתְּמַר בֵּיהּ, (תהילים קמ״ו:ד׳) יְדוָֹ\"ד זוֹקֵף כְּפוּפִים."],[[0,"איהי פקודא תניינא וכו':","היא, המלכות, היא מצוה שניה שמצד הגבורה, שהיא בחשבון \u0003יראה.\u0004 כי גבורה בגי' רי\"ו כמו יראה. והיא רמוזה במלה \u0003בראשית,\u0004 שהיא אותיות \u0003ירא בשת.\u0004 והעמידו, מי שאין לו בשת פנים, ודאי שלא עמדו אבותיו על הר סיני."],[1,"איהי פקודא תליתאה וכו':","היא מצוה השלישית, הנקראת \u0003אהבת חסד.\u0004 ז\"ש, אהבת עולם אהבתיך על כן משכתיך חסד. אהבה, שהיא המלכות, כלולה מהאבות, שנקרא בהם, \u0003בכל, מכל, כל,\u0004 שהם המלכות הנקראת \u0003כל.\u0004 שבאברהם נאמר, וה' ברך את אברהם \u0003בכל.\u0004 וביצחק כתוב ואכל \u0003מכל.\u0004 וביעקב כתוב, יש לי \u0003כל.\u0004 וסוד הדבר, זכרתי לך חסד נעוריך אהבת כלולותיך. שזה נאמר על המלכות."],[2,"ואיהי פקודא רביעאה וכו':","והיא מצוה הרביעית, שהיא \u0003יחוד\u0004 מצד עמוד האמצעי, דהיינו היחוד דשמע ישראל. והיא \u0003כ\"ה כ\"ה\u0004 אותיות עמו, עם ז\"א, דהיינו כ\"ה בשמע ישראל שהוא בז\"א, וכ\"ה בבשכמל\"ו שהיא במלכות, בשש מלות של שמע ישראל שהוא שש ספירות דז\"א. ובשבילה אמר אברהם נלכה עד \u0003כ\"ה\u0004 ונשתחוה. וכן \u0003כ\"ה\u0004 תאמר לבית יעקב."],[3,"איהו אח עמודא וכו':","הוא, ז\"א, \u0003אח\u0004 דאחד, שהוא עמוד האמצעי, והיא, המלכות, \u0003ד'\u0004 דאחד, היא ההשלמה של היחוד שלו, להשלים בו סוד \u0003אחד. א\"ח\u0004 דאחד, כולל ט' ספירות שהן, א' היא אין סוף דהיינו כתר. ושמונה ספירות מחכמה עד היסוד. \u0003ד'\u0004 דאחד, היא מלכות, עם הקוץ של ה \u0003ד'\u0004 הרומז ליסוד. בה, במלכות, נשלמו לעשר ספירות שהן עשר אותיות, יוד הא ואו הא. ה \u0003ד'\u0004 דאחד, כלולה מד' אותיות הוי\"ה."],[4,"פקודא חמישאה והגית וכו':","מצוה החמשית, היא, והגית בו יומם ולילה. היא, המלכות, תורה שבכתב מצד החסד, ותורה שבעל פה מצד הגבורה. שבהם חכמה ובינה. כי בגדלות עולה החסד ונעשה חכמה, והגבורה עולה ונעשית בינה. כמו שהעמידו בעלי המשנה, הרוצה להחכים ידרים, להעשיר יצפין. ואין עשיר אלא בדעת, ובבינה. ועמוד האמצעי, שהוא ת\"ת כולל את שניהם, הימין והשמאל, ומשום זה נקרא שמים, שהוא כולל אש ומים, אש היא גבורה, מים הם חסד."],[5,"ובגין דא כתר וכו':","ומשום זה, כתר שהוא כף. שה\"ס עשרה עשרה ה \u0003כף\u0004 בשקל הקדש. דהיינו עשר ספירות ממעלה למטה ועשר ספירות ממטה למעלה, שהוא \u0003יה\"ה\u0004 ג' אותיות, שנעשו כף, דהיינו כתר, על ו' שהיא ז\"א, והיינו כנגד כתר תורה, כי \u0003ו'\u0004 היא ספר תורה, וה \u0003כף\u0004 שהיא יה\"ה, היא עטרה על ראשו. והכל דהיינו \u0003יה\"ה\u0004 עם \u0003ו',\u0004 הוא הויה. שבחשבון כ\"ו. אשר ה \u0003כ'\u0004 ה\"ס כתר על ה \u0003ו'.\u0004"],[5,"","פירוש. כשהמלכות נעשית כתר על ז\"א, בסו\"ה אשת חיל עטרת בעלה. אז היא עולית לבינה, שה\"ס \u0003י\"ה,\u0004 ועמה עצמה שהיא \u0003ה',\u0004 ה\"ס יה\"ה. ונמצאות אלו ג' אותיות \u0003יה\"ה\u0004 כתר על ראש ה \u0003ו'\u0004 שהיא ז\"א. וז\"ש, \u0003ובגין דא כתר\u0004 וכו' \u0003דאינון יה\"ה תלת אתוון\u0004 דהיינו \u0003י\"ח\u0004 שבבינה, והמלכות עצמה שהיא \u0003ה' אתעבידו, כף,\u0004 דהיינו כתר, על \u0003ו'\u0004 שהיא ז\"א. בסו\"ה אשת חיל עטרת בעלה."],[6,"פקודא שתיתאה איהי וכו':","מצוה ששית של המלכות, היא תפלה של יד להניח בזרוע שמאל, שהיא גבורה, ומצד הגבורה היא ה \u0003ה'\u0004 של יד כהה, שהיא המלכות. וע\"כ צריכים להניח התפלה של יד שהיא המלכות בזרוע שמאל, שהיא גבורה דז\"א. ומכתר עד ספירת הגבורה הם ה' ספירות, והם בחינת תפלין של ראש דעמוד האמצעי, שהוא ז\"א. כי מכתר עד גבורה היא בחינת תפלין של ראש, שהם ז\"א. ומגבורה ולמטה הם תפלין של יד, שהם המלכות. והיא, המלכות, היא קשר של ג' רצועות, שהן נצח הוד יסוד. דהיינו שהיא הקשר של ב' רצועות של ראש שהן נצח והוד, והיא הקשר של רצועה האחת של תפלין של יד שהיא יסוד. ונמצא שהיא קשר של ג' רצועות."],[7,"ואיהי פקודא שביעאה וכו':","והיא מצוק השביעית, שהיא מצות ציצית הכלולה תכלת ולבן, שהם דין ורחמים. באש של הנר, אש לבן אינו אוכל מה שתחתיו, כי הוא נאחז רק באש תכלא שמתחתיו. אבל אשא תכלא שבנר היא דבוקה בפתילה ובשמן והיא אוכלת ומכלה מה שתחתיו (כנ\"ל ב\"ב מאות רמ\"ט עד אות רס\"ח) כי אש לבנה היא חסד, ואש תכלת היא דין. ועל אש התכלת שהיא דין, נאמר ותאכל את העולה. כי הלבן הוא מימין והתכלת משמאל, עמוד האמצעי, הוא היחוד בין שניהם, בין ימין ושמאל, והוא ירוק. משום זה העמידו חכמים, מאימתי קוראים את שמע בשחרית. משיכיר בין תכלת ללבן. דהיינו משיבחין בין חסד לדין, כי הוא צריך ליחדם בקו אמצעי, שה\"ס קריאת שמע. ומשום זה התקינו פרשת ציצית, לקראה ביחוד קריאת שמע משום שמצותה בלבן ותכלת, שצריכים ליחדם בק\"ש."],[8,"ואיהי פקודא תמינאה וכו':","והיא מצוה שמינית, שהיא מזוזה, השכינה נקראת מזוזה מצד עמוד האמצעי דהיינו ז\"א, שהוא אותיות \u0003הויה,\u0004 ומצד הצדיק דהיינו יסוד, שהוא סוד ברית שנקרא \u0003שדי.\u0004 שדי הוא חותם המלך שהוא הויה. וע\"כ במזוזה יש \u0003הויה\u0004 בפנים המזוזה, כנגד עמוד האמצעי, ו \u0003שדי\u0004 בחוץ למזוזה כנגד היסוד."],[9,"פקודא תשיעאה שכינתא וכו':","מצוה התשיעית היא, השכינה הנקראת אות ברית מצד צדיק יסוד עולם, שהוא יסוד, שכתוב, זאת אות הברית. \u0003זאת\u0004 היא השכינה, והיא \u0003אות הברית.\u0004 וכתוב, ביני ובין בני ישראל אות הוא לעולם כי ששת ימים עשה ה' את השמים ואת הארץ וביום השביעי וגו'. \u0003ביני,\u0004 היינו בין עמוד האמצעי שהוא ז\"א. \u0003ובין בני ישראל,\u0004 היינו בין נצח והוד, המכונים בני ישראל. \u0003אות,\u0004 זה צדיק, דהיינו יסוד. \u0003היא,\u0004 זו השכינה. \u0003כי ששת ימים עשה ה' את השמים,\u0004 היינו מכתר עד עמוד האמצעי, שהוא ת\"ת, הוא שש ספירות כח\"ב חג\"ת. שאין שש בכל מקום אלא מצד אות \u0003ו'\u0004 שהיא ת\"ת. אף כאן ששת ימים פירושו ת\"ת, עם חמש ספירות שלפניו, שהוא כולל אותם. אבל מת\"ת ולמטה כבר אינו בחינת ז\"א, אלא בחינת המלכות. ואין שביעי אלא מצד אות \u0003י'\u0004 שהיא המלכות שהיא עטרה על ראש ז\"א בסוד אשת חיל עטרת בעלה. ואז היא בבחינת חכמה עלאה, ונקראת, \u0003אות הוא\u0004 לשון זכר. וכשהמלכות היא חכמה תתאה, נקראת אות היא, לשון נקבה. ולפיכך אות \u0003הוא,\u0004 מנוקד עם חירק שהיא לשון נקבה, והכתיב הוא עם \u0003ו'\u0004 שהוא לשון זכר."],[10,"ותקינו למגזר לתמניא וכו':","והתקינו למול לשמונה, שהם שמונה ספירות מן חכמה עד יסוד, לקבל בהם \u0003י'\u0004 הקטנה, שהיא המלכות, להעלותה עד כתר, שתהיה עטרה על ראשם של שמונה ספירות. והתקינו לשום הערלה בכלי עם עפר, לקיים, ונחש עפר לחמו."],[11,"פקודא עשיראה ושמרו וגו':","מצוה העשירית שבמלכות, היא, ושמרו בני ישראל את השבת. השכינה נקראת שבת, מצד ג' מדרגות עליונות שהן \u0003ש',\u0004 הרומזת על ג' ספירות, כתר חכמה בינה. והמלכות, היא בת, ורביעית להם. ששת ימים, שהם שש ספירות מחסד עד היסוד, דהיינו חג\"ת נה\"י, תעשה בהם מלאכה, משום שבנין העולם מתחיל מחסד, ז\"ש, עולם חסד יבנה. אבל מבינה ולמעלה, דהיינו בג\"ר, היא מנוחה וענג ושביתה מכל מלאכה."],[12,"פקודא חד סר וכו':","מצוה הי\"א שבמלכות, היא נקראת תפלת שחרית מנחה וערבית, מצד ג' אבות, שהם חג\"ת. והיא \u0003תפלת כל פה,\u0004 דהיינו המלכות הדבוקה ביסוד, כי \u0003תפלת,\u0004 היא מלכות, \u0003כל פה,\u0004 הוא יסוד. כי אין \u0003כל\u0004 אלא צדיק, שהוא יסוד, שכתוב כי \u0003כל\u0004 בשמים ובארץ, ותרגם יונתן בן עוזיאל, דאחיד בשמיא וארעא. דהיינו יסוד הנאחז בשמים וארץ, שהם ז\"א ומלכות. \u0003פה\u0004 היא כחשבון מילה. ומה ברית, בו מתיחדים דכר ונוקבא שלמטה, אף ביסוד מתיחד חתן וכלה שלמעלה, שהם ז\"א ומלכות. היסוד, הוא \u0003ח\"י\u0004 עולמים, כי כולל ח\"י ברכות שבתפלת העמידה, ז\"ש ברכות לראש צדיק."],[13,"ובג\"ד כל הכורע וכו':","ומשום זה כל הכורע כורע בברוך, שה\"ס יסוד, וכל הזוקף זוקף בשם. זו היא השכינה בשם הויה, שבו צריכים לזקוף השכינה, אותה שנאמר בה, נפלה לא תוסיף קום בתולת ישראל, מעצמה, אלא על ידי מדרגה אחרת שהיא הויה, דהיינו ז\"א, ומשום זה, ביום ההוא אקים את סוכת דוד הנופלת. אותו שנאמר בו הויה זוקף כפופים. וע\"כ כל הזוקף זוקף בשם."]],[[0,"","הִיא מִצְוָה שְׁנִיָּה מִצַּד הַגְּבוּרָה, יִרְאָה בְּחֶשְׁבּוֹן. וּרְמוּזָה בְּמִלַּת בְּרֵאשִׁית, יָרֵא בשֶׁת. וּפֵרְשׁוּהָ, מִי שֶׁאֵין לוֹ בּשֶׁת פָּנִים, וַדַּאי שֶׁלֹּא עָמְדוּ אֲבוֹתָיו עַל הַר סִינַי."],[1,"","הִיא מִצְוָה שְׁלִישִׁית, שֶׁנִּקְרֵאת אַהֲבַת חֶסֶד. זֶהוּ שֶׁכָּתוּב (ירמיה לא) אַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד. אַהֲבָה כְּלוּלָה מֵהָאָבוֹת, שֶׁנִּקְרָא בָּהֶם בַּכֹּל מִכֹּל כֹּל. וְסוֹד הַדָּבָר - (שם ב) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ."],[2,"","וְהִיא מִצְוָה רְבִיעִית, יִחוּד, מִצַּד הָעַמּוּד הָאֶמְצָעִי, שְׁמַע יִשְׂרָאֵל. וְהִיא כ\"ה כ\"ה אוֹתִיּוֹת עִמּוֹ בְּשֵׁשׁ תֵּבוֹת, שֶׁהֵן שְׁמַע יִשְׂרָאֵל (וכו'). וּבִגְלָלָהּ אָמַר אַבְרָהָם, (בראשית כב) נֵלְכָה עַד כֹּ\"ה וְנִשְׁתַּחֲוֶה. (שמות יט) כֹּ\"ה תֹאמַר לְבֵית יַעֲקֹב."],[3,"","הוּא א\"ח, עַמּוּד הָאֶמְצָעִי, וְהִיא ד', שְׁלֵמוּת הַיִּחוּד שֶׁלּוֹ לְהַשְׁלִים בּוֹ אֶחָד. א\"ח כּוֹלֵל תֵּשַׁע סְפִירוֹת, שֶׁהֵן א' - אֵין סוֹף, ח' - שְׁמוֹנֶה סְפִירוֹת, מֵחָכְמָה עַד יְסוֹד. ד' - מַלְכוּת, הַקּוֹץ שֶׁלָּהּ, בָּהּ נִשְׁלָמוֹת לְעֶשֶׂר, שֶׁהֵם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. ד' כְּלוּלָה מֵאַרְבַּע אוֹתִיּוֹת יְהֹוָה."],[4,"","מִצְוָה חֲמִישִׁית, (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. הִיא תּוֹרָה שֶׁבִּכְתָב מִצַּד הַחֶסֶד, וְתוֹרָה שֶׁבְּעַל פֶּה מִצַּד הַגְּבוּרָה, שֶׁבָּהֶן חָכְמָה וּבִינָה. כְּמוֹ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הָרוֹצֶה לְהַחְכִּים - יַדְרִים. לְהַעֲשִׁיר - יַצְפִּין. וְהָעַמּוּד הָאֶמְצָעִי כּוֹלֵל אֶת שְׁנֵיהֶם, וּמִפְּנֵי זֶה נִקְרָא שָׁמַיִם, כּוֹלֵל אֵשׁ וּמַיִם, אֵשׁ שֶׁל גְּבוּרָה וּמַיִם שֶׁל חֶסֶד."],[5,"","וּמִפְּנֵי זֶה כֶּתֶר, שֶׁהִיא כַּף, (במדבר ז) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. שֶׁהֵם יה\"ה, שָׁלֹשׁ אוֹתִיּוֹת, נַעֲשׂוֹת כַּף עַל ו'. וְזֶהוּ כְּנֶגֶד כֶּתֶר תּוֹרָה. ו' זֶה סֵפֶר תּוֹרָה. כַּף עֲטָרָה עַל רֹאשׁוֹ. וְהַכֹּל יְהֹוָ\"ה, עֶשְׂרִים וָשֵׁשׁ בְּחֶשְׁבּוֹן."],[6,"","מִצְוָה שִׁשִּׁית הִיא תְּפִלָּה שֶׁל יָד בִּזְרוֹעַ שְׂמֹאל. וּמִצַּד הַגְּבוּרָה ה' שֶׁל יָד כֵּהָה, מִכֶּתֶר וְעַד גְּבוּרָה, חָמֵשׁ סְפִירוֹת, וְהֵן תְּפִלִּין שֶׁל רֹאשׁ שֶׁל הָעַמּוּד הָאֶמְצָעִי. וְהִיא קֶשֶׁר שָׁלֹשׁ רְצוּעוֹת, שֶׁהֵן נֵצַח הוֹד יְסוֹד."],[7,"","וְהִיא מִצְוָה שְׁבִיעִית, מִצְוַת צִיצִית, כּוֹלֶלֶת תְּכֵלֶת וְלָבָן, דִּין וְרַחֲמִים. בָּאֵשׁ, אֵשׁ לְבָנָה לֹא אוֹכֶלֶת. תְּכֵלֶת אוֹכֶלֶת וּמְכַלָּה, (מלכים א יח) וַתֹּאכַל אֶת הָעֹלָה. לָבָן מִיָּמִין, תְּכֵלֶת מִשְּׂמֹאל. הָעַמּוּד הָאֶמְצָעִי יִחוּד בֵּין שְׁנֵיהֶם, יָרֹק. מִשּׁוּם כָּךְ פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִית? מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. וּמִפְּנֵי זֶה תִּקְּנוּ פָּרָשַׁת צִיצִית לִקְרֹא אוֹתָהּ בְּיִחוּד."],[8,"","וְהִיא מִצְוָה שְׁמִינִית, מְזוּזָה. הַשְּׁכִינָה נִקְרֵאת מְזוּזָה מִצַּד הָעַמּוּד הָאֶמְצָעִי שֶׁל אוֹתִיּוֹת יְהֹוָ\"ה. וּמִצַּד שֶׁל צַדִּיק, סוֹד הַבְּרִית, נִקְרֵאת שַׁדַּי. שַׁדַּי חוֹתֶמֶת הַמֶּלֶךְ, שֶׁהוּא יְהֹוָה."],[9,"","מִצְוָה תְּשִׁיעִית, הַשְּׁכִינָה נִקְרֵאת אוֹת בְּרִית מִצַּד שֶׁל צַדִּיק יְסוֹד עוֹלָם. (בראשית ט) זֹּאת אוֹת הַבְּרִית. (שמות לא) בֵּינִי, הָעַמּוּד הָאֶמְצָעִי, וּבֵין בְּנֵי יִשְׂרָאֵל, נֵצַח וְהוֹד. אוֹת - זֶה צַדִּיק. הִיא - זוֹ הַשְּׁכִינָה. כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם - מִכֶּתֶר עַד הָעַמּוּד הָאֶמְצָעִי. שֶׁאֵין שִׁשָּׁה בְּכָל מָקוֹם אֶלָּא מִצַּד הָאוֹת ו'. וְאֵין שְׁבִיעִי אֶלָּא מִצַּד הָאוֹת י', עֲטָרָה עַל רֹאשׁוֹ חָכְמָה עֶלְיוֹנָה, אוֹת הוּא. חָכְמָה תַּחְתּוֹנָה, אוֹת הִיא."],[10,"","וְתִקְּנוּ לָמוּל לִשְׁמוֹנָה, שֶׁהֵם ח', מֵחָכְמָה עַד יְסוֹד. לְקַבֵּל בָּהֶם י' קְטַנָּה, לְהַעֲלוֹת אוֹתָהּ עַד כֶּתֶר, לִהְיוֹת עֲטָרָה עַל רֹאשָׁם. וְתִקְּנוּ לָשִׂים הָעָרְלָה בִּכְלִי עָפָר, לְקַיֵּם (ישעיה סה) וְנָחָשׁ עָפָר לַחְמוֹ."],[11,"","מִצְוָה עֲשִׂירִית, (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת. הַשְּׁכִינָה נִקְרֵאת שַׁבָּת מִצַּד שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁהֵן ש', שְׁלֹשָׁה כְּתָרִים: כֶּתֶר, חָכְמָה, בִּינָה. וְהִיא בַּת, רְבִיעִית לָהֶם. שִׁשָּׁה יָמִים, מֵחֶסֶד עַד יְסוֹד, בָּהֶם תַּעֲשֶׂה מְלָאכָה, מִפְּנֵי שֶׁהַבִּנְיָן מַתְחִיל מֵחֶסֶד. זֶהוּ שֶׁכָּתוּב (תהלים פט) עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִבִּינָה וּלְמַעְלָה הִיא מְנוּחָה וְעֹנֶג וּשְׁבִיתָה לְכָל מַעֲשֶׂה."],[12,"","מִצְוָה אַחַת עֶשְׂרֵה הִיא נִקְרֵאת תְּפִלָּה שֶׁל שַׁחֲרִית, מִנְחָה וְעַרְבִית, מִצַּד שְׁלֹשֶׁת הָאָבוֹת, וְהִיא תְּפִלַּת כָּ\"ל פֶּ\"ה. אֵין כֹּל אֶלָּא צַדִּיק, שֶׁכָּתוּב (דברי הימים א כט) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְתִרְגֵּם יוֹנָתָן בֶּן עֻזִּיאֵל, שֶׁאוֹחֵז בַּשָּׁמַיִם וּבָאָרֶץ. פֶּ\"ה כְּחֶשְׁבּוֹן מִילָה. וּמַה בְּרִית בָּהּ מִתְיַחֲדִים זָכָר וּנְקֵבָה שֶׁלְּמַטָּה - אַף בַּיְסוֹד מִתְיַחֵד חָתָן וְכַלָּה שֶׁלְּמַעְלָה, הוּא חַי הָעוֹלָמִים כּוֹלֵל חַ\"י בְּרָכוֹת, זֶהוּ שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק."],[13,"","וּמִפְּנֵי זֶה, כָּל הַכּוֹרֵע - כּוֹרֵעַ בְּבָרוּךְ, וְכָל הַזּוֹקֵף - זוֹקֵף בַּשֵּׁם. זוֹ הַשְּׁכִינָה. בְּשֵׁם יְהֹוָ\"ה, בּוֹ צָרִיךְ לִזְקֹף הַשְּׁכִינָה, הַהִיא שֶׁנֶּאֱמַר בָּהּ, (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל, עַל יְדֵי דַרְגָּה אַחֶרֶת. וּמִפְּנֵי זֶה, (שם ט) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ, (תהלים קמו) יְהֹוָ\"ה זוֹקֵף כְּפוּפִים."]]],[["פִּקּוּדָא תְּרֵיסָר, אִיהִי אִתְקְרִיאַת חַג הַמַּצּוֹת, וְחַג הַשָּׁבוּעוֹת, וְחַג הַסֻּכּוֹת, מִסִּטְרָא דְּג' אֲבָהָן. ורֹאשׁ הַשָּׁנָה מִסִּטְרָא דִּילָהּ, דִּינָא דְּמַלְכוּתָא דִּינָא. וְאִית דְּיֵימָא, פֶּסַח דְּרוֹעָא יְמִינָא. שָׁבוּעוֹת, מַתַּן תּוֹרָה, דְּאִתְיְיהִיבַת בְּמַדְבְּרָא, דְּאִיהוּ מְמָנָא עָלֵיהּ שׁוֹר, מִסִּטְרָא דִּגְבוּרָה. סֻכּוֹת (בראשית ל״ג:י״ז) וְיַעֲקֹב נָסַע סֻכּוֹתָה. פִּקּוּדָא תְּלֵיסַר, קְרִיאַת שְׁמַע.","וְאִית לְמִנְדַּע, דְּאִיהוּ אִתְקְרֵי חָכָם בְּכָל מִינֵי חָכְמוֹת. וּמֵבִין, בְּכָל מִינֵי תְּבוּנוֹת. וְחָסִיד, בְּכָל מִינֵי חֲסָדִים. וְגִבּוֹר, בְּכָל מִינֵי גְּבוּרוֹת. וְיוֹעֵץ, בְּכָל מִינֵי עֵצוֹת. וְצַדִּיק, בְּכָל מִינֵי צְדָקוֹת. וָמֶלֶךְ, בְּכָל מִינֵי מַלְכוּת. עַד אֵין סוֹף. עַד (ס\"א כתר) אֵין חֵקֶר. וּבְכָל אִלֵּין דַּרְגִּין, בְּחַד אִקְרֵי רַחֲמָן. וּבְחַד אִקְרֵי דַּיָּין. וְהָכִי בְּכַמָּה דַּרְגִּין, עַד אֵין סוֹף. אִי הָכִי שִׁנּוּי אִית, בֵּין רַחֲמָן לְדַּיָּין. אֶלָּא קוֹדֶם דְּבָרָא עָלְמָא, אִתְקְרֵי הוּא בְּכָל אִלֵּין דַּרְגִּין, עַל שֵׁם בִּרְיָין דַּהֲווֹ עֲתִידִין לְהִבָּרְאוֹת, דְּאִי לָאו בִּרְיָין דְּעָלְמָא, אֲמַאי אִתְקְרֵי רַחוּם דַּיָּין, אֶלָּא עַל שֵׁם בִּרְיָין דַּעֲתִידִין.","וּבְגִין דָּא, כָּל שְׁמָהָן, אִינּוּן כִּנּוּיִין דִּילֵיהּ. עַל שֵׁם עוֹבָדִין דִּילֵיהּ. כְּגַוְונָא דָּא, בָּרָא נִשְׁמְתָא, בְּדִיּוּקְנָא דִּילֵיהּ, דְּאִתְקְרִיאַת עַל שֵׁם פְּעוּלוֹת דִּילָהּ, בְּכָל אֵבֶר וְאֵבֶר דְּגוּפָא, דְּאִתְקְרֵי עָלְמָא זְעֵירָא. כְּגַוְונָא דְּמָארֵי עָלְמָא, אִתְנְהִיג בְּכָל בִּרְיָין. וּבְכָל דָּרָא, כְּפוּם עוֹבָדוֹי. כַּךְ נִשְׁמְתָא, כְּפוּם עוֹבָדוֹי דְּכָל אֵבֶר וְאֵבֶר. הַהוּא אֵבֶר דְּעָבִיד בֵּיהּ פִּקּוּדָא, אִתְקְרֵי נִשְׁמְתָא, לְגַבֵּי חֶמְלָה וְחִסְדָּא חִנָּא וְרַחֲמֵי. וּבְהַהוּא אֵבֶר דְּעָבִיד בֵּיהּ עֲבֵירָה, אִתְקְרֵי נִשְׁמְתָא לְגַבֵּי, דִּינָא וְחֵימָה וָכָעַס. אֲבָל לְבַר מִן גּוּפָא, לְמַאן תְּהֵא חֶמְלָה, אוֹ אַכְזָרִיוּת.","אוּף הָכִי מָארֵי עָלְמָא, קֹדֶם דְּבָרָא עָלְמָא, וּבָרָא בִּרְיָין דִּילֵיהּ, לְמַאן אִתְקְרֵי רַחוּם וְחַנּוּן אוֹ דַּיָּין. אֶלָּא כָּל שְׁמָהָן דִּילֵיהּ, אִינּוּן כִּנּוּיִין, וְלָא אִתְקְרֵי בְּהוֹן, אֶלָּא עַל שֵׁם בִּרְיָין דְּעָלְמָא, וּבְגִין דָּא, כַּד מָארֵי דָּרָא אִינּוּן טָבִין, אִיהוּ אִתְקְרֵי לְגַבַּיְיהוּ, יְהוָֹ\"ה בְּמִדַת רַחֲמִים. וְכַד מָארֵי דָּרָא אִינּוּן חַיָּיבִין, אִתְקְרֵי אֲדֹנָ\"י בְּמִדַת הַדִּין. לְכָל דָּרָא, וּלְכָל בַּר נָשׁ, כְּפוּם מִדָּה דִּילֵיהּ. אֲבָל לָאו דְּאִית לֵיהּ מִדָּה וְלָא שֵׁם יְדִיעַ.","כְּגַוְונָא דִּסְפִירָאן, דְּכָל סְפִירָה אִית לָהּ שֵׁם יְדִיעַ, וּמִדָּה, וּגְבוּל, וּתְחוּם. וּבְאִלֵּין שְׁמָהָן מָארֵי עָלְמָא אִיהוּ אִתְפְּשַּׁט, וְאַמְלִיךְ בְּהוֹן, וְאִתְקְרֵי בְּהוֹן, וְאִתְכַּסֵּי בְּהוֹן, וְדָר בְּהוֹן, כְּנִשְׁמְתָא לְגַבֵּי אֵבָרִים דְּגוּפָא. וּמַה רִבּוֹן עָלְמִין, לֵית לֵיהּ שֵׁם יְדִיעַ וְלָא אֲתָר יְדִיעַ, אֶלָּא בְּכָל סִטְרָא שׁוּלְטָנוּתֵיהּ. אוּף הָכִי לֵית לָהּ לְנִשְׁמְתָא שֵׁם יְדִיעַ, וְלָא אֲתָר יְדִיעַ, בְּכָל גּוּפָא אֶלָּא בְּכָל סְטָר שׁוּלְטָנוּתֵיהּ, וְלֵית אֵבֶר פָּנוּי מִנָּהּ.","וּבְגִין דָּא, לֵית לְרַשְּׁמָא לָהּ בְּחַד אֲתָר, דְּאִי לָאו הָא חָסֵר שׁוּלְטָנוּתָא בִּשְׁאַר אֵבָרִים. וְלָא לְאִתְקְרֵי לָהּ בִּשְׁמָא חַד, אוֹ בִּתְרֵין, אוֹ בְּג'. לְמֵימָר דְּאִיהִי חָכְמָה מִבִּינָה, וְאִית לָהּ דַּעַת, וְלָא יַתִּיר. דְּאִי עָבִיד הָכִי, הָא חָסֵר לָהּ מִשְּׁאַר דַּרְגִּין.","כָּל שֶׁכֵּן לְמָארֵי עָלְמָא, דְּלֵית לְרַשְׁמָא לֵיהּ בַּאֲתָר יְדִיעַ, אוֹ לְאִתְקְרֵי לֵיהּ בִּשְׁמָהָן, אוֹ לְשַׁנָּאָה לֵיהּ בְּהוֹן, אוֹ (ס\"א לשלשא) לְשַׁלְּטָאָה לֵיהּ כְּגוֹן דַּרְגָּא דְּמֶרְכַּבְתָּא, דְּאִתְּמַר בָּהּ קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ, דְּכָל דַּרְגִּין דְּכָל מַרְכְּבוֹת דִּילֵיהּ, אִינּוּן מְשׁוּלָּשִׁים, כְּגוֹן הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה, דְּאִינּוּן דְּמוּת אַרְיֵה שׁוֹר נֶשֶׁר, דְּאִינּוּן מֶרְכָּבָה לְאָדָם. דְּאִתְּמַר עָלֵיהּ, (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וּמִסִּטְרָא דְּנוּקְבָּא, אִינּוּן שַׁלְטִין עַל אָדָם, וְנוּקְבָּא אִיהִי מֶרְכָּבָה לְגַבַּיְיהוּ. וּבְגִין דָּא אִתְּמַר עָלָהּ, קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ.","וְאוֹף הָכִי אַתְוָון, דְּאִינּוּן אַנְפִּין דְּחֵיוָן, מְשׁוּלָּשִׁין, כְּגַוְונָא דָּא: יד\"ו. הו\"י. וה\"י. ה' רְבִיעָאָה, קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ. אִיהִי שְׁלָמִים דְּכֻלְּהוּ, לְאַשְׁלְמָא בְּכֻלְּהוּ שֵׁם יְדוָֹ\"ד. אֲבָל לְמָארֵיהּ דְּכֹלָּא, לֵית לְשַׁלְּשָׁא בֵּיהּ בִּשְׁמָהָן, וְלָא בְּאַתְוָון, אֶלָּא אִיהוּ אִתְקְרֵי בְּכָל שְׁמָהָן, וְלֵית לֵיהּ שֵׁם יְדִיעַ. וְכָל שֵׁם וְשֵׁם אַסְהִיד עָלֵיהּ, דְּאִיהוּ אֲדוֹן כָּל עָלְמִין. אַסְהִיד עָלֵיהּ אֲדֹנָי.","וְלֵית דְּיַדְעִין דְּאִית בַּר נָשׁ, דְּיָרִית ג' מֵאָה וְעֶשֶׂר עָלְמִין, הֲדָא הוּא דִכְתִיב, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֶשׁ. כְּפוּם דַּרְגָּא דִּילֵיהּ, דְּאִתְקְרֵי יֵשׁ מֵאַיִן. וְדָא חָכְמָה עִלָּאָה. וְאִית בַּר נָשׁ דְּלָא יָרִית אֶלָּא עָלְמָא חַד, כְּפוּם דַּרְגָּא דִּילֵיהּ, כְּמָה דְּאוֹקְמוּהָ, כָּל צַדִּיק וְצַדִּיק יֵשׁ לוֹ עוֹלָם בִּפְנֵי עַצְמוֹ. וְהָכִי יָרִית עָלְמִין כָּל בַּר נָשׁ מִיִשְׂרָאֵל, כְּפוּם דַּרְגָּא דִּילֵיהּ לְעֵילָּא. אֲבָל לְמָארֵי עָלְמָא, לֵית לְרַשְׁמָא לֵיהּ עָלְמִין בְּחוּשְׁבָּן, אֶלָּא אֲדוֹן כָּל עָלְמִין, וְאֲדֹנָ\"י קָא סָהִיד עָלֵיהּ.","אוּף הָכִי יְהוָֹ\"ה, מִנֵּיהּ תַּלְיָיא כָּל הֲוָיָין, וְאִיהוּ וְכָל הֲוָיָין דִּילֵיהּ, סָהֲדִין עַל מָארֵי עָלְמָא, דְּאִיהוּ הֲוָה קֹדֶם כָּל הֲוָיָין. וְאִיהוּ בְּתוֹךְ כָּל הֲוָיָה. וְאִיהוּ לְאַחַר כָּל הֲוָיָה. וְדָא רָזָא, דְּסָהֲדִין הַוָיָין עָלֵיהּ, הָיָה, הוְֹה, וְיִהְיֶה.","דִּינָא, בְּהִפּוּךְ אַתְוָון אֲדֹנָ\"י. וּבְגִין דָּא אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, דִּינָא דְּמַלְכוּתָא דִּינָא. שֵׁם אֵ\"ל סָהִיד עַל מָארֵי דְּכֹלָּא, דְּלֵית יְכוֹלֶת לְכָל שֵׁם, וַהֲוָיָה וְדַרְגָּא. כָּל שֶׁכֵּן לִשְׁאַר בִּרְיָין, פָּחוּת מִנֵּיהּ. הֲדָא הוּא דִּכְתִּיב, (דניאל ד׳:ל״ב) כְּלָא חֲשִׁיבָין וּכְמִצְבְּיֵהּ עָבֵּיד בְּחֵיל שְׁמַיָא וְגוֹ'. אֱלֹהִי\"ם, סָעִיד עַל אֱלָהוּת דִּילֵיהּ, דְּאִיהוּ אֱלֹהִי\"ם וִאלהֵי הָאֱלֹהִים, וְאִיהוּ אֱלוֹהַּ עַל כֹּלָּא, וְלֵית אֱלוֹהַּ עָלֵיהּ. צְבָאוֹ\"ת, סָהִיד עָלֵיהּ כְּדִכְתִיב, וּכְמִצְבְּיֵיהּ עָבִיד בְּחֵיל שְׁמַיָא. שַׁדַּ\"י, סָהִיד עָלֵיהּ, דְּכַד אִיהוּ אָמַר לְעוֹלָם דַּי עָמַד בִּתְחוּמֵיהּ, וְלָא אִתְפְּשָּׁט יַתִּיר. וְאוּף לְמַיָּא וְרוּחָא וְאֶשָּׁא."],[[0,"פקודא תריסר איהי וכו':","מצוה שתים עשרה שבמלכות, היא נקראת חג המצות חג השבועות וחג הסוכות, מצד ג' אבות, שהם חג\"ת, וראש השנה הוא מבחינתה עצמה של המלכות, שה\"ס דינא דמלכותא דינא. ויש מי שאומר, שחג הפסח הוא זרוע ימין, דהיינו חסד. שבועות שהוא זמן מתן תורה שניתנה במדבר, שהממונה על המדבר הוא שור מצד הגבורה, ע\"כ שבועות הוא גבורה. סוכות היא תפארת, שנאמר, ויעקב נסע סכותה. ויעקב הוא ת\"ת. ובכל המקומות אומר, שפסח הוא חסד, וסוכות הוא גבורה, ושבועות הוא תפארת. מצוה י\"ג שבמלכות, היא קריאת שמע."],[1,"ואית למנדע דאיהו וכו':","ויש לדעת, שהאין סוף נקרא חכם בכל מיני חכמות, ומבין בכל מיני תבונות, וחסיד בכל מיני חסדים, וגבור בכל מיני גבורות, ויועץ בכל מיני עצות, וצדיק בכל מיני צדקות, ומלך בכל מיני מלכות, עד אין סוף ועד אין חקר. ובכל אלו המדרגות, באחד נקרא רחמן, ובאחד נקרא דיין, וכך בכמה מדרגות עד אין סוף. שואל, א\"כ יש בו שינוי בין רחמן ובין דיין. ומשיב. אלא קודם שברא העולם הוא נקרא בכל אלו המדרגות, על שם הבריות שהיו עתידות להבראות, ואם לא על שם בריות העולם, למה נקרא רחום דיין, של מי ירחם. אלא שנקרא כן על שם הבריות העתידות. אבל בו עצמו אין חס ושלום שינוי."],[2,"ובג\"ד כל שמהן וכו':","ומשום זה, כל השמות הם כינוים שלו על שם מעשיו. כעין זה ברא נשמה בצורה שלו הנקראת על שם פעולותיה שבכל אבר ואבר של הגוף, הנקרא עולם קטן. כמו שרבון העולם נוהג בכל בריה ובכל דור כפי מעשיו, כך הנשמה היא כפי מעשיו של כל אבר ואבר. אבר ההוא שעושה בו מצוה, נקרא נשמה לחמלה וחסד וחן ורחמים הנפעלים בגופו. ובאבר ההוא שעושה בו עבירה. נקרא נשמה לדין וחימה וכעס. הנפעלים בגופו. אבל לחוץ מן הגוף, למי יהיה חמלה או אכזריות. מחמת מעשי הגוף."],[3,"אוף הכי מארי וכו':","אף כך, רבון העולם, מקודם שברא העולם וברא הבריות שלו, למי נקרא רחום וחנון או דיין. אלא כל שמותיו הם כינוים, ולא נקרא בהם אלא על שם בריות העולם. ומשום זה כשבני הדור הם טובים הוא נקרא אליהם \u0003הוי\"ה\u0004 במדת רחמים. וכשבני הדור הם רשעים, הוא נקרא אליהם \u0003אדנ\"י\u0004 במדת הדין. כי לכל דור ולכל אדם נקרא לפי המדה שלו, אבל לא שיש לו מדה ידועה, ולא שם ידוע."],[4,"כגוונא דספיראן דכל וכו':","כעין הספירות, שכל ספירה יש לה שם ידוע, ומדה וגבול ותחום. ובאלו השמות מתפשט רבון העולם ומלך בהם, ונקרא בהם ומתכסה בהם ודר בהם כנשמה באברי הגוף. ומה רבון העולמים אין לו שם ידוע ולא מקום ידוע, אלא ממשלתו בכל צד שבעולם, אף כך אין לנשמה שם ידוע, ולא מקום ידוע בכל הגוף, אלא ממשלתה היא בכל צד, ואין אבר פנוי ממנה."],[5,"ובג\"ד לית לרשמא וכו':","ומשום זה אין לציין את הנשמה במקום אחד שבגוף, שאם לא כן, אלא שתציין אותה במקום אחד, נמצא שחסר ממשלתה בשאר האברים. ואין לקראה בשם אחד או בשנים או בג', לומר שהיא חכמה ומבינה, ויש לה דעת, ולא יותר, שאם עושה כך נמצא שחסר לה שאר המדרגות."],[6,"כ\"ש למארי עלמא וכו':","כל שכן לרבון העולם, שאין לציין אותו במקום ידוע, או לקראו בשם ידוע, או להכפיל, אותו בהם, או לשלש אותו בהם, דהיינו, המדרגה של המרכבה, שנאמר בה קדושה לך \u0003ישלשו.\u0004 כי כל המדרגות של כל המרכבות שלו, הם משולשים, כמו, האבות הן הן המרכבה, שהם דמות אריה שור נשר. שהם מרכבה לאדם, שנאמר עליהם, ודמות פניהם פני אדם. ומצד הנוקבא, הם, אריה שור נשר, שולטים על אדם, שהוא שם הנוקבא, והנוקבא היא מרכבה. אל אריה שור נשר. ומשום זה נאמר עליה קדושה לך ישלשו."],[7,"ואוף הכי אתוון וכו':","ואף כך האותיות יה\"ו שהן רומזות על פני החיות, אריה שור נשר, הן משולשים, כעין זה, יה\"ו הו\"י וה\"י. \u0003ה'\u0004 היא רביעית אליהם, וה\"ס קדושה לך ישלשו כנ\"ל, היא שלמים של כולם. שמשלמת בכולם את שם הויה. אבל לרבון הכל, אין לשלש בו בשמות, ולא באותיות, אלא הוא נקרא בכל השמות ואין לו שם ידוע, וכל שם ושם מעיד עליו, שהוא אדון כל עולמים, והשם אדנ\"י מעיד עליו."],[8,"דאית ב\"נ דירית וכו':","ויש אדם שיורש ש\"י עולמות. ז\"ש להנחיל אוהבי \u0003יש,\u0004 שהוא בגי' ש\"י. שהוא לפי מדרגת החכמה שנקראת \u0003יש\u0004 מאין. כי כתר נקרא \u0003אין,\u0004 והחכמה \u0003יש,\u0004 הנמשך מן ה \u0003אין.\u0004 וזו היא חכמה עליונה. ויש אדם שאינו יורש אלא עולם אחד כפי המדרגה שלו, כמו שהעמידו, כל צדיק וצדיק יש לו עולם בפני עצמו. וכך כל אדם מישראל יורש עולמות לפי המדרגה שלו למעלה. אבל לרבון העולם, אין לרשום לו עולמות בחשבון, אלא הוא, אדון כל העולמות, והשם אדנ\"י מעיד עליו."],[9,"אוף הכי הויה וכו':","אף כך השם \u0003הויה,\u0004 ממנו תלוים כל הויות, והוא וכל הויות שלו. מעידים על רבון העולם, שהוא היה קודם כל הויות, והוא בתוך כל הויות, והוא לאחר כל הויות. וז\"ס, שהויות מעידים עליו, שהוא \u0003היה הוה ויהיה.\u0004"],[10,"דינא בהפוך אתוון וכו':","דינא בהפוך האותיות הוא \u0003אדני.\u0004 ומשום זה אמרו רבותינו ז\"ל דינא דמלכותא דינא. השם \u0003אל\u0004, מעיד על רבון הכל, שאין יכולת לכל שם והויה ומדרגה, וכל שכן לשאר הבריות, חוץ ממנו. ז\"ש, כלא חשיבין וכמצבייה עביד בחיל שמייא וגו'. \u0003אלקים,\u0004 מעיד על אלקות שלו, שהוא האלקים ואלקי האלקים, והוא אלוה על הכל ואין אלוה עליו. \u0003צבאות\u0004 מעיד עליו, כמ\"ש \u0003וכמצבייה\u0004 עביד בחיל שמייא. \u0003שדי,\u0004 מעיד עליו, כשהוא אמר לעתם \u0003די,\u0004 עמד העולם בגבולו ולא נתפשט יותר. ואף כך, למים ורוח ואש, אמר די."]],[[0,"","מִצְוָה שְׁתֵּים עֶשְׂרֵה, הִיא נִקְרֵאת חַג הַמַּצּוֹת וְחַג הַשָּׁבוּעוֹת וְחַג הַסֻּכּוֹת, מִצַּד שְׁלֹשֶׁת הָאָבוֹת. וְרֹאשׁ הַשָּׁנָה מֵהַצַּד שֶׁלָּהּ, דִּין הַמַּלְכוּת - דִּין. וְיֵשׁ שֶׁיֹּאמַר, פֶּסַח זְרוֹעַ יָמִין. שָׁבוּעוֹת, מַתַּן תּוֹרָה, שֶׁנִּתְּנָה בַּמִּדְבָּר, שֶׁהוּא מְמֻנֶּה עָלָיו שׁוֹר, מִצַּד הַגְּבוּרָה. סֻכּוֹת, (בראשית לג) וְיַעֲקֹב נָסַע סֻכֹּתָה. מִצְוָה שְׁלֹשׁ עֶשְׂרֵה, קְרִיאַת שְׁמַע."],[1,"","וְיֵשׁ לָדַעַת שֶׁהוּא נִקְרָא חָכָם בְּכָל מִינֵי חָכְמוֹת, וּמֵבִין בְּכָל מִינֵי תְבוּנוֹת, וְחָסִיד בְּכָל מִינֵי חֲסָדִים, וְגִבּוֹר בְּכָל מִינֵי גְבוּרוֹת, וְיוֹעֵץ בְּכָל מִינֵי עֵצוֹת, וְצַדִּיק בְּכָל מִינֵי צְדָקוֹת, וּמֶלֶךְ בְּכָל מִינֵי מַלְכוּת, עַד אֵין סוֹף. עַד (כתר) אֵין חֵקֶר. וּבְכָל אֵלּוּ הַדְּרָגוֹת, בְּאַחַת נִקְרָא רַחֲמָן, וּבְאַחַת נִקְרָא דַּיָּן. וְכָךְ בְּכַמָּה דְרָגוֹת עַד אֵין סוֹף. אִם כָּךְ, שִׁנּוּי יֵשׁ בֵּין רַחֲמָן לְדַיָּן. אֶלָּא קֹדֶם שֶׁבָּרָא הָעוֹלָם נִקְרָא הוּא בְּכָל אֵלּוּ הַדְּרָגוֹת, עַל שֵׁם בְּרִיּוֹת שֶׁהָיוּ עֲתִידוֹת לְהִבָּרְאוֹת. שֶׁאִם לֹא בְּרִיּוֹת הָעוֹלָם, מַדּוּעַ נִקְרָא רַחוּם, דַּיָּן? אֶלָּא עַל שֵׁם הַבְּרִיּוֹת הָעֲתִידוֹת."],[2,"","וּמִפְּנֵי זֶה כָּל הַשֵּׁמוֹת הֵם כִּנּוּיִים שֶׁלּוֹ, עַל שֵׁם הַמַּעֲשִׂים שֶׁלּוֹ. כְּמוֹ כֵן בָּרָא הַנְּשָׁמָה בַּדְּמוּת שֶׁלּוֹ, שֶׁנִּקְרֵאת עַל שֵׁם פְּעֻלּוֹת שֶׁלָּהּ בְּכָל אֵיבָר וְאֵיבָר שֶׁל הַגּוּף, שֶׁנִּקְרָא עוֹלָם קָטָן. כְּמוֹ שֶׁאֲדוֹן הָעוֹלָם נוֹהֵג בְּכָל הַבְּרִיּוֹת וּבְכָל דּוֹר כְּפִי מַעֲשָׂיו, כָּךְ הַנְּשָׁמָה כְּפִי מַעֲשָׂיו שֶׁל כָּל אֵיבָר וְאֵיבָר. אוֹתוֹ אֵיבָר שֶׁעוֹשֶׂה בּוֹ מִצְוָה, נִקְרֵאת הַנְּשָׁמָה לְגַבָּיו חֶמְלָה וָחֶסֶד וְחֵן וְרַחֲמִים. וּבְאוֹתוֹ אֵיבָר שֶׁעוֹשֶׂה בּוֹ עֲבֵרָה, נִקְרֵאת הַנְּשָׁמָה לְגַבָּיו דִּין וְחֵמָה וָכַעַס. אֲבָל לַחוּץ מִן הַגּוּף, לְמִי תִהְיֶה חֶמְלָה אוֹ אַכְזָרִיּוּת?"],[3,"","אַף כָּךְ אֲדוֹן הָעוֹלָם, קֹדֶם שֶׁבָּרָא אֶת הָעוֹלָם וּבָרָא בְּרִיּוֹתָיו, לְמִי נִקְרָא רַחוּם וְחַנּוּן אוֹ דַּיָּן? אֶלָּא כָּל הַשֵּׁמוֹת שֶׁלּוֹ הֵם כִּנּוּיִים, וְלֹא נִקְרָא בָּהֶם אֶלָּא עַל שֵׁם בְּרִיּוֹת הָעוֹלָם. וּמִפְּנֵי זֶה, כַּאֲשֶׁר בַּעֲלֵי הַדּוֹר הֵם טוֹבִים, הוּא נִקְרָא אֶצְלָם יְהֹוָ\"ה, בְּמִדַּת הָרַחֲמִים. וְכַאֲשֶׁר בַּעֲלֵי הַדּוֹר הֵם רְשָׁעִים, נִקְרָא אֲדנָ\"י, בְּמִדַּת הַדִּין. לְכָל דּוֹר וּלְכָל בֶּן אָדָם כְּפִי מִדָּתוֹ. אֲבָל לֹא שֶׁיֵּשׁ לוֹ מִדָּה וְלֹא שֵׁם יָדוּעַ."],[4,"","כְּמוֹ הַסְּפִירוֹת, שֶׁכָּל סְפִירָה יֵשׁ לָהּ שֵׁם יָדוּעַ וּמִדָּה וּגְבוּל וּתְחוּם. וּבְאֵלּוּ הַשֵּׁמוֹת אֲדוֹן הָעוֹלָם הוּא מִתְפַּשֵּׁט, וּמוֹלֵךְ בָּהֶם, וְנִקְרָא בָּהֶם, וְנִתְכַסֶּה בָּהֶם, וְגָר בָּהֶם, כַּנְּשָׁמָה אֵצֶל אֶבְרֵי הַגּוּף. וּמָה רִבּוֹן הָעוֹלָמִים אֵין לוֹ שֵׁם יָדוּעַ, וְלֹא מָקוֹם יָדוּעַ, אֶלָּא בְּכָל צַד שִׁלְטוֹנוֹ - אַף כָּךְ אֵין לָהּ לַנְּשָׁמָה שֵׁם יָדוּעַ, וְלֹא מָקוֹם יָדוּעַ בְּכָל הַגּוּף, אֶלָּא בְּכָל צַד שִׁלְטוֹנָהּ, וְאֵין אֵיבָר פָּנוּי מִמֶּנָּה."],[5,"","וּמִפְּנֵי זֶה אֵין לְצַיֵּר אוֹתָהּ בְּמָקוֹם אֶחָד, שֶׁאִם לֹא הֲרֵי חָסֵר הַשִּׁלְטוֹן בִּשְׁאָר הָאֵיבָרִים. וְלֹא לִקְרֹא לָהּ בְּשֵׁם אֶחָד, אוֹ בִּשְׁנַיִם, אוֹ בִּשְׁלֹשָׁה, לוֹמַר שֶׁהִיא חֲכָמָה מִבִּינָה וְיֵשׁ לָהּ דַּעַת, וְלֹא יוֹתֵר. שֶׁאִם עוֹשֶׂה כָּךְ, הֲרֵי חָסֵר לָהּ מִשְּׁאָר דְּרָגוֹת."],[6,"","כָּל שֶׁכֵּן לַאֲדוֹן הָעוֹלָם שֶׁאֵין לְצַיֵּר אוֹתוֹ בְּמָקוֹם יָדוּעַ, אוֹ לִקְרֹא לוֹ בְּשֵׁמוֹת, אוֹ לִשְׁנוֹת לוֹ בָּהֶם, אוֹ (לשלש) לְהַשְׁלִיט לוֹ כְּמוֹ דַּרְגַּת הַמֶּרְכָּבָה שֶׁנֶּאֱמַר בָּהּ קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. שֶׁכָּל הַדְּרָגוֹת שֶׁל הַמֶּרְכָּבוֹת שֶׁלּוֹ הֵן מְשֻׁלָּשׁוֹת, כְּמוֹ הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה, שֶׁהֵם דְּמוּת אַרְיֵה שׁוֹר נֶשֶׁר, שֶׁהֵם מֶרְכָּבָה לְאָדָם, שֶׁנֶּאֱמַר עָלָיו (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וּמִצַּד הַנְּקֵבָה הֵם שׁוֹלְטִים עַל אָדָם, וְהַנְּקֵבָה הִיא מֶרְכָּבָה לְגַבֵּיהֶם. וּמִפְּנֵי זֶה נֶאֱמַר עָלֶיהָ, קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ."],[7,"","וְאַף כָּךְ הָאוֹתִיּוֹת, שֶׁהֵן פְּנֵי הַחַיּוֹת, מְשֻׁלָּשׁוֹת, כְּמוֹ זֶה: יה\"ו. הו\"י. וה\"י. ה' רְבִיעִית - קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. הִיא שְׁלָמִים שֶׁל כֻּלָּם, לְהַשְׁלִים בְּכֻלָּם שֵׁם יְהֹוָ\"ה. אֲבָל לַאֲדוֹן הַכֹּל אֵין לְשַׁלֵּשׁ בּוֹ בְּשֵׁמוֹת וְלֹא בְּאוֹתִיּוֹת, אֶלָּא הוּא נִקְרָא בְּכָל הַשֵּׁמוֹת, וְאֵין לוֹ שֵׁם יָדוּעַ, וְכָל שֵׁם וְשֵׁם מֵעִיד עָלָיו שֶׁהוּא אֲדוֹן כָּל הָעוֹלָמוֹת. מֵעִיד עָלָיו אֲדנָי."],[8,"","וְאֵין שֶׁיּוֹדְעִים שֶׁיֵּשׁ בֶּן אָדָם שֶׁיּוֹרֵשׁ שְׁלֹשׁ מֵאוֹת וַעֲשָׂרָה עוֹלָמוֹת, זֶהוּ שֶׁכָּתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ. כְּפִי הַדַּרְגָּה שֶׁלּוֹ, שֶׁנִּקְרֵאת יֵשׁ מֵאַיִן. וְזוֹ חָכְמָה עֶלְיוֹנָה. וְיֵשׁ בֶּן אָדָם שֶׁלֹּא יוֹרֵשׁ אֶלָּא עוֹלָם אֶחָד, כְּפִי הַדַּרְגָּה שֶׁלּוֹ, כְּמוֹ שֶׁפֵּרְשׁוּהוּ, כָּל צַדִּיק וְצַדִּיק יֵשׁ לוֹ עוֹלָם בִּפְנֵי עַצְמוֹ. וְכָךְ יוֹרֵשׁ עוֹלָמוֹת כָּל אָדָם מִיִּשְׂרָאֵל כְּפִי הַדַּרְגָּה שֶׁלּוֹ לְמַעְלָה. אֲבָל לַאֲדוֹן הָעוֹלָם אֵין לְצַיֵּר לוֹ עוֹלָמוֹת בְּחֶשְׁבּוֹן, אֶלָּא אֲדוֹן כָּל הָעוֹלָמוֹת, וַאדנָ\"י הוּא מֵעִיד עָלָיו."],[9,"","אַף כָּךְ יְהֹוָ\"ה, מִמֶּנּוּ תְּלוּיוֹת כָּל הַהֲוָיוֹת, וְהוּא וְכָל הַהֲוָיוֹת שֶׁלּוֹ מְעִידִים עַל אֲדוֹן הָעוֹלָם, שֶׁהוּא הָיָה קֹדֶם כָּל הַהֲוָיוֹת, וְהוּא בְּתוֹךְ כָּל הֲוָיָה, וְהוּא לְאַחַר כָּל הֲוָיָה. וְזֶה סוֹד שֶׁמְּעִידוֹת הַהֲוָיוֹת עָלָיו - הָיָה, הֹוֶה, וְיִהְיֶה."],[10,"","דִּינָא בְּהִפּוּךְ אוֹתִיּוֹת - אֲדנָ\"י. וּמִפְּנֵי זֶה אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, דִּין הַמַּלְכוּת - דִּין. שֵׁם אֵ\"ל מֵעִיד עַל אֲדוֹן הַכֹּל, שֶׁאֵין יְכֹלֶת לְכָל שֵׁם וַהֲוָיָה וְדַרְגָּה. כָּל שֶׁכֵּן לִשְׁאָר בְּרִיּוֹת פָּחוֹת מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (דניאל ד) כְּלֹא נֶחְשָׁבִים וְכִרְצוֹנוֹ עוֹשֶׂה בִּצְבָא הַשָּׁמַיִם וְגוֹ'. אֱלֹהִי\"ם מֵעִיד עַל אֱלָהוּת שֶׁלּוֹ, שֶׁהוּא אֱלֹהִי\"ם וֵאלֹהֵי הָאֱלֹהִים, וְהוּא אֱלוֹהַּ עַל הַכֹּל, וְאֵין אֱלוֹהַּ עָלָיו. צְבָאוֹ\"ת מֵעִיד עָלָיו כְּמוֹ שֶׁכָּתוּב (שם) וְכִרְצוֹנוֹ עוֹשֶׂה בִּצְבָא הַשָּׁמַיִם. שַׁדַּ\"י מֵעִיד עָלָיו, שֶׁכַּאֲשֶׁר הוּא אָמַר לָעוֹלָם דַּי, עָמַד בִּתְחוּמוֹ וְלֹא הִתְפַּשֵּׁט יוֹתֵר. וְגַם לַמַּיִם, וְרוּחַ וְאֵשׁ."]]],[["וְאוֹף הָכִי, כָּל הֲוָיָה, וְשֵׁם, סָהֲדִין עָלֵיהּ. דְּכַד הֲוָה אִיהוּ יָחִיד קוֹדֶם דְּבָרָא עָלְמָא, אֲמַאי הֲוָה אִיהוּ צָרִיךְ לְאִתְקְרֵי בִּשְׁמָהָן אִלֵּין, אוֹ בִּשְׁאַר כִּנּוּיִין, כְּגוֹן (שמות ל״ד:ו׳) רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְגוֹ', דַּיָּין אַמִּיץ חָזָק. וְסַגִּיאִין בְּכָל אִינּוּן שְׁמָהָן וְכִנּוּיִין, אִתְקְרֵי עַל שֵׁם כָּל עָלְמִין וּבִרְיָין דִּלְהוֹן, לְאַחֲזָאָה שׁוּלְטָנוּתֵיהּ עָלַיְיהוּ.","אוּף הָכִי נִשְׁמְתָא, (תיקונין כ\"ד ע\"א) עַל שׁוּלְטָנוּתָא דְּכָל אֵבָרִים דְּגוּפָא, אַמְתִּיל לָהּ לְגַבֵּיהּ. לָאו דְּאִיהִי אַדְמְיָא לֵיהּ אִיהִי בְּעַצְמָהּ, דְּהוּא בָּרָא לָהּ, וְלֵית לֵיהּ אֱלוֹהַ עָלֵיהּ דְּבָרָא לֵיהּ. וְעוֹד, נִשְׁמְתָא אִית לָהּ כַּמָה שִׁנּוּיִים וּמִקְרִים וְסִבּוֹת, דְּאִתְקְרִיאוּ לָהּ. מַה דְּלָאו הָכִי לְמָארֵי כֹּלָּא. וּבְגִין דָּא הִיא אַדְמְיָא בְּשָׁלְטָנוּתָא דִּילָהּ עַל כָּל אֵבָרֵי גּוּפָא, אֲבָל לָא בְּמִלָּה אַחֲרָא.","וְעוֹד, (דברים ו) שְׁמַע יִשְׂרָאֵל, שֵׁם ע' רַבָּתִי, ד' מִן אֶחָ\"ד רַבָּתִי, הַיְינוּ עֵ\"ד, בֵּין שֵׁ\"ם מִן שְׁמַע, א\"ח מִן אֶחָ\"ד. (שמואל א י״ב:ה׳) עֵד יְיָ בָּכֶם. וְעַל כָּל אֶחָד וְאֶחָד דִּמְיַחֵד אוֹתוֹ בָּעוֹלָם. וְעַל כֵּן אָמַר דָּוִד, (תהילים ק״ד:ל״ד-ל״ה) אָנֹכִי אֶשְׂמַח בַּיְיָ, (עיין לעיל רל\"ו ע\"ב) ש\"מ מִן שְׁמַע, א\"ח מִן אֶחָ\"ד, הֲרֵי אֶשְׂמַח.","וְעוֹד. ד' רַבָּתִי, ד' בָּתֵּי תְּפִילִּין, דְּמָנַח לְהוֹן א\"ח, וְאִתְעֲטָּר בְּהוּ, וְאִינּוּן פְּאֵר עַל רֵישֵׁיהּ. וְאִינּוּן יהו\"ה (ס\"א יהה\"ו), י' עֲטָרָא עַל ה', דְּאִיהִי בְּרַתָּא, וְהַיְינוּ (משלי ג׳:י״ט) יְדוָֹ\"ד בְּחָכְמָה יָסַד אָרֶץ, אַבָּא יָסַד בְּרַתָּא. ה', אִמָּא עִלָּאָה, עֲטָרָה עַל ו', דְּאִיהוּ בְּרָא, וְהַיְינוּ (משלי ג׳:י״ט) כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. בְּאִמָּא כּוֹנֵן בְּרָא. וְהַאי אִיהוּ דְּעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם.","וּבְרַתָּא אִיהִי תְּפִלָּה שֶׁל יַד, כֵּהָ\"ה. י' קֶשֶׁר דִּילֵיהּ. ה' עִלָּאָה אִימָּא, תְּפִלִּין דְּרֵישָׁא עַל רֹאשׁ תִּפְאֶרֶת. תְּפִלִּין דִּילֵיהּ, כְּסֵדֶר יְדוָֹ\"ד, דְּאִיהוּ קַדֶּשׁ לִי. וְהָיָה כִּי יְבִאֲךָ. שְׁמַע. וְהָיָה אִם שָׁמוֹעַ. אֲבָל בְּעָלְמָא דְּאָתֵי, הֲוָיוֹת בְּאֶמְצַע, דְּאִינּוּן ה' ה'. וּבְגִין דָּא אָמַר הַנָבִיא, (ירמיהו ט׳:כ״ג) בְּזֹאת יִ\"תְהַלֵּל הַ\"מִתְהַלֵּל הַ\"שְׂכֵּל וְ\"יָדוֹעַ אוֹתִי כִּי אֲנִי יְדוָֹ\"ד. וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, דְּאִית בְּרֵישָׁא אֲתָר, לְאָנָחָא תְּרֵי זּוּגֵי דִּתְפִלֵּי. וְדָא זָכֵי לִתְרֵין פִּקוּדִין, דְּאוֹקְמוּהָ עָלַיְיהוּ, לֹא כָּל אָדָם זוֹכֶה לִשְׁתֵּי שׁוּלְחָנוֹת.","י' חָכְמָה. ה' בִּינָה. ו' עַמּוּדָא דְּאֶמְצָעִיתָא. ה' מַלְכוּת קַדִּישָׁא. רֵישָׁא דְּאִתְעַטָּר בְּאַרְבַּע אַתְוָון, דָּא כֶּתֶר רִיהֲטָא דְּרֵישָׁא דְּאַסְחַר לוֹן, וְכַסֵּי לוֹן. אַהֲבָה חֶסֶד קְרִיאַת שְׁמַע, דִּשְׁקִילָא לְאוֹרַיְיתָא, דְּאִתְיְיהִיבַת מִימִינָא. תְּפִלִּין עֹז, מִשְּׂמָאלָא דִּגְבוּרָה. עַמּוּדָא דְּאֶמְצָעִיתָא, כָּלִיל כֹּלָּא, כַּנְפֵי דְּמִצְוָה, נֶצַח וְהוֹד, תְּכֵלֶת וְלָבָן. מְזוּזָה רָשִׁים שַׁדַּי, צַדִּיק. וּשְׁכִינְתָּא תַּרְעָא דִּמְזוּזָה, זֶה הַשַּׁעַר לַיְדוָֹ\"ד.","וְעוֹד ש' תְּלַת רְצוּעוֹת. ד' קֶשֶׁר שֶׁל תְּפִילִּין מֵאֲחוֹרוֹי. י' קֶשֶׁר דִּתְפִלִּין דְּיָד. וּבְגִין דָּא שַׁדַּ\"י מִלְּבַר, יְדוָֹ\"ד מִלְּגוֹ, דְּאִיהִי ד' פָּרְשִׁיָין. דד' רָאשִׁין רֶמֶז לד' בָּתֵּי דִּתְפִילִּין, שַׁדַּ\"י אוֹת דִּילֵיהּ עוֹלֶה מטטרו\"ן.","וְעוֹד. י' חָכְמָה קַדֶּשׁ לִי. ה' בִּינָה, וְהָיָה כִּי יְבִיאֲךָ. ו' שְׁמַע, שִׁית תֵּיבִין, רְמִיזָא לְשִׁית סְפִירָן, שִׁית עַנְפִין דְּאִילָנָא, דְּכָלַל לוֹן תִּפְאֶרֶת. ה' וְהָיָה אִם שָׁמוֹעַ מַלְכוּת. אִלֵּין אִינּוּן דְּרֵישָׁא, דְּאִיהוּ כֶּתֶר, כ', (שמואל א ב׳:ב׳) אֵין קָדוֹשׁ כַּיְיָ כִּי אֵין בִּלְתֶּךָ.","שַׁדַּי, רָמִיז רְצוּעֵי וּבָתֵי וְקִשְׁרֵי דִּתְפִלִּין מִלְּבַר. אוּף הָכִי בַּמְּזוּזָה, יְדוָֹ\"ד מִלְּגוֹ, שַׁדַּ\"י מִלְּבַר, דְּאַרְבַּע רָאשִׁין עִם ד' רָמִיז לד' בָּתֵּי וּלְקֶשֶׁר תְפִלִּין מֵאָחוֹר ד' כְּפוּלָה אוּף הֲכִי ש' כְּפוּלָה, י' קֶשֶׁר דְיָד כֵּהָה דְּאִיהוּ בֵּיתָא חֲמִישָׁאָה ד' (ס\"א י') דְּשַׁדַּ\"י אִיהוּ מוֹחָא דּאוּקְמוּהַ עָלֵיהּ בַּמָּקוֹם שְׁמוֹחוֹ שֶׁל תִינוֹק רוֹפֶס בּוֹ, וְדָא תִּינוֹק יוֹנֵק מִשְּׁדֵי אִמּוֹ שַׁדַּ\"י.","תְּפִלִּין דְּמָארֵי עָלְמָא, כֶּתֶר. וּמַאי נִיהוּ כֶּתֶר דְּמָארֵי עָלְמָא. יְדוָֹ\"ד. דְּאִיהוּ: י' חָכְמָה. ה' בִּינָה. ו' תִּפְאֶרֶת. כָּלִיל שִׁית סְפִירָין. ה' מַלְכוּת. וּבְגִין דָּא (שמואל ב ז׳:כ״ג) וּמִי כְעַמְּךָ כְּיִשְׂרָאֵל (דברים ד׳:ז׳) כִּי מִי גּוֹי גָּדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרוֹבִים אֵלָיו, כַּיְיָ אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. אַרְבַּע קְרָאֵי, כֻּלְּהוּ רְשִׁימִין בְּכ', רָזָא דְּאָת כ': י' י'. דְּאִיהִי י' י' מִן יְאֲהדוָֹנָהי, (במדבר ז׳:פ״ו) עַשָׂרָה עַשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ, כּ' מִן כֶּתֶר, כְּלִילָא מֵעֶשֶׂר סְפִירָאן, כְּלִילָן מֵעֵילָּא לְתַתָּא, וּמֵעֶשֶׂר סְפִירָאן מִתַּתָּא לְעֵילָּא.","וְאִלֵּין אִינּוּן, (תהילים קמ״ח:ד׳) וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם, מַיִם עֶלְיוֹנִים זְכָרִים, מַיִם תַּחְתּוֹנִים נְקֵבוֹת. וְעָלַיְיהוּ אָמַר רִבִּי עֲקִיבָא לְתַלְמִידָיו, כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר, אַל תֹּאמְרוּ מַיִם מַיִם, שֶׁמָא תִּסְתַּכְּנוּ בְּנַפְשְׁכֶם. דְּלָאו אִינּוּן מַיִם כְּמַשְׁמָעָן. אֶלָּא אִיהוּ אוֹר נוֹבֵעַ. וּבְגִין דָּא, אִדְּמוּ לְמַיִם נוֹבְעִים. וְהַאי נְהוֹרָא לֵית לֵיהּ פְּסָק, וְלֹא קִצוּץ, וּפִרוּד. וּבְגִין דְּאִינּוּן מִכֶּתֶר, אִתְקְרִיאָן שֶׁאֵין לָהֶם סוֹף, דְּכֶתֶר אֵין סוֹף אִתְקְרֵי. (ע\"כ רעיא מהימנא)."],[[0,"ואוף הכי כל וכו':","ואף כך כל הויה וכל שם מעידים עליו. כי כשהיה יחיד קודם שברא העולם למה היה צריך להקרא בשמות אלו, או בשאר כינוים, כמו רחום וחנון ארך אפים וגו', דיין אמיץ חזק. ורבים הם בכל אלו השמות וכינוים, שנקראים על שם כל העולמות והבריות שבהם, להראות שממשלתו עליהם."],[1,"עוף הכי נשמתא וכו':","אף הנשמה כך, אשר מבחינת ממשלתה על כל אברי הגוף המשילה אליו, שכמו שהוא שולט על כל העולמות כך הנשמה שולטת על כל אברי הגוף, אבל לא שהנשמה דומה לו בעצמותה, שהרי הוא ברא אותה, והוא אין לו אלוה עליו שברא אותו. ועוד שהנשמה יש לה כמה שינוים ומקרים וסבות הקורים אותה, מה שאין כן לרבון הכל. ומשום זה, הנשמה דומה לו רק בממשלתה על כל אברי הגוף, אבל לא בדבר אחר."],[2,"ועוד. שמע ישראל וכו':","ועוד. שמע ישראל, הוא אותיות \u0003שם, ע'\u0004 גדולה, ועם \u0003ד'\u0004 גדולה דאח \u0003ד,\u0004 היינו \u0003עד.\u0004 בין \u0003ש\"ם\u0004 מן שמע, שהוא המלכות הנקראת \u0003שם. וא\"ח\u0004 מן אחד, שהוא ז\"א נמצאות אותיות \u0003ע\"ד\u0004 הגדולות, שה\"ס \u0003עד\u0004 ה' בכם. וכן הוא \u0003עד.\u0004 על כל אחד ואחד המיחד אותו בעולם. וע\"כ אמר דוד אנכי \u0003אשמח\u0004 בה', כי \u0003שם\u0004 מן שמע, שהוא המלכות, ו \u0003א\"ח\u0004 מן אחד שהוא ז\"א הרי \u0003אשמח.\u0004 שה\"ס היחוד דז\"א ומלכות, מבחינת הגדלות. כי המלכות מבחינת הגדלות נקראת \u0003שם.\u0004"],[3,"ועוד. ד' רבתי וכו':","ועוד. \u0003ד'\u0004 הגדולה דאחד, רומזת על ד' בתים דתפלין שמניח אותם \u0003א\"ח,\u0004 דאחד, שהוא ז\"א, ונתעטר בהם, והם פאר על ראשו. והם סוד הצירוף \u0003יה\"הו.\u0004 ה \u0003י',\u0004 שהיא חכמה, היא עטרה על \u0003ה'\u0004 שהיא הבת, דהיינו מלכות. והיינו ה' בחכמה יסד ארץ, שאבא שה\"ס חכמה, יסד הבת, שהיא מלכות, הנקראת ארץ \u0003ה'\u0004 שניה של הצירוף יה\"הו, היא אמא עלאה, שהיא עטרה על \u0003ו'\u0004 שהוא הבן, דהיינו ז\"א, והיינו כונן שמים בתבונה. שז\"א הנקרא שמים, מקבל המוחין מתבונה, דהיינו אמא עלאה. כי אמא כוננה הבן. וזהו שעולם הבא, שהיא בינה, אין בו לא אכילה ולא שתיה אלא צדיקים יושבים ועטרותיהם בראשיהם. דהיינו ז\"א שיש לו עטרה בראשו מן הבינה הנקראת עולם הבא."],[4,"וברתא איהי תפלה וכו':","והבת, דהיינו מלכות, היא תפלה של יד כה\"ה. \u0003י'\u0004 היא קשר שלו. \u0003ה'\u0004 עליונה, דהיינו אמא, היא תפלין של ראש על ראש התפארת. התפילין שלו דהיינו המוחין שלו, הוא כסדר י\"ה ו\"ה, שהוא קדש לי, \u0003י',\u0004 והיה כי יביאך היא \u0003ה',\u0004 שמע היא \u0003ו',\u0004 והיה אם שמוע, היא \u0003ה'\u0004 אחרונה. וסדר זה הוא לתפלין של ראש ז\"א. אבל בעולם הבא, שהיא בינה, התפלין, שהם המוחין שמקבלת, הסדר הוא, הויות באמצע, שהם ה' ה', דהיינו \u0003י'\u0004 בתחילה שהוא קדש, ו \u0003ו'\u0004 בסוף דהיינו שמע, והויות, דהיינו ו \u0003היה\u0004 כי יביאך, \u0003והיה\u0004 אם שמוע, \u0003ה' ה',\u0004 באמצע. ועל זה אמר הנביא, בזאת \u0003י\u0004 תהלל \u0003ה\u0004 מתהל \u0003ה\u0004 שכל \u0003ו\u0004 ידוע אותי כי אני ה'. שהם כסדר הצירוף \u0003יה\"הו\u0004 (ועי' בהקדמת תקוני זהר דף ט' ע\"ב) ומשום זה העמידו בעלי המשנה, שיש מקום בראש להניח ב' זוגות תפלין. וזה זוכה לב' מצות. שהעמידו עליהם, לא כל אדם זוכה לב' שלחנות."],[5,"י' חכמה ה' בינה ו' וכו':","הד' פרשיות דתפלין של ראש, ה \u0003י'\u0004 שהיא קדש, היא חכמה. \u0003ה'\u0004 שהיא והיה כי יביאך, היא בינה. \u0003ו',\u0004 שהיא שמע, היא עמוד האמצעי, \u0003ה'\u0004 שהיא והיה אם שמוע, היא מלכות הקדושה. הראש הנעטר בד' אותיות אלו, הוא כתר, שהוא ההקף של הראש, המקיף את התפלין שהם המוחין, ומכסה אותם. \u0003קריאת שמע,\u0004 היא אהבה, חסד, השקולה לתורה שניתנה מימין. ה \u0003תפלין,\u0004 נקראים \u0003עז,\u0004 והם משמאל שהוא גבורה. עמוד האמצעי, שהוא תפארת, כולל הכל, שכולל חסד וגבורה. כנפי מצוה, שהם \u0003ציצית,\u0004 שבהם תכלת ולבן, הם נצח והוד. \u0003מזוזה,\u0004 שבה רשום השם \u0003שדי,\u0004 הוא צדיק, דהיינו יסוד. והשכינה היא ה \u0003שער\u0004 שבו המזוזה. שעליה כתוב, זה השער לה'."],[6,"ועוד. ש' תלת וכו':","ועוד \u0003ש'\u0004 של ג' ראשים, היא ג' רצועות, ב' רצועות שבתפלין של ראש, ואחת של תפלין של יד. \u0003ד'\u0004 היא הקשר של תפילין של ראש שמאחוריו. \u0003י'\u0004 היא הקשר של תפלין של יד. שהם אותיות \u0003שדי.\u0004 ומשום זה \u0003שדי,\u0004 הוא מבחוץ על התפלין, \u0003והויה,\u0004 היא מבפנים התפלין, שהיא ד' פרשיות שבהם. \u0003ש\u0004 של ד' ראשים רומזת לארבעה בתים של התפלין. \u0003שדי,\u0004 הוא אות שלו. של ז\"א, ועולה בגי' מטטרון."],[7,"ועוד. י' חכמה וכו':","ועוד. \u0003י'\u0004 חכמה, היא קדש לי. \u0003ה'\u0004 בינה, היא והיה כי יביאך. \u0003ו',\u0004 היא שמע, שבו שש מלות, שמע ישראל ה' אלקים ה' אחד, הרומזת לשש ספירות, שהם ששה ענפים של האילן, שתפארת כולל אותם. \u0003ה'\u0004 אחרונה, היא והיה אם שמוע, שהיא מלכות. אלו הם המוחין של הראש, שהראש, הוא כתר, שה\"ס \u0003כ',\u0004 בסו\"ה אין קדוש \u0003כ\u0004 הויה וגו'. שה \u0003כ'\u0004 של \u0003כ\u0004 הויה, הוא כתר דז\"א."],[8,"שדי רמיז רצועי וכו':","שדי, רומז לרצועות ובתים וקשרי התפלין מבחוץ. כי \u0003ש'\u0004 דשדי רומזת לג' רצועות ב' של ראש וא' של יד. \u0003ד'\u0004 דשדי רומזת לד' בתים דתפלין של ראש, וכן לקשר של \u0003ד'\u0004 שבאחורי הראש. \u0003י'\u0004 דשדי רומזת לקשר תפלין של יד. אף כך המזוזה, הויה מבפנים והשם שדי מבחוץ."],[8,"ש","של ארבעה ראשים, עם ה \u0003ד'\u0004 דשדי, רומזים לד' בתים ולקשר של תפלין דראש מאחוריו, שהוא בצורת \u0003ד'\u0004 כפולה. ואף כך \u0003ש'\u0004 כפולה. א' בצד ימין הבית, וא' בצד שמאל הבית. \u0003י'\u0004 דשדי היא הקשר של תפלין דיד כהה, שהוא בית חמישי. כלומר שד' בתים בתפלין של ראש, ובית חמישי בתפלין של יד. \u0003ד'\u0004 דשדי הוא המוח שהעמידו עליו, במקום שמוחו של תינוק רופס בו, דהיינו שמתנענע. וזהו תינוק יונק מ \u0003שדי\u0004 אמו דהיינו מן שדי. כי \u0003ד'\u0004 רומזת על מוחין דג\"ר דיניקה."],[9,"תפלין דמאתי עלמא וכו':","התפלין של רבון העלם הוא כתר. ומה הוא כתר של רבון העולם, הוא \u0003הויה.\u0004 שהוא, \u0003י'\u0004 דהויה היא חכמה, \u0003ה'\u0004 בינה, \u0003ו'\u0004 היא תפארת הכולל שש ספירות חג\"ת נה\"י, \u0003ה'\u0004 אחרונה היא מלכות. דהיינו עשר ספירות. ומשום זה, ומי \u0003כ\u0004 עמך \u0003כ\u0004 ישראל, \u0003כ\u0004 י מי גוי גדול אשר לו אלקים קרובים אליו, \u0003כ\u0004 הויה אלקינו בכל קראינו אליו. וכן הכתוב אין קדוש \u0003כ\u0004 הויה כנ\"ל (אות תקע\"ב) ארבעה פסוקים אלו כולם רשומים ב \u0003כ',\u0004 והסוד של אות \u0003כ'\u0004 היא \u0003י' י',\u0004 שהוא \u0003י' י'\u0004 מן השילוב \u0003י\u0004 אהדונה \u0003י,\u0004 שבתחילה ושבסוף. שהסו\"ה, עשרה עשרה הכף בשקל הקדש. דהיינו \u0003כף\u0004 מן כתר, הכלולה מעשר ספירות, כנ\"ל, הכלולות מעשר ספירות דאור ישר, שהן ממעלה למטה. ומעשר ספירות דאור חוזר, שהן ממטה למעלה."],[10,"ואלין אינון והמים וגו':","ואלו כ' ספירות דאור ישר ואור חוזר, הם סוד, והמים אשר מעל השמים, שהם מים עליונים זכרים, דהיינו הע\"ס דאו\"י, המים אשר מתחת לרקיע, הם מים תחתונים נקבות, דהיינו העשר ספירות דאור חוזר. ועליהם אמר ר' עקיבא לתלמידיו כשתגיעו לאבני שיש טהור, אל תאמרו, מים מים. שמא תסתכנו בנפשכם. שאין הם מים כמשמעם, דהיינו חסדים, אלא הוא אור נובע, דהיינו שהוא כלול ג\"כ מחכמה הנקרא \u0003אור,\u0004 ומבחינת החסדים הוא \u0003נובע,\u0004 ומשום זה נמשלו למים נובעים. ואור הזה אין לו הפסק, ואין לו קצוץ. ולא פרוד. (ועי' לעיל אות תתס\"ח) ומשום שהוא מכתר, הם נקראים מים שאין להם סוף, כי הכתר נקרא אין סוף. (ע\"כ רעיא מהימנא)"]],[[0,"","וְאַף כָּךְ, כָּל הֲוָיָה וְשֵׁם מְעִידִים עָלָיו. שֶׁכַּאֲשֶׁר הָיָה הוּא יָחִיד קֹדֶם שֶׁבָּרָא הָעוֹלָם, מַדּוּעַ הָיָה הוּא צָרִיךְ לְהִקָּרֵא בְּשֵׁמוֹת אֵלּוּ, אוֹ בִּשְׁאָר כִּנּוּיִים, כְּגוֹן (שמותלד) רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְגוֹ', דַּיָּן, אַמִּיץ, חָזָק. וְרַבִּים בְּכָל אֵלּוּ שֵׁמוֹת וְכִנּוּיִים. אֶלָּא נִקְרָא עַל שֵׁם כָּל עוֹלָמוֹת וּבְרִיּוֹת שֶׁלָּהֶם, לְהַרְאוֹת שִׁלְטוֹנוֹ עֲלֵיהֶם."],[1,"","אַף כָּךְ הַנְּשָׁמָה, עַל שִׁלְטוֹן כָּל אֶבְרֵי הַגּוּף הִמְשִׁיל אוֹתָהּ אֶצְלוֹ. לֹא שֶׁהִיא דּוֹמָה לוֹ הִיא בְּעַצְמָהּ, שֶׁהוּא בָּרָא אוֹתָהּ, וְאֵין לוֹ אֱלוֹהַּ עָלָיו שֶׁבָּרָא אוֹתוֹ. וְעוֹד, הַנְּשָׁמָה יֵשׁ לָהּ כַּמָּה שִׁנּוּיִים וּמִקְרִים וְסִבּוֹת שֶׁקּוֹרִים לָהּ, מַה שֶּׁאֵין כָּךְ לַאֲדוֹן הַכֹּל. וּמִפְּנֵי זֶה הִיא דּוֹמָה בַּשִּׁלְטוֹן שֶׁלָּהּ עַל כָּל אֶבְרֵי הַגּוּף, אֲבָל לֹא בְּדָבָר אַחֵר."],[2,"","וְעוֹד, (דברים ו) שְׁמַע יִשְׂרָאֵל - שֵׁם ע' רַבָּתִי, ד' מִן אֶחָ\"ד רַבָּתִי, זֶהוּ עֵ\"ד, בֵּין שֵׁ\"ם מִן שְׁמַע, א\"ח מִן אֶחָ\"ד. (שמואל א יב) עֵד ה' בָּכֶם. וְעַל כָּל אֶחָד וְאֶחָד שֶׁמְּיַחֵד אוֹתוֹ בָּעוֹלָם. וְעַל כֵּן אָמַר דָּוִד, (תהלים קד) אָנֹכִי אֶשְׂמַח בַּייָ. ש\"מ מִן שְׁמַע, א\"ח מִן אֶחָ\"ד, הֲרֵי אֶשְׂמַח."],[3,"","וְעוֹד, ד' רַבָּתִי - אַרְבָּעָה בָּתֵּי תְפִלִּין, שֶׁמֵּנִיחַ אוֹתָם א\"ח וּמִתְעַטֵּר בָּהֶם, וְהֵם פְּאֵר עַל רֹאשׁוֹ. וְהֵם יְהֹוָ\"ה (יהה\"ו), י' עֲטָרָה עַל ה', וְזוֹהִי בַּת, וְזֶהוּ (משלי ג) יְהֹוָ\"ה בְּחָכְמָה יָסַד אָרֶץ. אַבָּא יָסַד בַּת. ה', אִמָּא עֶלְיוֹנָה, עֲטָרָה עַל ו', שֶׁהוּא בֵּן, וְזֶהוּ (משלי ג) כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. בְּאִמָּא כּוֹנֵן בֵּן. וְזֶהוּ שֶׁעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם."],[4,"","וּבַת הִיא תְּפִלָּה שֶׁל יָד כֵּהָ\"ה. י' קֶשֶׁר שֶׁלָּהּ. ה' עֶלְיוֹנָה אִמָּא, תְּפִלִּין שֶׁל רֹאשׁ עַל רֹאשׁ תִּפְאֶרֶת. תְּפִלִּין שֶׁלּוֹ כְּסֵדֶר יְהֹוָ\"ה, שֶׁהוּא: קַדֶּשׁ לִי. וְהָיָה כִּי יְבִאֲךְ. שְׁמַע. וְהָיָה אִם שָׁמֹעַ. אֲבָל בָּעוֹלָם הַבָּא הֲוָיוֹ\"ת בָּאֶמְצַע, שֶׁהֵם ה' ה'. וּמִפְּנֵי זֶה אָמַר הַנָּבִיא, (ירמיה ט) בְּזֹּאת יִ\"תְהַלֵּל הַ\"מִּתְהַלֵּל הַ\"שְׂכֵּל וְ\"יָדעַ אוֹתִי כִּי אֲנִי יְהֹוָ\"ה. וּמִפְּנֵי זֶה פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁיֵּשׁ בָּרֹאשׁ מָקוֹם לְהָנִיחַ שְׁנֵי זוּגוֹת תְּפִלִּין. וְזֶה זוֹכֶה לִשְׁתֵּי מִצְווֹת שֶׁפֵּרְשׁוּ עֲלֵיהֶן, לֹא כָּל אָדָם זוֹכֶה לִשְׁנֵי שֻׁלְחָנוֹת."],[5,"","י' -חָכְמָה, ה' -בִּינָה. ו' -הָעַמּוּד הָאֶמְצָעִי. ה' - מַלְכוּת קְדוֹשָׁה. הָרֹאשׁ שֶׁמִּתְעַטֵּר בְּאַרְבַּע אוֹתִיּוֹת זֶה כֶּתֶר הֶקֵּף הָרֹאשׁ שֶׁמְּסוֹבֵב אוֹתָם וּמְכַסֶּה אוֹתָם. אַהֲבָה חֶסֶד קְרִיאַת שְׁמַע, שֶׁשְּׁקוּלָה לַתּוֹרָה שֶׁנִּתְּנָה מִיָּמִין. תְּפִלִּין עֹז, מִשְּׂמֹאל שֶׁל גְּבוּרָה. הָעַמּוּד הָאֶמְצָעִי כּוֹלֵל הַכֹּל, כַּנְפֵי הַמִּצְוָה, נֵצַח וְהוֹד, תְּכֵלֶת וְלָבָן. בַּמְּזוּזָה רָשׁוּם שַׁדַּי, צַדִּיק. וְהַשְּׁכִינָה שַׁעַר הַמְּזוּזָה, זֶה הַשַּׁעַר לַה'."],[6,"","וְעוֹד, ש' - שָׁלֹשׁ רְצוּעוֹת. ד' - קֶשֶׁר שֶׁל תְּפִלִּין מֵאֲחוֹרָיו. י' - קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד. וּמִפְּנֵי זֶה שַׁדַּ\"י מִבַּחוּץ, יְהֹוָ\"ה מִבִּפְנִים, שֶׁהִיא אַרְבַּע פָּרָשִׁיּוֹת. שֶׁל אַרְבָּעָה רָאשִׁים רֶמֶז לְאַרְבָּעָה בָּתֵּי הַתְּפִלִּין. שַׁדַּ\"י, אוֹת שֶׁלּוֹ עוֹלָה מְ טַטְרוֹ\"ן."],[7,"","וְעוֹד, י' חָכְמָה, קַדֶּשׁ לִי. ה' בִּינָה - וְהָיָה כִּי יְבִאֲךְ. ו' - שְׁמַע, שֵׁשׁ תֵּבוֹת, רוֹמֵז לְשֵׁשׁ סְפִירוֹת, שִׁשָּׁה עַנְפֵי הָאִילָן, שֶׁכּוֹלֶלֶת אוֹתָם תִּפְאֶרֶת. ה' - וְהָיָה אִם שָׁמֹעַ, מַלְכוּת. אֵלּוּ הֵם שֶׁל הָרֹאשׁ, שֶׁהוּא כֶּתֶר, כ', (שמואל א ב) אֵין קָדוֹשׁ כַּה' כִּי אֵין בִּלְתֶּךְ."],[8,"","שַׁדַּ\"י, רָמוּז רְצוּעוֹת וּבָתֵּי וְקִשְׁרֵי הַתְּפִלִּין מִבַּחוּץ. אַף כָּךְ בַּמְּזוּזָה, יְהֹוָ\"ה מִבִּפְנִים, שַׁדַּ\"י מִבַּחוּץ, שֶׁל אַרְבָּעָה רָאשִׁים עִם ד', רֶמֶז לְאַרְבָּעָה בָּתִּים וּלְקֶשֶׁר תְּפִלִּין מֵאָחוֹר. ד' כְּפוּלָה, אַף כָּךְ ש' כְּפוּלָה, י' קֶשֶׁר שֶׁל יָד כֵּהָה, שֶׁהוּא בַּיִת חֲמִישִׁי. ד' (י') שֶׁל שַׁדַּ\"י הוּא מֹחַ, שֶׁפֵּרְשׁוּהוּ עָלָיו, בְּמָקוֹם שֶׁמֹּחוֹ שֶׁל תִּינוֹק רוֹפֵס בּוֹ, וְהוּא תִּינוֹק יוֹנֵק מִשְּׁדֵי אִמּוֹ, שַׁדַּ \"י."],[9,"","תְּפִלִּין שֶׁל אֲדוֹן הָעוֹלָם - כֶּתֶר. וּמַהוּ הַכֶּתֶר שֶׁל אֲדוֹן הָעוֹלָם? שֵׁם יְהֹוָ\"ה, שֶׁהוּא: י' - חָכְמָה. ה' - בִּינָה. ו' - תִּפְאֶרֶת, כּוֹלֶלֶת שֵׁשׁ סְפִירוֹת. ה' - מַלְכוּת. וּמִפְּנֵי זֶה, (שמואל בז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל. (דברים ד) כִּי מִי גוֹי גָּדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרֹבִים אֵלָיו כַּה' אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. אַרְבָּעָה פְסוּקִים, כֻּלָּם רְשׁוּמִים בְּכ'. סוֹד הָאוֹת כ' - י' י'. שֶׁהוּא י' י' מִן יְאֲהדוָנָהי, (במדבר ז) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. כ' מִן כֶּתֶר, כְּלוּלָה מֵעֶשֶׂר סְפִירוֹת, כְּלוּלוֹת מִמַּעְלָה לְמַטָּה, וּמֵעֶשֶׂר סְפִירוֹת מִמַּטָּה לְמַעְלָה."],[10,"","וְאֵלּוּ הֵם: (תהלים קמח) וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם, מַיִם עֶלְיוֹנִים - זְכָרִים, מַיִם תַּחְתּוֹנִים - נְקֵבוֹת. וַעֲלֵיהֶם אָמַר רַבִּי עֲקִיבָא לְתַלְמִידָיו: כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר, אַל תֹּאמְרוּ מַיִם מַיִם, שֶׁמָּא תִסְתַּכְּנוּ בְנַפְשְׁכֶם. שֶׁאֵינָם מַיִם כְּמַשְׁמָעָם, אֶלָּא הוּא אוֹר נוֹבֵעַ, וּמִפְּנֵי זֶה נִדְמוּ לְמַיִם נוֹבְעִים, וְזֶה הָאוֹר אֵין לוֹ הֶפְסֵק, וְלֹא קִצּוּץ וּפֵרוּד. וּמִפְּנֵי שֶׁהֵם מִכֶּתֶר, נִקְרְאוּ שֶׁאֵין לָהֶם סוֹף, שֶׁכֶּתֶר נִקְרָא אֵין סוֹף."]]],[["(במדבר כ״ח:כ״ז) וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַיְיָ. תָּא חֲזֵי, בְּפֶסַח כְּתִיב, וְהִקְרַבְתֶּם אִשֶּׁה עוֹלָה לַיְיָ. וְהָכָא לָא כְּתִיב אִשֶּׁה, (דהא ביומא דא אשה לא כתיב ביה) אֶלָּא וְהִקְרַבְתֶּם עוֹלָה. מַאי טַעְמָא. יוֹמָא דָּא, יוֹמָא דְּעַיְילַת כַּלָּה לְחוּפָּה אִיהוּ. וְיִשְׂרָאֵל מָנוּ יוֹמִין דְּדַכְיוּ. יוֹמִין וְשָׁבוּעִין, וְאִתְכְּלִילוּ וְעָאלוּ בְּיוֹמִין דְּדַכְיוּ. וְהִיא נַפְקַת מִכָּל סִטְרָא בִּישָׁא, וְנַטְרַת יוֹמֵי דַּכְיוּ כַּדְּקָא חֲזֵי. וְרָזָא דָּא, מַלְכָּא טַעַם בְּתוּלָה טָעִים. בְּגִין כָּךְ לָא כְּתִיב בֵּיהּ אִשֶּׁה, דְּהָא אַחֲרָא לָא קָרִיב לְמַשְׁכְּנָא, וְהָא אִתְרְחַק מִתַּמָּן. וְעַל דָּא אִשִּׁים לָאו הָכָא, וְלָאו אִצְטְרִיכוּ לְהָכָא, וְיִשְׂרָאֵל מְרַחֲקָן אִינּוּן מִן סִטְרָא בִּישָׁא. (ומנן יומין דדכיו, יומין ושבועין, ואתכלילו ועאלו ביומין דדכיו). אָמַר רִבִּי אַבָּא, עֲדַיִין צְרִיכִין אֲנָן לְפִתְחָא דָּא לְמִפְתַּח.","אָמַר רַבִּי שִׁמְעוֹן, אֲרִימִית יְדַי בְּצַלּוּ לְמַאן דְּבָרָא עָלְמָא, וְרָזָא דָּא, אַשְׁכְּחָן בְּסִפְרֵי קַדְמָאֵי, אִשִּׁים אִינּוּן בְּאֶמְצָעִיתָא, וְאַתְיָין בְּסִטְרָא דָּא וּבְסִטְרָא דָּא, אִדַבְּקוּ בְּאִילָנָא דְּדַעַת טוֹב וָרָע, אִדַבְּקָן בְּרָע, וְאִדַבְּקָן בְּטוֹב. וּבְגִין כָּךְ, בִּשְׁאַר יוֹמִין כְּתִיב בְּהוּ אִשֶּׁה עוֹלָה. אֲבָל בְּהָנֵי יוֹמָא, דְּאִילָנָא דְּחַיֵּי קַיְּימָא, וְלָא אַחֲרָא, לֵית אֲנָן צְרִיכִין לְאִשֶּׁה, וְלָא אִצְטְרִיךְ לְמֶהֱוִי תַּמָּן. וְיוֹמָא דָּא, יוֹמָא דְּאִילָנָא דְּחַיֵּי אִיהוּ, וְלָא דְּדַעַת טוֹב וָרָע. וּבְגִין דָּא, וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַיְיָ, וְלָא אִשֶׁה לַיְיָ עוֹלָה. וְעוֹלָה, לָשׁוֹן (נ\"א לשם) עוֹלֶה, כְּמָה דְּאִתְּמַר, וְהָא אִתְּעַרְנָא מִלֵּי דְּפָרִים בְּנֵי בָּקָר, וְכָל הַהוּא קָרְבָּן.","(במדבר כ״ט:א׳) וּבַחֹדֶשׁ הַשְּׁבִיעִי, כְּמָה דְּאִתְּמַר, יוֹמָא דְרֹאשׁ הַשָּׁנָה, דִּינָא דְּכָל עָלְמָא, דִּינָא תַּקִּיפָא, וְדִינָא רַפְיָא. וַעֲשִׂיתֶם עוֹלָה, וְהִקְרַבְתֶּם מִבָּעֵי לֵיהּ, כִּשְׁאַר כָּל יוֹמִין, מַאי וַעֲשִׂיתֶם. אֶלָּא בְּיוֹמָא דָּא, (בראשית כ״ז:ד׳) וַעֲשֵׂה לִי מַטְעַמִּים כְּתִיב. כַּמָה מַטְעַמִּים וְתַבְשִׁילִים עָבְדוּ יִשְׂרָאֵל בְּהָנֵי יוֹמֵי, בְּעוֹד דִּמְקַטְרְגָא אָזִיל לְפַשְׁפְּשָׁא בְּחוֹבִין דְּעָלְמָא. וְעַל דָּא לָא כְּתִיב וְהִקְרַבְתֶּם, אֶלָּא וַעֲשִׂיתֶם עוֹלָה. וְלָא אִשֶּׁה עוֹלָה. וְכֵן בְּכָל שְׁאַר יוֹמִין, (ס\"א בקרבנין) לָא כְּתִיב אִשֶּׁה, דְּלֵית לוֹן חוּלָקָא בְּכָל הָנֵי יוֹמֵי. כָּל שֶׁכֵּן בְּהַאי יוֹמָא, דַּאֲנָן עַבְדִּין מַטְעַמִּים וְתַבְשִׁילִים בְּלָא דַּעְתָּא דְּסִטְרָא אַחֲרָא, דְּהָא יִצְחָק מְשַׁדֵּר לֵיהּ לָצוּד צֵידָה דְּחוֹבִין דִּבְנֵי עָלְמָא, וּלְאַיְיתָאָה לְגַבֵּיהּ.","וּבְעוֹד דְּאִיהוּ אָזִיל, יִשְׂרָאֵל נַטְלֵי עֵיטָא בְּרִבְקָה, וְעַבְדִין כָּל אִינּוּן פּוּלְחָנִין, כָּל אִינּוּן צְלוֹתִין, מְזַמְּנֵי שׁוֹפָר וְתַקְעִין לֵיהּ, בְּגִין לְאַתְּעָרָא רַחֲמֵי. וְהָא אוֹקִימְנָא, (בראשית כ״ז:כ״ה) וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ, דְּאָתֵי (ס\"א דאכל) מֵרָחוֹק, מִגּוֹ אֲתָר דְּחַמְרָא עַתִּיקָא, וְשָׁתֵי. וְאַטְעִים לֵיהּ, וְחַדֵּי. וְאַחַר כַּךְ מְבָרֵךְ לֵיהּ בְּכַמָּה בִּרְכָאן, וְאַעְבַּר עַל חוֹבוֹי. מַה כְּתִיב, (בראשית כ״ז:ל׳) וַיְהִי אַךְ יָצוֹא יָצָא יַעֲקֹב וְעֵשָׂו אָחִיו בָּא מִצֵּדוֹ, טָעִין מִכַּמָּה טוֹעֲנֵי כְּמָה דְּאִתְּמַר, וְהָא אוֹקִימְנָא מִלָּה.","וּבְגִין כָּךְ אִיהוּ יוֹמָא דִּיבָבָא, וְקָרְבְּנָא אִיהוּ עוֹלָה. אַיִל אֶחָד, כְּמָה דְּאִתְּמַר, בְּגִין אֵילוֹ דְּיִצְחָק. וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת, שׁוֹחַד לְסַמָאֵל לְכַפְּרָה (לתברא) אַנְפּוֹי, בְּהַהוּא בִּכְיָה דְּאִיהוּ בָּכֵי בְּהַאי יוֹמָא, כֵּיוָן דְּחָמֵי דְּלָא אִתְעָבִיד רְעוּתֵיהּ, וְהָא לְמַגָּנָא צַד צֵידָה. כְּמָה דְּאִתְּמַר. כְּגַוְונָא דָּא יוֹמָא דְּכִפּוּרֵי, וְהָא כְּתִיב בְּפָּרָשַׁת אֱמוֹר.","(במדבר כ״ט:י״ב) וּבַחֲמִשָּׁה עָשָׂר יוֹם וְגוֹ'. רִבִּי אַבָּא פָּתַח, (בראשית ח׳:ד׳) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ', תָּא חֲזֵי, כָּל הָנֵי יוֹמִין, אַזְלַת אִימָּא עַל בְּנַיָּיא, בְּגִין דְּלָא יִשְׁלוֹט סִטְרָא אַחֲרָא עָלַיְיהוּ, וּבְגִין לְשֵׁזָבָא לוֹן. כֵּיוָן דְּאִשְׁתְּזִיבוּ בְּנָהָא, וְהָא יַתְבִין בַּסֻּכּוֹת, מִתְנַטְּרִין בִּנְטוּרָא. יוֹמָא קַדְמָאָה, וְיוֹמָא תִּנְיָנָא, פַּקְדַת לוֹן לְיִשְׂרָאֵל, לְמֶעְבַּד סְעוּדָתָא לִמְּמָנָן דִּשְׁאַר עַמִּין, וְאִיהִי לָא שַׁרְיָא תַּמָּן. בְּיוֹמָא תְּלִיתָאָה, דְּאִיהוּ י\"ז לַחֹדֶשׁ, שָׁרִיאַת לְמִשְׁרֵי עָלַיְיהוּ. הֲדָא הוּא דִכְתִיב, וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ עַל הָרֵי אֲרָרָט, טוּרִין דְּכָל לְוָוטִין וּמְרָדִין שָׁרָאן בְּגַוַויְיהוּ.","אָמַר רִבִּי אֶלְעָזָר, יוֹמָא קַדְמָאָה דְּחַג, לָא שַׁרְיָא עָלַיְיהוּ, וְלָא יוֹמָא תִּנְיָינָא, אֶלָּא יוֹמָא תְּלִיתָאָה, דְּאוֹסִיף וְגָרַע שַׁרְיָא עָלַיְיהוּ, אוֹסִיף אַתְוָון, וְגָרַע קָרְבְּנִין. דִּכְתִּיב עַשְׁתֵּי עָשָׂר וְגוֹ'. וְהָכִי אִתְחֲזֵי לְרַע עַיִן, בְּגִין דְּיוֹמָא קַדְמָאָה וְיוֹמָא תִּנְיָינָא חֶדְוָה דִּבְנָהָא, וְאִינּוּן מְפַלְגֵּי עִדָּאָן לוֹן. מִיּוֹמָא תְּלִיתָאָה וּלְהָלְאָה, דְּאִיהִי שַׁרְיָא עָלַיְיהוּ, מַה כְּתִיב. (בראשית ח׳:ה׳) וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר עַד הַחֹדֶשׁ הָעֲשִׂירִי בָּעֲשִׂירִי בְּאֶחָד לַחֹדֶשׁ נִרְאוּ רָאשֵׁי הֶהָרִים וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר, אִלֵּין קָרְבְּנִין, דְּאַזְלִין וּמִתְמַעֲטִין. וּכְמָה דְּאִינּוּן מִתְמַעֲטִין, הָכִי נָמֵי אִתְמְעַט טוּבָא דִּלְהוֹן."],[[0,"והקרבתם עולה לריח","וגו': והקרבתם עולה לריח ניחח לה'. בוא וראה, בפסח כתוב, והקרבתם אשה עולה לה'. וכאן לא כתוב אשה, אלא והקרבתם עולה. מהו הטעם. ומשיב, יום הזה, של חג השבועות, הוא יום שהכלה נכנסה לחופה. דהיינו המלכות נכנסה לחופה עם ז\"א. וישראל באו מן ספירת ימי טהרה, ימים ושבועות, ונכללו ונכנסו בימי טהרה אלו, שה\"ס ז' ימים חג\"ת נהי\"מ, שבכל אחת חג\"ת נהי\"מ. דהיינו מ\"ט יום. והיא, המלכות יצאה מכל הצד הרע, דהיינו שאין להם עוד אחיזה בה, ושמרה ימי טהרה כראוי, דהיינו מ\"ט ימי הספירה, וז\"ס מלכא טעם בתולה טעים. כלומר, שה\"ס, בתולה ואיש לא ידעה, שסודו, שאגלאי מלתא, שלא היתה אחיזה בה לשום איש מסטרא אחרא. משום זה לא כתוב בו \u0003אשה,\u0004 כי אחר לא קרב אל המשכן, שהוא המלכות, וכבר נתרחק צד האחר משם. וע\"כ אין כאן אשים, ולא נצרכו כאן, כי ישראל נתרחקו מן צד הרע. אמר ר' אבא, עדיין אנו צריכים לפתוח הפתח כאן. פירוש. האשים, הם דינין (כנ\"ל במראות הסולם אות ו' ז', ע\"ש) וכיון שכאן כבר יצאה המלכות מכל הדינים שבה, על כן לא כתוב והקרבתם \u0003אשה\u0004 עולה, אלא והקרבתם עולה סתם."],[1,"אר\"ש ארימית ידי","וכו': א\"ר שמעון הרימותי ידי בתפלה למי שברא העולם. וסוד זה מצאתי בספרים ראשונים. \u0003אשים,\u0004 הם באמצע הטוב והרע, ובאים בצד זה ובצד זה, כי נדבקו בעץ הדעת טוב ורע, ע\"כ נדבקו ברע ונדבקו בטוב, ומשום זה, בשאר ימים כתוב בהם אשה עולה, משום שיש בהם דינים ואחיזה בעץ הדעת טו\"ר. אבל באלו הימים שעץ החיים נמצא ולא אחר, דהיינו בשבועות, אין אנו צריכים ל \u0003אשה\u0004 ואינו צריך להיות שם. כי יום זה, דשבועות, הוא של עץ החיים ולא של עץ הדעת טוב ורע. ומשום זה כתוב, והקרבתם עולה לריח ניחח לה', ולא אשה לה' עולה. ועולה פירושו לשון עולה, שהוא עולה לגבוה, כמו שלמדנו. וכבר הערנו הדברים בפירוש של פרים בני בקר, וכל קרבן ההוא."],[2,"ובחדש השביעי כמה","וכו': ובחדש השביעי באחד לחדש. היינו כמו שלמדנו כי יום של ראש השנה, הוא דינם של כל העולם, דין קשה ביום א'. ודין רפה, ביום ב'. שואל כתוב, ועשיתם עולה, והקרבתם היה צריך לומר כשאר כל הימים, מהו ועשיתם. ומשיב, אלא ביום זה, דראש השנה, כתוב, ועשה לי מטעמים. שיצחק אמר לעשו, שהוא המקטרג, כמה מטעמים ותבשילים עושים ישראל באלו הימים, דהיינו במצות ובתפלה, בעוד שהמקטרג הולך לחפש בעונות העולם. לעשות מהם מטעמים לקטרוג. וע\"כ לא כתוב, והקרבתם, אלא \u0003ועשיתם\u0004 עולה. דהיינו לעשות ולתקן מטעמים. ולא כתוב אשה עולה, וכן בכל שאר הימים שאין לסטרא אחרא חלק באלו הימים, לא כתוב אשה, כגון בשבועות כנ\"ל בדבור הסמוך. וכן ביום הכפורים. כל שכן ביום הזה, שאנו עושים מטעמים ותבשילים בלי דעת הסטרא אחרא. שהרי יצחק שלח אותו, לצוד צידה של עונות בני העולם ולהביא אצלו."],[2,"","פירוש. בכל הקרבנות נותנים חלק לסטרא אחרא (כנ\"ל במראות הסולם אות יג/ב ע\"ש) אבל ביום זה דראש השנה הוא להיפך, שעל ידי תקיעת שופר מבלבלים דעתו של השטן, שפירושו, שע\"י תקיעת שופר מתבטלים ג\"ר דשמאל שמשם חיות הסטרא אחרא. כי ברה\"ש שולט מצב הא' של המלכות, וה\"ס מה שיצחק, שהוא קו שמאל אמר לעשו וצידה לה ציד, שנתן לו רשות להמשיך הג\"ר דשמאל, ולעורר כל הדינים הבאים עמו, שה\"ס ויחרד יצחק חרדה גדולה. ודינים הללו מתחילים להתעורר בראש השנה, אמנם בתוך כך, \u0003אזיל ישראל נטלי עיטא ברבקה\u0004 וכו' \u0003מזמני שופר ותקעין,\u0004 כמ\"ש להלן בדבור הסמוך. דהיינו שע\"י תקיעת שופר מתמעטים הג\"ר דשמאל שהם כל המוחין דס\"א, וע\"כ הס\"א מתבלבלת. ונמצא שלא עוד שאין לה חלק מקרבנות דראש השנה, כמו בשאר הקרבנות, אלא עוד שמפסיד כל אחיזתו ומתבלבל דעתו (עי' לעיל אמור מאות קפ\"ז עד אות רכ\"ד)."],[2,"","וז\"ש, \u0003כל שכן בהאי יומא דאנן עבדין מטעמים ותבשילין בלא דעתא דסטרא אחרא,\u0004 דהיינו לא לבד שאין נותנים לו חיות מן הקרבנות אלא עוד שמבלבלים דעתו, \u0003דהא יצחק משדר ליה לצוד צידה דחובין\u0004 וכו', דהיינו מחמת שהוא מצב הא' דמלכות, שיצחק, שה\"ס קו השמאל, יושב על כסא דין, ורוצה להגביר שליטתו, שולח את עשו לצוד ציד, שהוא שימשיך ג\"ר משמאל, וכיון שנתן לו רשות, תיכף מתעוררים הדינים, שהם דנים כל העולם לכף חוב. וכמ\"ש בדבור הסמוך \u0003ובעוד דאיהו אזיל,\u0004 דהיינו מטרם שמספיק לגלות הדינים מג\"ר דשמאל, \u0003מזמני שופר ותקעין ליה בגין לאתערא רחמי,\u0004 כי ע\"י תקיעת שופר מתבטלים הג\"ר דשמאל והס\"א אינו יכול להמשיכם, ומתבלבל דעתו, ובמקומם נמשכים מטעמים דיעקב, שהם רחמים."],[3,"ובעוד דאיהו אזיל","וכו': ובעוד שהוא הולך, ישראל לוקחים עצה מרבקה, ועושים כל אלו עבודות, וכל אלו התפלות, מזמינים שופר ותוקעים, כדי לעורר הרחמים. כמ\"ש ברבור הסמוך. וכבר העמדנו, ויבא לו יין וישת, שבא מרחוק, מבינה, מאותו מקום שהיין ישן, שה\"ס הארת חכמה דו\"ק דשמאל אחר הביטול של ג\"ר דשמאל, שזה מכונה יין ישן. ושתה. והוטעם לו, ושמח. ואחר כך מברך אותו יצחק, שהוא קו השמאל, בכמה ברכות, ומעביר עונותיו. כי הארת החכמה מכפרת העונות. מה כתוב, ויהי אך יצוא יצא יעקב ועשו אחיו בא מצדו. דהיינו שנושא עמו כמה משאות של עונות, כמו שלמדנו. וכבר העמדנו הדברים (לעיל אמור אות רי\"ח רי\"ט)."],[4,"ובג\"כ איהו יומא","וכו': ומשום זה הוא יום תרועה. והקרבן הוא עולה. איל אחד, היינו כמו שלמדנו שהוא משום אילו של יצחק. ושעיר עזים אחד לחטאת, שהוא שוחד לסמאל, כי מקרבן זה בלבד הוא מקבל איזה יניקה מבחינת ו\"ק דחכמה. כדי לכפר פניו, על אותו הבכיה שבכה באותו יום, אחר שראה שלא נעשה רצונו, והוא צד ציד בחנם. כי נתבטלו הג\"ר דשמאל שלו, שהם כל כחו כנ\"ל. ומיעוט הג\"ר נקרא בכייה. כמו שלמדנו. וכעין זה הוא ביום הכפורים. והרי זה כתוב בפרשת אמור (מאות רכ\"ז עד אות רנ\"ז)."],[5,"ובחמשה עשר יום","וגו': ר' אבא פתח, ותנח התיבה בחדש השביעי וגו'. בוא וראה, כל אלו הימים מיום הכפורים עד סוכות, הולכת האם, שהיא השכינה, על הבנים, שהם ישראל, כדי שלא ישלוט הסטרא אחרא על ישראל, וכדי להצילם. כיון שנצלו הבנים ויושבים בסוכות הם נשמרים בשמירה של אמא, שהיא השכינה. ביום הראשון ויום השני של חג הסוכות, ציותה לישראל לעשות סעודה לממונים של שאר העמים. שהם ע' פרים, לע' שרים, והיא אינה שורית שם עמהם. ביום השלישי, שהוא י\"ז לחדש, השכינה מתחלת לשרות עליהם. ז\"ש ותנח התיבה בחדש השביעי בשבעה עשר יום לחדש על הרי אררט. אשר תיבה ה\"ס השכינה, הרי אררט, היינו הרים שכל הקללות וכל העונשים שורים בתוכם, שהם הממונים של האומות."],[6,"אמר רבי אלעזר","וכו': אר\"א, יום הראשון של חג אין המלכות שורה עליהם, על הממונים דע' אומות, ולא ביום השני, אלא ביום השלישי, שמוסיף וגורע, היא שורה עליהם, מוסיף אותיות וגורע קרבנות, שכתוב, עשתי עשר וגו', שזה ראוי לרע עין. כי ביום הראשון ויום השני הוא שמחה של הבנים, וישראל מחלקים להם, לממוני האומות, שלל. מיום השלישי והלאה, שהמלכות שורה עליהם, מה כתוב, והמים היו הלוך וחסור עד החדש העשירי בעשירי באחד לחדש נראו ראשי ההרים. \u0003והמים היו הלוך וחסור,\u0004 אלו הם הקרבנות שהולכים ומתמעטים. וכמו שהם מתמעטים כך מתמעט הטוב שלהם. \u0003ומרדין\u0004 פירושו עונשים, מלשון מכות מרדות. \u0003עדאן\u0004 פירושו שלל ומתנות, מלשון בבוקר יאכל \u0003עד.\u0004"],[6,"","פירוש. עיקר בנין המלכות הוא מקו שמאל שהוא הארת החכמה דשמאל, אמנם כשהיא שורה על ישראל היא בזווג עם ז\"א, שה\"ס קו האמצעי, שאז אין החכמה שבמלכות מאירה אלא ממטה למעלה. ועיקר הארתה היא מבחינת החסדים שמקבלת מז\"א. אבל כשהמלכות שורה על אומות העולם והס\"א, הוא להיפך, שאינה שורה עליהם, אלא כשהיא בפרוד מז\"א, כי האומות והס\"א אינם חפצים לקבל מקו אמצעי, שהוא ז\"א, אלא מבחינת השמאל שבמלכות בלבד."],[6,"","וז\"ש, \u0003כל הני יומין אזלת אמא על בנייא\u0004 וכו', דהיינו המלכות כשהיא בזווג עם ז\"א, שהוא קו אמצעי, \u0003בגין דלא ישלוט סטרא אחרא עלייהו,\u0004 דהיינו שהס\"א לא יעוררו אותם להמשיך החכמה ממעלה למטה מן המלכות, כדרך הסרא אחרא. \u0003כיון דאשתזיבו בנהא והא יתבין בסכות, מתנטרין\u0004 וכו' כיון שזכו לסוכה המה משומרים בשמירה עליונה שהס\"א לא יוכל עוד לשלוט עליהם להסיתם למשוך השמאל ממעלה למטה. וע\"כ \u0003פקדת לון לישראל למעבד סעודתא לממנן דשאר עמין,\u0004 דהיינו שיקריבו ע' פרים, שה\"ס המשכת הארת השמאל לשרי האומות ולסטרא אחרא בשיעור חיותם וקיומם בלבד, כי אין חיות וקיום לאומות ולסטרא אחרא, אלא מהארת השמאל בלבד. \u0003ואיהי לא שרייא תמן,\u0004 כי אין המלכות שורה עליהם אלא אם כן כשהיא בפרוד מן ז\"א, שאז היא מגבירה כח חיותם של הס\"א. ולפיכך כדי שלא לתת להם תוספת חיות, אינה שורית עליהם. אלא ישראל בלבד ממשיכים להם חלקם מן הקרבנות, וישראל אין ממשיכים אלא הארת ממטה למעלה בלבד, שהוא כתקון קו האמצעי. שהארה זו באה בדרך ג' קוין, המאירים אל המלכות, שה\"ס חו\"ג תו\"מ, ואחר שנכללים זה מזה, יש ג' קוין בכל אחד מחו\"ג תו\"מ, שהם י\"ב, שה\"ס י\"ב פרים. ועם הכולל הם י\"ג פרים. וז\"ס י\"ג פרים שהקריבו ביום א', וי\"ב פרים שהקריבו ביום ב', שהם היו בבחינת המשכת החכמה בסוד ג' קוין ומלכות המקבלתם, שבהתכללם זה מזה הם סוד י\"ב, ועם הכולל הם י\"ג. וז\"ש, \u0003בגין דיומא קדמאה ויומא תנינא חדוה דבנהא, ואינון מפלגי עדאן לון,\u0004 כי ישראל הם המחלקים הארת השמאל לממוני האומות, וע\"כ הם מחלקים להם בסוד המספר י\"ג פרים ביום א' וי\"ב פרים ביום ב'. שה\"ס התכללות ג' קוין והמלכות זה בזה. כדרך הארת קו האמצעי."],[6,"","וז\"ש \u0003ביומא תליתאה\u0004 וכו' \u0003שריאת למשרי עלייהו\u0004 וכו'. כי אחר שכבר קבלו מישראל כל מה שיכלו להאיר להם, שה\"ס י\"ב פרים. אז מתחלת המלכות לשרות על הממונים של האומות, כלומר שמכח ההארה שקבלו מי\"ב פרים שבקדושה, שהיתה מקו האמצעי, הם מתגברים וממשיכים ממלכות בלבד, דהיינו מבחינתה עצמה שהיא שמאל בלי ימין, כדי שיוכלו להמשיך ממעלה למטה כחפצם. וז\"ס שנצטוו אז ישראל להקריב \u0003עשתי עשר\u0004 פרים, וז\"ש, \u0003אלא יומא תליתאה דאוסיף וגרע, שריא עלייהו, אוסיף אתוון וגרע קרבנין דכתיב עשתי עשר\u0004 וגו'. כי ביום א' וב' השפיעו ישראל עליהם מקדושה, בסוד \u0003שתי עשר,\u0004 שהם סוד התכללות ג' קוין כנ\"ל. אבל כשהתגברו למשוך מבחינת שמאל בלי ימין דהיינו ממלכות כשהיא בפרוד, אז הוסיפו \u0003עין\u0004 רע על הארת שתי עשר פרים שקבלו ביום א' וב', ונעשה \u0003ע\u0004 שתי עשר, כי כשמוסיפים \u0003ע'\u0004 על שתי עשר נעשה \u0003ע\u0004 שתי עשר. ונמצא \u0003דאוסיף אתוון,\u0004 שהוסיף \u0003ע', וגרע קרבנין,\u0004 שכבר אין להם \u0003שתי עשר\u0004 פרים אלא \u0003עשתי עשר\u0004 פרים. וכל היו הולכים ומתמעטים עד שנפסקו לגמרי. וז\"ש, \u0003מה כתיב, והמים היו הלוך וחסור\u0004 וגו' \u0003אלין קרבנין דאזלין ומתמעטין\u0004 וכו'."]],[[0,"","וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַה' (במדבר כח). בֹּא וּרְאֵה, בְּפֶסַח כָּתוּב וְהִקְרַבְתֶּם אִשֶּׁה עֹלָה לַה'. וְכָאן לֹא כָתוּב אִשֶּׁה (שהרי ביום זה אשה לא כתובבו), אֶלָּא וְהִקְרַבְתֶּם עוֹלָה. מָה הַטַּעַם? יוֹם זֶה, יוֹם שֶׁנִּכְנֶסֶת כַּלָּה לְחֻפָּה הוּא, וְיִשְׂרָאֵל מוֹנִים יְמֵי טָהֳרָה, יָמִים וְשָׁבוּעוֹת, וְנִכְלָלִים וְנִכְנָסִים בִּימֵי הַטָּהֳרָה. וְהִיא יוֹצֵאת מִכָּל צַד רַע, וְשׁוֹמֶרֶת יְמֵי טָהֳרָה כְּמוֹ שֶׁרָאוּי. וְסוֹד זֶה, הַמֶּלֶךְ טַעַם בְּתוּלָה טוֹעֵם. מִשּׁוּם כָּךְ לֹא כָתוּב בּוֹ אִשֶּׁה, שֶׁהֲרֵי אַחֵר לֹא קָרֵב לַמִּשְׁכָּן, וַהֲרֵי מִתְרַחֵק מִשָּׁם. וְעַל כֵּן אִשִּׁים לֹא כָאן, וְלֹא צְרִיכִים לְכָאן, וְיִשְׂרָאֵל מְרֻחָקִים הֵם מִצַּד רַע (ומונים ימי טהרה, ימים ושבועות, ונכללים ונכנסים בימי הטהרה). אָמַר רַבִּי אַבָּא, עֲדַיִן צְרִיכִים אֲנַחְנוּ לְפֶתַח זֶה לִפְתֹּחַ."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, הֵרַמְתִּי יָדַי בִּתְפִלָּה לְמִי שֶׁבָּרָא הָעוֹלָם, וְסוֹד זֶה מָצָאנוּ בְּסִפְרֵי הָרִאשׁוֹנִים. אִשִּׁים הֵם בָּאֶמְצַע, וּבָאִים בְּצַד זֶה וּבְצַד זֶה, נִדְבָּקִים בְּעֵץ הַדַּעַת טוֹב וָרָע. נִדְבָּקִים בָּרָע וְנִדְבָּקִים בַּטּוֹב. וּמִשּׁוּם כָּךְ בִּשְׁאָר הַיָּמִים כָּתוּב בָּהֶם אִשֶּׁה עוֹלָה, אֲבָל בְּאֵלּוּ הַיָּמִים שֶׁעֵץ הַחַיִּים קַיָּם וְלֹא אַחֵר, אֵין אֲנַחְנוּ צְרִיכִים לְאִשֶּׁה, וְלֹא צָרִיךְ לִהְיוֹת שָׁם. וְיוֹם זֶה יוֹם שֶׁל עֵץ הַחַיִּים הוּא, וְלֹא שֶׁל דַּעַת טוֹב וָרָע. וּמִפְּנֵי זֶה, וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַה', וְלֹא אִשֶּׁה לַה' עוֹלָה. וְעוֹלָה לְשׁוֹן (לשם) עוֹלֶה, כְּמוֹ שֶׁנֶּאֱמַר, וַהֲרֵי הֵעַרְנוּ דְבָרִים שֶׁל פָּרִים בְּנֵי בָקָר, וְכָל אוֹתוֹ קָרְבָּן."],[2,"","וּבַחֹדֶשׁ הַשְּׁבִיעִי (במדבר כט), כְּמוֹ שֶׁנֶּאֱמַר, יוֹם שֶׁל רֹאשׁ הַשָּׁנָה דִּין שֶׁל כָּל הָעוֹלָם, דִּין חָזָק וְדִין רָפֶה. וַעֲשִׂיתֶם עוֹלָה?! וְהִקְרַבְתֶּם הָיָה צָרִיךְ לוֹ, כִּשְׁאָר כָּל הַיָּמִים! מַהוּ וַעֲשִׂיתֶם? אֶלָּא בְּיוֹם זֶה כָּתוּב (בראשית כז) וַעֲשֵׂה לִי מַטְעַמִּים. כַּמָּה מַטְעַמִּים וְתַבְשִׁילִים עוֹשִׂים יִשְׂרָאֵל בְּאֵלּוּ הַיָּמִים, בְּעוֹד שֶׁהַמְקַטְרֵג הוֹלֵךְ לְפַשְׁפֵּשׁ בַּחֲטָאֵי הָעוֹלָם. וְעַל כֵּן לֹא כָתוּב וְהִקְרַבְתֶּם, אֶלָּא וַעֲשִׂיתֶם עוֹלָה, וְלֹא אִשֶּׁה עֹלָה. וְכֵן בְּכָל שְׁאָר הַיָּמִים (בקרבנות) לֹא כָתוּב אִשֶּׁה, שֶׁאֵין לָהֶם חֵלֶק בְּכָל אֵלּוּ הַיָּמִים. כָּל שֶׁכֵּן בְּזֶה הַיּוֹם, שֶׁאֲנַחְנוּ עוֹשִׂים מַטְעַמִּים וְתַבְשִׁילִים בְּלִי דַעַת הַצַּד הָאַחֵר, שֶׁהֲרֵי יִצְחָק שׁוֹלֵחַ אוֹתוֹ לָצוּד צִידָה שֶׁל חֲטָאֵי בְּנֵי הָעוֹלָם וּלְהָבִיא אֶצְלוֹ."],[3,"","וּבְעוֹד שֶׁהוּא הוֹלֵךְ, יִשְׂרָאֵל לוֹקְחִים עֵצָה מֵרִבְקָה וְעוֹשִׂים כָּל אֵלּוּ הָעֲבוֹדוֹת, כָּל אֵלּוּ הַתְּפִלּוֹת, מְזַמְּנִים שׁוֹפָר וְתוֹקְעִים בּוֹ כְּדֵי לְעוֹרֵר רַחֲמִים. וַהֲרֵי בֵּאַרְנוּ, (שם) וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ, שֶׁבָּא (שאכל) מֵרָחוֹק, מִתּוֹךְ מְקוֹם הַיַּיִן הָעַתִּיק, וְשׁוֹתֶה. וְטוֹעֵם אוֹתוֹ, וְשָׂמֵחַ. וְאַחַר כָּךְ מְבָרֵךְ אוֹתוֹ בְּכַמָּה בְרָכוֹת, וּמַעֲבִיר עַל חֲטָאָיו. מַה כָּתוּב? (שם) וַיְהִי אַךְ יָצֹא יָצָא יַעֲקֹב, וְעֵשָׂו אָחִיו בָּא מִצֵּידוֹ. טָעוּן מִכַּמָּה מַשָּׂאוֹת כְּמוֹ שֶׁנִּתְבָּאֵר, וַהֲרֵי בֵּאַרְנוּ הַדָּבָר."],[4,"","וּמִשּׁוּם כָּךְ הוּא יוֹם שֶׁל יְבָבָה, וְהַקָּרְבָּן הוּא עוֹלָה. אַיִל אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר, מִפְּנֵי אֵילוֹ שֶׁל יִצְחָק. וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת, שֹׁחַד לְסָמָאֵל לְכַפֵּר (לשבר) פָּנָיו בְּאוֹתָהּ בְּכִיָּה שֶׁהוּא בּוֹכֶה בְּזֶה הַיּוֹם כֵּיוָן שֶׁרוֹאֶה שֶׁלֹּא נַעֲשָׂה רְצוֹנוֹ וַהֲרֵי לְחִנָּם צָד צִידָה, כְּמוֹ שֶׁנִּתְבָּאֵר. כְּמוֹ כֵן יוֹם הַכִּפּוּרִים, וַהֲרֵי כָּתוּב בְּפָרָשַׁת אֱמֹר."],[5,"","וּבַחֲמִשָּׁה עָשָׂר יוֹם וְגוֹ' (במדבר כט). רַבִּי אַבָּא פָּתַח, (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ'. בֹּא וּרְאֵה, כָּל אֵלּוּ הַיָּמִים הוֹלֶכֶת אִמָּא עַל הַבָּנִים כְּדֵי שֶׁלֹּא יִשְׁלֹט הַצַּד הָאַחֵר עֲלֵיהֶם וּבִכְדֵי לְהַצִּיל אוֹתָם. כֵּיוָן שֶׁנִּצְּלוּ בָנֶיהָ וַהֲרֵי יוֹשְׁבִים בַּסֻּכּוֹת, שְׁמוּרִים בִּשְׁמִירָה, יוֹם רִאשׁוֹן וְיוֹם שֵׁנִי צִוְּתָה לָהֶם לְיִשְׂרָאֵל לַעֲשׂוֹת סְעוּדָה לִמְמֻנֵּי שְׁאָר הָעַמִּים, וְהִיא לֹא שׁוֹרָה שָׁם. בְּיוֹם שְׁלִישִׁי, שֶׁהוּא י\"ז לַחֹדֶשׁ, מַתְחִילָה לִשְׁרוֹת עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ עַל הָרֵי אֲרָרָט. הָרִים שֶׁכָּל קְלָלוֹת וְיִסּוּרִים שְׁרוּיִים בְּתוֹכָם."],[6,"","אָמַר רַבִּי אֶלְעָזָר, יוֹם רִאשׁוֹן שֶׁל חַג לֹא שׁוֹרֶה עֲלֵיהֶם, וְלֹא יוֹם שֵׁנִי, אֶלָּא יוֹם שְׁלִישִׁי, שֶׁמּוֹסִיף וְגוֹרֵעַ שׁוֹרֶה עֲלֵיהֶם. מוֹסִיף אוֹתִיּוֹת וְגוֹרֵעַ קָרְבָּנוֹת, שֶׁכָּתוּב עַשְׁתֵּי עָשָׂר וְגוֹ'. וְכָךְ רָאוּי לְרַע עַיִן, מִפְּנֵי שֶׁיּוֹם רִאשׁוֹן וְיוֹם שֵׁנִי שִׂמְחַת בָּנֶיהָ, וְהֵם מְחַלְּקִים שְׁלָלָם לָהֶם. מִיּוֹם שְׁלִישִׁי וָהָלְאָה, שֶׁהִיא שׁוֹרָה עֲלֵיהֶם, מַה כָּתוּב? (שם) וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר עַד הַחֹדֶשׁ הָעֲשִׂירִי בָּעֲשִׂירִי בְּאֶחָד לַחֹדֶשׁ נִרְאוּ רָאשֵׁי הֶהָרִים. וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר - אֵלּוּ הַקָּרְבָּנוֹת שֶׁהוֹלְכִים וּמִתְמַעֲטִים. וּכְמוֹ שֶׁהֵם מִתְמַעֲטִים, כָּךְ גַּם מִתְמַעֵט הַטּוֹב שֶׁלָּהֶם."]]],[["אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, תָּא חֲזֵי, מִיּוֹמָא תִּנְיָינָא שָׁרִיאוּ מַיָּיא לְאִתְחֲזָאָה, כֵּיוָן דְּשָׁרִיאוּ מַיִם, מִיּוֹמָא תְּלִיתָאָה אִיהִי שָרַת עָלַיְיהוּ, וְאִינּוּן מַיִם לָא הֲווֹ יַדְעֵי בַּבְלָאֵי (ס\"א בכולא), אֲמַאי רְשִׁימִין הָכָא, דְּהָא טוּבָא דְּיִשְׂרָאֵל לָא הֲוִי בַּאֲתָר דְּמִעוּטָא, אֶלָּא בַּאֲתָר דְּרִבּוּיָיא. וּבְגִין דְּאִלֵּין מַיִין דִּרְשִׁימִין הָכָא אִתְמַעֲטָן, אָתֵי קְרָא לְאַשְׁמְעִינָן דִּכְתִּיב, וְהַמַּיִם אִינּוּן דִּיְדִיעָן בְּיוֹמֵי דְּחַג, אִינּוּן דִּרְשִׁימִין גּוֹ קָרְבְּנִין, דְּאִינּוּן טוּרֵי לְוָוטִין, הָיוּ הָלוֹךְ וְחָסוֹר טוּבָא דִּלְהוֹן, וּנְגִידוּ דְּאַנְגִּיד עָלַיְיהוּ, הָיוּ הָלוֹךְ וְחָסוֹר, וּבְגִין דְּאִינּוּן מַיִם דִּלְהוֹן הוּא, לָא אִתְחַבְּרָן אַתְוָון, דְּלָא יִתְחַבָּר טוּבָא דִּלְהוֹן, אֶלָּא זְעֵיר זְעֵיר.","אֲבָל לְיִשְׂרָאֵל, דְּאִינּוּן מְּקוּדְשָׁא בְּרִיךְ הוּא, מַה כְּתִיב. (תהילים ל״ד:י״א) וְדוֹרְשֵׁי יְיָ לֹא יַחְסְרוּ כָּל טוֹב. רֵישֵׁיהּ דִּקְרָא, כְּפִירִים רָשׁוּ וְרָעֵבוּ, אִלֵּין מְמָנָן דִּשְׁאַר עַמִּין. וְדוֹרְשֵׁי יְיָ, אִלֵּין יִשְׂרָאֵל, לֹא יַחְסְרוּ כָּל טוֹב, אִלֵּין אַזְלִין וְאִסְתַּלָּקוּ לְעֵילָּא לְעֵילָּא. וּבְגִין כָּךְ, טוּבָא דִּלְהוֹן דְּאִינּוּן מַיִם, הָיוּ הָלוֹךְ וְחָסוֹר. עַד הַחֹדֶשׁ הָעֲשִׂירִי. דָּא טֵבֵת, דְּהָא כְּדֵין יְמֵי הָרָעָה הֲווֹ, וְאִתְעֲרַת הַהִיא רָעָה וְאִתְתַּקְפַת, וְכַלָּה קַדִּישָׁא לָא אַנְהִירַת מִגּוֹ שִׁמְשָׁא, כְּדֵין נִרְאוּ רָאשֵׁי הֶהָרִים, אִלֵּין אִינּוּן הֲרֵי חֲשׁוֹכָא, טוּרִין דִּלְוָוטִין אִתְחָזוּן וְאִתְתְּקָפוּ, וְעַבְדִין בִּישִׁין בְּעָלְמָא.","בְּיוֹמִין אִלֵּין, אִשֶּׁה בְּהַאי עוֹלָה, דְּהָא כְּדֵין הָנֵי אִשִּׁים אָכְלֵי חוּלָקֵיהוֹן. שִׁבְעִים פָּרִים אִלֵּין, אִינּוּן לָקֳבֵל שִׁבְעִים מְמָנָן, דְּשַׁלְטוּ עַל שִׁבְעִין עַמִּין. וְסַלְּקִין בְּיוֹמָא קַדְמָאָה, וְנַחְתֵּי בְּכָל יוֹמָא וְיוֹמָא, וְאִקְרוּן פָּרִים מְנַגְּחִין בְּיוֹמִין דִּלְהוֹן. אֵילִם, (חסר) אַרְבֵּיסָר, תְּרֵין בְּכָל יוֹמָא אִינּוּן יָ\"ד יְהוָֹ\"ה. יְדָא דְּשָׁלִיטָא עָלַיְיהוּ תָּדִיר, בְּכָל יוֹמָא וְיוֹמָא. אַמְרִין בְּנֵי שָׁנָה, מִנְיָינָא דִּלְהוֹן חֵ\"ץ.","וְאִי תֵּימָא אִי הָכִי, רַע עַיִן הֲוִינָן לְגַבַּיְיהוּ. אִין, דְּהָא כְּתִיב, (משלי כ״ה:כ״ב) כִּי גֶּחָלִים אַתָּה חוֹתֶה עַל רֹאשׁוֹ. אֲבָל אֲנָן לָא יַהֲבֵינָן אֶלָּא בְּחֶדְוָותָא, דְּלֵית בְּיוֹמֵי שַׁתָּא, חֶדְוָותָא, כְּאִלֵּין יוֹמִין. וּבְגִין דַּאֲנָן יָהֲבִין בְּטוּב לִבָּא, וּבְחֶדְוָותָא דִּרְעוּתָא, אִתְהַפָּךְ עָלַיְיהוּ גֶּחָלִים עַל רֵישֵׁיהוֹן, גּוּמְרִין מְלַהֲטָן, דְּחֶדְוְותָא דִּילָן, עַבְדֵי לוֹן בִּישׁ. י\"ד, (ס\"א ה') ע', וחץ. כַּךְ סַלְּקִין בְּחוּשְׁבָּנָא דִּילְהוֹן.","וְכָל דָּא אִיתֵּימָא מַאן יָהִיב לָן לְאַקְרְבָא עָלַיְיהוּ, דִּלְמָא אִינּוּן לָא בָּעָאן כָּל דָּא. אֶלָּא לֵית חֶדְוָוה לְכָל אִינּוּן מְמָנָן, בְּכָל אִינּוּן תּוֹרִים אֵילִים וְאִמְרִין כְּהָנֵי, בְּשַׁעֲתָא דְּיִשְׂרָאֵל יַהֲבֵי לוֹן סְעוּדְתִּין אִלֵּין. וְעִם כָּל דָּא לָא מִתְקַרְבוּ כֹּלָּא, אֶלָּא לְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וְאִינּוּן מִתְקָרְבֵי תַּמָּן, וְאִיהוּ פָּלִיג לוֹן. וְעַל דָּא כְּתִיב, (משלי כ״ה:כ״א) אִם רָעֵב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לָחֶם, אִלֵּין אִינּוּן קָרְבְּנִין דְּחָג. וְאִם צָמֵא הַשְׁקֵהוּ מָיִם, אִלֵּין מַיִם דִּרְשִׁימִין הָכָא בְּיוֹמֵי דְּחָג. וּבְיוֹמָא תִּנְיָינָא, וּבְיוֹמָא שְׁתִּיתָאָה וּשְׁבִיעָאָה, וְסִימָן (שיר השירים ח׳:ז׳) בּוֹ\"ז יָבוּזוּ לוֹ.","מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה, אִלֵּין אִינּוּן מַיִם, דִּי מְנַסְּכֵי יִשְׂרָאֵל, בְּחֶדְוָה וּבִרְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (ישעיהו י״ב:ג׳) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן. וּנְהָרוֹת לֹא יִשְׁטְפוּהָ, אִלֵּין אִינּוּן נַהֲרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא, דְּכֻלְּהוּ דַּבְקֵי וּמִתְקַשְּׁרֵי בִּרְחִימוּ דָּא. אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בְּאַהֲבָה בּוֹז יָבוּזוּ, דָּא סַמָאֵל, בְּאַהֲבָה דְּיִשְׂרָאֵל, לְמֶהֱוִי לֵיהּ חוּלָקָא בַּהֲדַיְיהוּ, בְּאִינּוּן מַיִם דִּרְשִׁימִין הָכָא בְּפַרְשְׁתָּא, דִּכְתִּיב אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בְּאַהֲבָה בּוֹז יָבוּזוּ, סִימָנָא דְּאִינּוּן מַיִם בּוֹ\"ז, יָבוּזוּ לוֹ וַדַּאי, דְּהָא כֻּלְּהוּ אִתְחֲשִׁיבוּ לְגַבָּן, חֶרֶשׂ נִשְׁבָּר, דְּלֵית לֵיהּ תְקָנָה לְעָלְמִין.","מַיִם דִּלְהוֹן אִתְפְּלִיגוּ בְּיוֹמִין בּוֹ\"ז, אִשְׁתָּאֲרוּ שְׁאַר יוֹמִין, דְּאִינּוּן ג' ד' ה' (נוטריקון) חֲמִישִׁי רְבִיעִי שְׁלִישִׁי, וְסִימָן, (ישעיהו מ״ה:ט׳) חֶרֶ\"שׂ אֶת חַרְשֵׂי הָאֲדָמָה, וְלֵית לוֹן תִּקּוּנָא בַּהֲדָן, וְלָא לְעָלְמִין. וְאִי תֵּימָא בּוֹז יָבוּזוּ לוֹ כְּתִיב. הָתָם (תהילים כ״ב:כ״ה) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת.","יוֹמָא קַדְמָאָה מַאי עָבִיד לֵיהּ. אֶלָּא לָא אִקְרֵי רִאשׁוֹן, וְלָא אִקְרֵי אֶחָד, אֶלָּא חֲמִשָּׁה עָשָׂר סְתָם, בְּלָא רְשׁוּמָא כְּלַל. אֲבָל שֵׁירוּתָא דִּרְשִׁימוּ דְּמַיִין, מִיּוֹם שֵׁנִי הֲוִי. וְהָכִי אִתְחֲזֵי, בְּגִין דְּלֵית טוֹב בַּשֵּׁנִי, וּבְגִין כָּךְ, לָא רְשִׁים רִאשׁוֹן וְלָא אֶחָד כְּלַל, וַהֲוִי בִּסְתָם, וְשָׁרֵי רְשִׁימוּ דְּיוֹמִין, בְּיוֹם שֵׁנִי. וְאִתְפְּלָגוּ מַיִם בְּבוּ\"ז, וְאִשְׁתָּאָרוּ בְּיוֹמִין חֶרֶ\"שׂ, כְּמָה דְּאִתְּמַר, וְכֹלָּא כַּדְּקָא יֵאוֹת."],[[0,"אר\"ש, אלעזר","וכו': א\"ר שמעון אלעזר, בוא וראה. מיום השני התחילו המים להראות, דהיינו שהתחיל ניסוך המים על המזבח. שהיה ג\"כ בשביל להמשיך חיות וקיום לס\"א (כמ\"ש להלאה באות תת\"צ) ואם צמא השקהו מים אלין מים דרשימין הכא ביומי דחג. כיון שהתחילו המים, והס\"א וע' אומות קבלו השפע, אז נתגברו, כנ\"ל בדבור הסמוך, ומיום השלישי המלכות שרתה עליהם, שהמשיכו אותה בפרוד מז\"א, כנ\"ל. ואלו המים, לא היו יודעים הבבלים, למה הם רשומים כאן בחג, כלומר שלא היו יודעים, שהם לתת קיום לאומות העולם, שהרי הטוב של ישראל אינו במקום המיעוט, דהיינו בפרי החג המתמעטים, אלא במקום הריבוי, ומשום שאלו מים הרשומים כאן, מתמעטים, ביחד עם פרי החג, בא הכתוב להשמיענו, שכתוב, \u0003והמים\u0004 דהיינו המים הידועים של ימי החג, אלו הרשומים בתוך הקרבנות, כי ביום השני כתוב בקרבנות ונסכיה \u0003מ\u0004 עם \u0003מ',\u0004 ובששי, נאמר ונסכיה עם \u0003י',\u0004 ובשביעי כתוב כמשפט \u0003ם\u0004 עם \u0003ם',\u0004 הרי כאן מים, שמכאן רמז לניסוך המים מן התורה, (כמ\"ש תענית ב:) שהם, הקרבנות, הרי קללות, היו הלוך וחסור, (כנ\"ל אות תתפ\"ד) והטוב שלהם, והשפע הנמשך עליהם \u0003היו הלוך וחסור.\u0004 ומשום שאלו המים הם שלהם, של האומות וס\"א, לא נתחברו האותיות \u0003מים\u0004 שיהיו כתובים בתורה בפירוש. אלא הם מפוזרות, כי \u0003ם'\u0004 היא בנסכיה \u0003ם,\u0004 וה \u0003י'\u0004 בונסכ \u0003י\u0004 ה, וה \u0003ם'\u0004 הסופית בכמשפט \u0003ם\u0004 כנ\"ל. שהוא כדי שלא יתחבר הטוב שלהם, אלא יהיה מעט מעט."],[1,"אבל לישראל דאינון","וכו': אבל לישראל, שהם מהקב\"ה, שהוא קו האמצעי, מה כתוב, ודורשי ה' לא יחסרו כל טוב. התחלת הכתוב הוא, \u0003כפירים רשו ורעבו,\u0004 אלו הם הממונים של שאר העמים. \u0003ודורשי ה',\u0004 אלו הם ישראל, \u0003לא יחסרו כל טוב,\u0004 אלו הולכים ומתעלים למעלה למעלה. כי מעלין בקודש ואין מורידין. ומשום זה הטוב שלהם של האומות והס\"א, שהם מים, היו הלוך וחסור עד חדש העשירי, שזה טבת, כי אז הם ימי הרעה. כי חדשי טבת שבט הם ימי דין ונקראים ימי הרעה (כמ\"ש בזוהר חדש יתרו ל\"ו ע\"ב.) ורעה הזו מתעוררת ומתחזקת והכלה הקדושה, שהיא המלכות אינה מאירה מתוך השמש, דהיינו שהיא נפרדת מן השמש, שהוא ז\"א, אז נראו ראשי ההרים אלו, שהם הדינים דשמאל הנמשכים עם פרי החג, שהם אלו הרי חשך והרי קללות, הנראים ומתחזקים ועושים רעות בעולם."],[2,"ביומין אלין אשה","וכו': בימים אלו, דחג הסוכות, כתוב אשה, בעולה הזו שבהם, דהיינו שכתוב, והקרבתם עולה \u0003אשה\u0004 וגו'. כי אז אלו אשים שהם הדינים (כנ\"ל אות תתע\"ט) אוכלים חלקיהם, ע' פרים אלו הם כנגד ע' ממונים השולטים על ע' אומות. ומספרם עולה ביום הראשון, ויורדים ומתמעטים בכל יום ויום. ונקראים פרים מנגחים בימים שלהם. אילים (יש כאן חסר, וצ\"ל) שנים. כבשים בני שנה ארביסר. אילים שנים בכל יום הם \u0003י\"ד\u0004 הויה. כי ז' פעמים ב' הוא י\"ד. והוא יד השולטת עליהם תמיד בכל יום ויום. כבשים בני שנה, המספר שלהם ח\"צ. דהיינו ז' פעמים י\"ד הם צ\"ח."],[3,"ואי תימא אי","וכו': ואם תאמר אם כן, שאנו מקריבים י\"ד אילים שתשלוט יד ה', \u0003וח\"ץ\u0004 כבשים, שזה סימן רע. שהיא כנגד צ\"ח קללות שבתוכחה, וכן יפלח כ \u0003חץ\u0004 כבדם. הנה רע עין אם אליהם, שאכול ושתה יאמר לו ולבו בל עמו. ומשיב כן. כי כתוב, אם רעב שונאך וגו', כי גחלים אתה חותה על ראשו. אבל אנו איננו נותנים אלא בשמחה, כי אין בימי השנה, שמחה, כמו בימים אלו דסוכות, ומשום שאנחנו נותנים בטוב לב ובשמחה ורצון, מתהפך מתנותינו אליהם לגחלים על ראשם, גחלים בוערות, שהשמחה שלנו עושה להם רע, דהיינו י\"ד אילים, ע' פרים, ח\"ץ כבשים, שכך עולה החשבון של הקרבנות שלהם. כי הי\"ד אילים יורה על י\"ד הויה השולטת בהם. וע' פרים, שהולכים ומתמעטים, יורה שהטוב שלהם ילך ויתמעט. וח\"ץ כבשים יורה על מספר צ\"ח קללות להשרות בהם. או יפלח כ \u0003חץ\u0004 כבדם."],[4,"וכל דא איתימא","וכו': וכל זה, אם תאמר, מי נותן אותנו להקריב עליהם, על הממונים של ע' אומות, אולי אינם רוצים כל זה. אלא אין שמחה לכל אלו הממונים, כמו בכל אלו הפרים ואילים וכבשים, בשעה שישראל נותנים להם סעודות אלו. ועם כל זה אין הכל נקרב אלא אל הקב\"ה בלבד, והם, הממונים, מתקרבים שם, והקב\"ה מחלק להם. ועל זה כתוב, אם רעב שונאך האכילהו לחם, אלו הם קרבנות החג. ואם צמא השקהו מים, אלו הם המים הרשומים כאן לנסכם בימי החג, ביום השני, וביום הששי וביום השביעי. והסימן \u0003בוז\u0004 יבוזו לו. שהוא ראשי תיבות \u0003ב' ו' ז'.\u0004"],[5,"מים רבים","וגו': מים רבים לא יוכלו לכבות את האהבה, אלו הם המים שישראל מנסכים בשמחה ובאהבת הקב\"ה, שכתוב, ושאבתם מים בששון. ונהרות לא ישטפוה, אלו הם נהרות אפרסמון הטהור, דהיינו י\"ח נהרות השפע הנמשכים מיסוד הבינה (כנ\"ל שמות רנ\"ז). שכולם דבקים ומתקשרים באהבה זו, \u0003אם יתן איש את כל הון ביתו\u0004 וגו', זה סמאל, \u0003באהבה,\u0004 של ישראל, דהיינו שיהיה לו חלק עמהם באלו המים הכתובים כאן בפרשה, דהיינו, מה שכתוב אם יתן איש את כל הון ביתו באהבה \u0003בוז\u0004 וגו', שהוא סימן של אלו המים שמנסכים אותו בימי \u0003בו\"ז,\u0004 דהיינו ביום ב' וביום ו' וביום ז'. \u0003יבוזו לו\u0004 ודאי. כי כל ההון של סמאל נחשב לנו כמו \u0003חרש\u0004 הנשבר, שאין לו תקנה לעולם."],[6,"מים דלהון אתפליגו","וכו': ומפרש דבריו, מים שלהם, של סמא\"ל והס\"א והאומות, נתחלקו בימים \u0003בו\"ז,\u0004 נשארו שאר ימים, שהם שלישי רביעי חמישי, שאין בהם ניסוך המים, והסימן הוא \u0003חרש\u0004 את חרשי האדמה, אשר \u0003חרש\u0004 הוא ראשי תיבות \u0003ח\u0004 מישי \u0003ר\u0004 ביעי \u0003ש\u0004 לישי, שבאותם הימים אין ניסוך המים. ואין להם תקון עמנו, ולא לעולם. כי כמו שאין להם תקון בימים חר\"ש, כן לא יהיה להם תקון לעולם. ואם תאמר, \u0003בוז\u0004 יבוזו לו כתוב, ולפי הנ\"ל היה צריך לומר \u0003בוז\u0004 לא יבוזו לו, דהיינו שאינם רוצים בבו\"ז, שהוא הון של סמאל. ומשיב, שכתוב שם כי לא \u0003בזה\u0004 וגו'. פי', שזהו רמז שישראל אינם רוצים לותר על אהבה בשביל הארת ניסוך המים שב \u0003בו\"ז,\u0004 שהוא הון הס\"א, דהיינו שיש לסטרא אחרא חלק בהם. ויבוזו לו, אינו סובב על האור שב \u0003בוז,\u0004 אלא כפשוטו שהם מבזים לו."],[6,"","ופירוש הכתוב הוא. \u0003מים רבים לא יוכלו לכבות את האהבה,\u0004 היינו מימי החכמה שעליהם כתוב ושאבתם מים בששון ממעייני הישועה. ואע\"פ שהם חכמה אינם מכבים את החסדים הנקראים \u0003אהבה.\u0004 וכמו כן, \u0003ונהרות לא ישטפוה,\u0004 היינו נחלי אפרסמון, אע\"פ שיש בהם הארת חכמה, עכ\"ז אינם שוטפים את האהבה, דהיינו שאין ממעטים את החסדים. אבל אם יתן איש, שזה סמאל, \u0003את כל הון ביתו\u0004 דהיינו כל האורות שיש לו \u0003באהבה,\u0004 שתמורת ביטול האהבה, יתן לנו אורות ניסוך המים שבימים \u0003בוז,\u0004 כי הארת המים שבבו\"ז מתמעטת והולכת, וזה יורה שממעט האהבה, דהיינו החסדים, כי החכמה שיש בה חלק לסטרא אחרא, ממעטת תמיד החסדים, נמצא שהארת חכמה שלו מכבה את האהבה, עד שהחכמה תשאר בלי חסדים. ואז גם הארת החכמה נכבית כי אינה יכולה להאיר בלי חסדים (כנ\"ל ב\"א דף מ\"ז אות ל\"ד ד\"ה נפק) וע\"כ \u0003יבוזו לו.\u0004 משא\"כ הארת החכמה שישראל מקבלים, אין מכבים את החסדים שה\"ס אהבה."],[7,"יומא קדמאה מאי","וכו': שואל, יום הראשון של החג, מה הוא עושה. כי חושב ימי \u0003בו\"ז\u0004 דחג לניסוך המים, וימי \u0003חר\"ש\u0004 דחג לימים פנוים מניסוך המים, ויום הראשון של החג אינו מזכיר כלום, ומשיב, שיום הראשון לא נקרא ראשון, ולא נקרא אחד, אלא שנקרא חמשה עשר סתם. בלי ציון מיוחד כלל, כי אין בו דבר מיוחד לציון. אבל התחלת הציון של ניסוך המים הוא ביום שני, וכך ראוי להיות, כיון שנותנים בו חלק לסטרא אחרא, ראוי להיות ביום שני, שלא נאמר בו כי טוב בשני. ומשום זה אינו מציין כלל יום ראשון, ולא אחד, והוא חמשה עשר סתם, ותחילת הציון והחידוש של הימים מתחיל ביום שני. ומחלקים המים בימים \u0003בו\"ז,\u0004 ונשארו פנוים בימים \u0003חר\"ש,\u0004 כמו שלמדנו, והכל כראוי."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, בֹּא וּרְאֵה, מִיּוֹם שֵׁנִי מַתְחִילִים הַמַּיִם לְהֵרָאוֹת. כֵּיוָן שֶׁהִתְחִילוּ הַמַּיִם - מִיּוֹם שְׁלִישִׁי הִיא שׁוֹרָה עֲלֵיהֶם, וְאֵלּוּ הַמַּיִם לֹא הָיוּ יוֹדְעִים הַבַּבְלִים (בכל) מַדּוּעַ רְשׁוּמִים כָּאן, שֶׁהֲרֵי הַטּוֹב שֶׁל יִשְׂרָאֵל אֵינוֹ בִּמְקוֹם הַמִּעוּט, אֶלָּא בִּמְקוֹם הָרִבּוּי. וּמִפְּנֵי שֶׁאֵלּוּ הַמַּיִם שֶׁרְשׁוּמִים כָּאן מִתְמַעֲטִים, בָּא הַפָּסוּק לְהַשְׁמִיעֵנוּ, שֶׁכָּתוּב וְהַמַּיִם, אֵלּוּ שֶׁיְּדוּעִים בִּימֵי הֶחָג, אֵלּוּ שֶׁרְשׁוּמִים תּוֹךְ הַקָּרְבָּנוֹת, שֶׁהֵם הָרֵי קְלָלוֹת, הָיוּ הָלוֹךְ וְחָסוֹר הַטּוֹב שֶׁלָּהֶם. וּמְשִׁיכָה שֶׁנִּמְשֶׁכֶת עֲלֵיהֶם הָיוּ הָלוֹךְ וְחָסוֹר. וּמִפְּנֵי שֶׁאֵלּוּ הַמַּיִם שֶׁלָּהֶם הוּא, לֹא מִתְחַבְּרוֹת אוֹתִיּוֹת, שֶׁלֹּא יִתְחַבֵּר הַטּוֹב שֶׁלָּהֶם אֶלָּא מְעַט מְעַט."],[1,"","אֲבָל לְיִשְׂרָאֵל, שֶׁהֵם מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, מַה כָּתוּב? (תהלים לד) וְדֹרְשֵׁי ה' לֹא יַחְסְרוּ כָל טוֹב. רֹאשׁ הַפָּסוּק - כְּפִירִים רָשׁוּ וְרָעֵבוּ - אֵלּוּ הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים. וְדֹרְשֵׁי ה' - אֵלּוּ יִשְׂרָאֵל - לֹא יַחְסְרוּ כָל טוֹב. אֵלּוּ הוֹלְכִים וְעוֹלִים לְמַעְלָה לְמַעְלָה. וּמִשּׁוּם כָּךְ הַטּוֹב שֶׁלָּהֶם, שֶׁהֵם מַיִם, הָיוּ הָלוֹךְ וְחָסוֹר, עַד הַחֹדֶשׁ הָעֲשִׂירִי, זֶה טֵבֵת, שֶׁהֲרֵי אָז יְמֵי הָרָעָה הֵם, וּמִתְעוֹרֶרֶת אוֹתָהּ רָעָה וּמִתְחַזֶּקֶת, וְהַכַּלָּה הַקְּדוֹשָׁה לֹא מְאִירָה מִתּוֹךְ הַשֶּׁמֶשׁ. אָז נִרְאוּ רָאשֵׁי הֶהָרִים, אֵלּוּ הֵם הָרֵי הַחֹשֶׁךְ, הָרֵי הַקְּלָלוֹת נִרְאִים וּמִתְחַזְּקִים וְעוֹשִׂים רָעוֹת בָּעוֹלָם."],[2,"","בְּיָמִים אֵלּוּ אִשֶּׁה בְּזוֹ הָעוֹלָה, שֶׁהֲרֵי אָז אֵלּוּ הָאִשִּׁים אוֹכְלִים חֶלְקָם. שִׁבְעִים פָּרִים אֵלּוּ הֵם כְּנֶגֶד שִׁבְעִים מְמֻנִּים שֶׁשּׁוֹלְטִים עַל שִׁבְעִים עַמִּים, וְעוֹלִים בְּיוֹם רִאשׁוֹן, וְיוֹרְדִים בְּכָל יוֹם וָיוֹם, וְנִקְרָאִים פָּרִים מְנַגְּחִים בַּיָּמִים שֶׁלָּהֶם. אֵילִם אַרְבָּעָה עָשָׂר, שְׁנַיִם בְּכָל יוֹם הֵם יַ\"ד יְהֹוָ\"ה. יָד שֶׁשּׁוֹלֶטֶת עֲלֵיהֶם תָּדִיר, בְּכָל יוֹם וָיוֹם. כְּבָשִׂים בְּנֵי שָׁנָה, הַמִּנְיָן שֶׁלָּהֶם חֵ\"ץ."],[3,"","וְאִם תֹּאמַר, אִם כָּךְ, רַע עַיִן אָנוּ אֶצְלָם - כֵּן, שֶׁהֲרֵי כָּתוּב (משלי כה) כִּי גֶחָלִים אַתָּה חֹתֶה עַל רֹאשׁוֹ. אֲבָל אֲנַחְנוּ לֹא נוֹתְנִים אֶלָּא בְּשִׂמְחָה, שֶׁאֵין בִּימֵי הַשָּׁנָה שִׂמְחָה כְּאֵלּוּ הַיָּמִים. וּמִפְּנֵי שֶׁאֲנַחְנוּ נוֹתְנִים בְּטוּב לֵב וּבְשִׂמְחָה שֶׁל רָצוֹן - מִתְהַפֵּךְ עֲלֵיהֶם גֶּחָלִים עַל רָאשֵׁיהֶם, גֶּחָלִים לוֹהֲטוֹת שֶׁל הַשִּׂמְחָה שֶׁלָּנוּ עוֹשׂוֹת לָהֶם רָע. י\"ד (ה'), ע', וח\"ץ, כָּךְ עוֹלִים בַּחֶשְׁבּוֹן שֶׁלָּהֶם."],[4,"","וְכָל זֶה אִם תֹּאמַר מִי נָתַן לָנוּ לְהַקְרִיב עֲלֵיהֶם, אוּלַי הֵם לֹא רוֹצִים אֶת כָּל זֶה? אֶלָּא אֵין שִׂמְחָה לְכָל אֵלּוּ הַמְמֻנִּים בְּכָל אֵלּוּ הַתּוֹרִים, הָאֵילִים, וְהַכְּבָשִׂים כְּאֵלּוּ, בְּשָׁעָה שֶׁיִּשְׂרָאֵל נָתְנוּ לָהֶם סְעוּדוֹת אֵלּוּ. וְעִם כָּל זֶה לֹא קָרֵב הַכֹּל אֶלָּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ, וְהֵם מִתְקָרְבִים שָׁם וְהוּא מְחַלֵּק לָהֶם. וְעַל זֶה כָּתוּב, (שם) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִלֵהוּ לָחֶם - אֵלּוּ הֵם קָרְבְּנוֹת הֶחָג. וְאִם צָמֵא הַשְׁקֵהוּ מָיִם - אֵלּוּ מַיִם שֶׁרְשׁוּמִים כָּאן בִּימֵי הֶחָג, וּבְיוֹם שֵׁנִי, וּבְיוֹם שִׁשִּׁי וּשְׁבִיעִי, וְסִימָן - (שיר השירים ח) בּוֹ\"ז יָבוּזוּ לוֹ."],[5,"","מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה - אֵלּוּ הֵם מַיִם אֲשֶׁר מְנַסְּכִים יִשְׂרָאֵל בְּשִׂמְחָה וּבְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (ישעיה יב) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן. וּנְהָרוֹת לֹא יִשְׁטְפוּהָ - אֵלּוּ הֵם נַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר, שֶׁכֻּלָּם דְּבוּקִים וּמִתְקַשְּׁרִים בְּאַהֲבָה זוֹ. אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה בּוֹז יָבוּזוּ - זֶה סָמָאֵל, בְּאַהֲבַת יִשְׂרָאֵל, לִהְיוֹת לוֹ חֵלֶק אִתָּם בְּאֵלּוּ הַמַּיִם שֶׁרְשׁוּמִים כָּאן בַּפָּרָשָׁה, שֶׁכָּתוּב אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה בּוֹז יָבוּזוּ, סִימָן שֶׁל אֵלּו הַמַּיִם בּוֹ\"ז - יָבוּזוּ לוֹ וַדַּאי, שֶׁהֲרֵי כֻּלָּם נֶחְשָׁבִים אֶצְלֵנוּ חֶרֶשׂ נִשְׁבָּר, שֶׁאֵין לוֹ תַּקָּנָה לְעוֹלָמִים."],[6,"","הַמַּיִם שֶׁלָּהֶם נֶחֱלָקִים בִּימֵי בּוֹ\"ז. נִשְׁאֲרוּ שְׁאָר יָמִים, שֶׁהֵם ג' ד' ה' (נוטריקון) חֲמִישִׁי רְבִיעִי שְׁלִישִׁי, וְסִימָן - (ישעיה מה) חֶרֶ\"שׂ אֶת חַרְשֵׂי (ה) אֲדָמָה, וְאֵין לָהֶם תִּקּוּן אִתָּנוּ וְלֹא לְעוֹלָמִים. וְאִם תֹּאמַר, בּוֹז יָבוּזוּ לוֹ כָּתוּב שָׁם, (תהלים כב) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת."],[7,"","יוֹם רִאשׁוֹן מָה עוֹשֶׂה לוֹ? אֶלָּא לֹא נִקְרָא רִאשׁוֹן וְלֹא נִקְרָא אֶחָד, אֶלָּא חֲמִשָּׁה עָשָׂר סְתָם, בְּלִי רִשּׁוּם כְּלָל. אֲבָל הַתְחָלַת רִשּׁוּם הַמַּיִם מִיּוֹם שֵׁנִי הוּא. וְכָךְ רָאוּי, מִפְּנֵי שֶׁאֵין טוֹב בַּשֵּׁנִי, וּמִשּׁוּם כָּךְ לֹא רָשׁוּם רִאשׁוֹן וְלֹא אֶחָד כְּלָל, וְהוּא בִּסְתָם, וּמַתְחִיל רִשּׁוּם הַיָּמִים בְּיוֹם שֵׁנִי. וְנֶחְלְקוּ מַיִם בְּבוֹ\"ז, וְנִשְׁאֲרוּ בִּימֵי חֶרֶ\"שׂ, כְּמוֹ שֶׁנֶּאֱמַר, וְהַכֹּל כְּמוֹ שֶׁצָּרִיךְ."]]],[["זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּיַדְעֵי לְאַעְלָאָה לְגוֹ מוֹחָא דֶּאֱגוֹזָא. וּבְגִין לְמֵיעָאל לְגוֹ מוֹחָא, מְתַבְּרִין קְלִיפִין אִלֵּין, וְעָאלִין. מַה כְּתִיב לְבָתַר כָּל הַאי. בַּיוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. לְבָתַר דְּתַבְרוּ כָּל הָנֵי קְלִיפִין, וְתַבְרוּ כַּמָה גְּזִּיזִין, וְכַמָּה נְחָשִׁים קַטְלוּ, וְכַמָּה עַקְרַבִּים דַּהֲווֹ לוֹן בְּאִינּוּן טוּרֵי דַּחֲשׁוֹכָא, עַד דְּאַשְׁכָּחוּ אֲתָר דִּישׁוּבָא, וְקַרְתָּא קַדִּישָׁא, מַקְפָּא שׁוּרִין סְחוֹר סְחוֹר, כְּדֵין עָאלוּ לְגַבָּהּ, לְמֶעְבַּד נַיְיחָא תַּמָּן, וּלְמֵחדֵי בָּהּ. וְהָא אוֹקִימְנָא מִלָּה.","וְדָא אִיהוּ עֲצֶרֶת, כְּנִישׁוּ. אֲתָר דְּמִתְכְּנַשׁ כֹּלָּא לְגַבָּהּ. תִּהְיֶה לָכֶם, וְלָא לְאַחֲרָא, לְמֶחְדֵּי אַתּוּן בְּמָארֵיכוֹן, וְאִיהוּ בַּהֲדַיְיכוּ. וְעַל דָּא כְּתִיב, (תהילים ל״ב:י״א) שִׂמְחוּ בַּיְיָ וְגִילוּ צַדִּיקִים וְהַרְנִינוּ כָּל יִשְׁרֵי לֵב. אמר ר' שמעון כל מאן דחדי וכו' עד שלא עשו חסד עם העניים (נדפס בהקדמת בראשית דף י' ע\"ב)"],[[0,"זכאה חולקהון דישראל","וכו': אשרי חלקם של ישראל, שיודעים לכנוס לתוך מוח האגוז, כלומר שהקדושה היא כמו מוח האגוז שקליפות מסבבים אותו, ובכדי לכנוס לתוך המוח, הם משברים הקליפות האלו שמסבבים אותו, ונכנסים. מה כתוב, לאחר כל זה. ביום השמיני עצרת תהיה לכם. כי אחר ששברו כל אלו הקליפות, ושברו כמה כחות, והרגו כמה נחשים וכמה עקרבים שהיו להם באלו הרי חשך, עד שמצאו מקום ישוב ועיר קדוש, שהיא המלכות הקדושה, מוקפת חומות סביב סביב, אז נכנסו אליה בשמיני עצרת, לעשות נחת לה שמה, ולשמוח בה. וכבר העמדו הדבר (עי' לעיל אות ל\"ג). כחות כמו תברא ר\"ע לגזיזיה (סנהדרין ז')."],[1,"ודא איהו עצרת","וכו': וזה הוא \u0003עצרת,\u0004 שפירושו אסיפה, דהיינו המלכות, שהיא מקום שמתאסף הכל אצלה, כי היא בית קבול לכל האורות העליונים. \u0003תהיה לכם,\u0004 היינו ולא לאחר, שאין לס\"א חלק בו, אלא שאתם תשמחו באדונכם והוא עמכם. וע\"ז כתוב, שמחו בה' וגילו צדיקים והרנינו כל ישרי לב."]],[[0,"","אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁיּוֹדְעִים לְהִכָּנֵס לְתוֹךְ מֹחַ הָאֱגוֹז, וּכְדֵי לְהִכָּנֵס לְתוֹךְ הַמֹּחַ מְשַׁבְּרִים קְלִפּוֹת אֵלּוּ וְנִכְנָסִים. מַה כָּתוּב לְאַחַר כָּל זֶה? בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. לְאַחַר שֶׁשָּׁבְרוּ כָּל אֵלּוּ הַקְּלִפּוֹת, וְשָׁבְרוּ כַּמָּה חֲתִיכוֹת, וְכַמָּה נְחָשִׁים הָרְגוּ, וְכַמָּה עַקְרַבִּים שֶׁהָיוּ לָהֶם בְּאֵלּוּ הָרֵי הַחֹשֶׁךְ, עַד שֶׁמָּצְאוּ מְקוֹם יִשּׁוּב וְעִיר קְדוֹשָׁה מֻקֶּפֶת חוֹמוֹת סָבִיב סָבִיב - אָז נִכְנָסִים אֶצְלָהּ, לַעֲשׂוֹת מְנוּחָה שָׁם וְלִשְׂמֹחַ בָּהּ. וַהֲרֵי בֵּאַרְנוּ הַדָּבָר."],[1,"","וְזְהִוּ עֲצֶרֶת, אֲסֵיפָה, מָקוֹם שֶׁנֶּאֱסָף הַכֹּל אֶצְלָהּ. תִּהְיֶה לָכֶם, וְלֹא לְאַחֵר, לִשְׂמֹחַ אִתָּם בַּאֲדוֹנְכֶם, וְהוּא אִתְּכֶם. וְעַל כֵּן כָּתוּב, (תהלים לב) שִׂמְחוּ בַה' וְגִילוּ צַדִּיקִים וְהַרְנִינוּ כָּל יִשְׁרֵי לֵב."]]]]};
